INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '9aa54139-ead5-5352-9122-a889379b5f42', id, 'ishraq-duha-prayer', '{"bn": "ইশরাক ও চাশতের নামাজ", "en": "Ishraq and Duha Prayer"}', '{"bn": "সূর্য ওঠার পর থেকে দুপুরের আগ পর্যন্ত পড়া নফল নামাজ: ইশরাক, চাশত (দুহা) ও আওয়াবিন।", "en": "Voluntary prayer between sunrise and noon: ishraq, duha and salat al-awwabin."}', 'basic', '[{"type": "text", "text": {"bn": "সালাতুদ দুহা (চাশতের নামাজ) সূর্য ওঠার পর থেকে দুপুরে সূর্য মাথার ওপর আসার (জাওয়াল) একটু আগ পর্যন্ত পড়া যায়। অনেক আলেমের মতে এই সময়ের শুরুর দিকে, সূর্য ওঠার প্রায় ১৫–২০ মিনিট পর পড়া নামাজকেই ‘ইশরাক’ বলা হয়।", "en": "Salat al-duha is prayed from after sunrise until just before the sun reaches its zenith (zawal). Many scholars say the prayer at the start of this period, about 15–20 minutes after sunrise, is what is called ''ishraq''."}}, {"type": "heading", "text": {"bn": "ফজিলত", "en": "Virtue"}}, {"type": "list", "items": [{"bn": "মানুষের শরীরের প্রতিটি জোড়ার জন্য প্রতিদিন সদকা দেওয়া কর্তব্য; চাশতের দুই রাকাত নামাজ এর জন্য যথেষ্ট (সহিহ মুসলিম ৭২০)।", "en": "Every joint owes a charity each day, and two rak''ahs of duha suffice for it (Sahih Muslim 720)."}, {"bn": "আবু হুরায়রা (রা.)-কে নবীজি (সা.) তিনটি বিষয়ের ওসিয়ত করেছেন: প্রতি মাসে তিন রোজা, চাশতের দুই রাকাত এবং ঘুমের আগে বিতর (সহিহ বুখারি ১১৭৮)।", "en": "The Prophet advised Abu Hurayrah: three fasts a month, two rak''ahs of duha, and witr before sleeping (Sahih al-Bukhari 1178)."}, {"bn": "মক্কা বিজয়ের দিন নবীজি (সা.) চাশতের সময় আট রাকাত পড়েছেন (সহিহ বুখারি ১১৭৬; সহিহ মুসলিম ৩৩৬)।", "en": "On the day of the conquest of Makkah the Prophet prayed eight rak''ahs at duha time (Sahih al-Bukhari 1176; Sahih Muslim 336)."}]}, {"type": "heading", "text": {"bn": "রাকাত ও সময়", "en": "Rak''ahs and time"}}, {"type": "table", "head": [{"bn": "বিষয়", "en": "Item"}, {"bn": "বিবরণ", "en": "Details"}], "rows": [[{"bn": "রাকাত", "en": "Rak''ahs"}, {"bn": "সর্বনিম্ন ২; ৪, ৬ বা ৮ রাকাতও পড়া যায়, দুই দুই করে", "en": "Minimum 2; 4, 6 or 8 also, two at a time"}], [{"bn": "শুরুর সময়", "en": "Starts"}, {"bn": "সূর্য ওঠার প্রায় ১৫–২০ মিনিট পর (মাকরুহ সময় শেষ হলে)", "en": "About 15–20 minutes after sunrise (when the disliked time ends)"}], [{"bn": "উত্তম সময়", "en": "Best time"}, {"bn": "রোদ কিছুটা তেতে উঠলে, অর্থাৎ সকাল ও দুপুরের মাঝামাঝি", "en": "When the sun has grown hot, around mid-morning"}], [{"bn": "শেষ সময়", "en": "Ends"}, {"bn": "জাওয়ালের (ঠিক দুপুর) কিছুক্ষণ আগে", "en": "A little before zawal (true noon)"}]]}, {"type": "text", "text": {"bn": "‘আওয়াবিনের নামাজ হলো যখন উটের বাচ্চার পা গরম বালুতে পুড়তে থাকে’ (সহিহ মুসলিম ৭৪৮)। অর্থাৎ চাশতের সবচেয়ে উত্তম সময় হলো সকাল গড়িয়ে রোদ বেশ চড়া হলে।", "en": "''The prayer of the awwabin is when the young camels feel the heat of the sand'' (Sahih Muslim 748), i.e. the best duha time is mid-morning when the sun is hot."}}, {"type": "note", "tone": "info", "text": {"bn": "বাংলাদেশে অনেকে মাগরিবের পর ছয় রাকাত নফলকে ‘আওয়াবিন’ বলেন। মাগরিবের পর নফল পড়া ভালো কাজ, তবে এর বিশেষ ফজিলতের হাদিসগুলো দুর্বল; আর সহিহ হাদিসে ‘আওয়াবিনের নামাজ’ বলা হয়েছে চাশতের নামাজকে (সহিহ মুসলিম ৭৪৮)।", "en": "In Bangladesh many call six nafl rak''ahs after Maghrib ''awwabin''. Nafl after Maghrib is good, but the hadiths on its special reward are weak, and the sahih hadith uses ''prayer of the awwabin'' for duha (Sahih Muslim 748)."}}, {"type": "heading", "text": {"bn": "ইশরাকের ফজিলতের হাদিস", "en": "The hadith on ishraq"}}, {"type": "text", "text": {"bn": "আনাস (রা.) থেকে বর্ণিত: যে ব্যক্তি জামাতে ফজর পড়ে সূর্য ওঠা পর্যন্ত বসে আল্লাহর জিকির করে, তারপর দুই রাকাত নামাজ পড়ে, সে পূর্ণ হজ ও উমরার সওয়াব পায় (জামে তিরমিজি ৫৮৬)।", "en": "Anas reported: whoever prays Fajr in congregation, sits remembering Allah until sunrise, then prays two rak''ahs, has the reward of a complete Hajj and ''Umrah (Jami'' al-Tirmidhi 586)."}}, {"type": "note", "tone": "info", "text": {"bn": "ইমাম তিরমিজি এই হাদিসকে ‘হাসান গরিব’ বলেছেন। শাইখ আলবানিসহ কেউ কেউ একে হাসান বলেছেন, আবার কিছু মুহাদ্দিস সনদকে দুর্বল বলেছেন। আমলটি নিজে ভালো; তবে ফজিলত বর্ণনায় এই মতভেদ মনে রাখুন।", "en": "Al-Tirmidhi called it hasan gharib; al-Albani and others graded it hasan, while some scholars judged its chain weak. The practice itself is good; keep this grading difference in mind."}}, {"type": "note", "tone": "tip", "text": {"bn": "নিয়ত মনে মনে করাই যথেষ্ট। উদাহরণ (প্রচলিত বাংলা): ‘আমি আল্লাহর জন্য দুই রাকাত চাশতের নফল নামাজ পড়ছি।’", "en": "The intention in the heart is enough. Example (common Bangla phrasing): ''I am praying two rak''ahs of duha for Allah.''"}}]', 'in_review', 60 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '9dfc6cb5-b4df-534d-8fc7-4221275a1718', id, 'istikhara-prayer', '{"bn": "ইস্তিখারার নামাজ ও দোয়া", "en": "Istikhara Prayer and Du''a"}', '{"bn": "কোনো বৈধ কাজে সিদ্ধান্ত নিতে আল্লাহর কাছে কল্যাণ চাওয়ার সুন্নত পদ্ধতি: দুই রাকাত নামাজ ও পূর্ণ দোয়া।", "en": "The sunnah way to ask Allah for what is best before a permissible decision: two rak''ahs and the full du''a."}', 'basic', '[{"type": "text", "text": {"bn": "ইস্তিখারা মানে আল্লাহর কাছে কল্যাণ চাওয়া। বিয়ে, চাকরি, ব্যবসা, সফর ইত্যাদি যেকোনো বৈধ বিষয়ে কোনটি ভালো বুঝতে না পারলে ইস্তিখারা করা সুন্নত। জাবির (রা.) বলেন, নবীজি (সা.) আমাদের সব বিষয়ে ইস্তিখারা এমনভাবে শেখাতেন, যেমন কুরআনের সূরা শেখাতেন।", "en": "Istikhara means asking Allah for good. It is sunnah for any permissible matter you are unsure about: marriage, a job, business, travel. Jabir said the Prophet taught it for all matters as he taught a surah of the Quran."}}, {"type": "heading", "text": {"bn": "পদ্ধতি", "en": "Method"}}, {"type": "step", "title": {"bn": "ওযু", "en": "Wudu"}, "text": {"bn": "ভালোভাবে ওযু করুন।", "en": "Make wudu properly."}}, {"type": "step", "title": {"bn": "দুই রাকাত নফল", "en": "Two rak''ahs of nafl"}, "text": {"bn": "ফরজ ছাড়া দুই রাকাত নফল নামাজ পড়ুন। যেকোনো সূরা পড়া যায়; নির্দিষ্ট সূরা হাদিসে বর্ণিত নেই। মাকরুহ সময় এড়িয়ে চলুন।", "en": "Pray two non-obligatory rak''ahs. Any surah may be recited; no specific surah is narrated. Avoid the disliked times."}}, {"type": "step", "title": {"bn": "দোয়া", "en": "The du''a"}, "text": {"bn": "সালাম ফিরিয়ে আল্লাহর প্রশংসা ও দরুদ পড়ে নিচের দোয়াটি পড়ুন। ‘হাযাল আমরা’ (এই বিষয়টি) বলার সময় মনে মনে আপনার বিষয়টি স্মরণ করুন বা নাম উল্লেখ করুন।", "en": "After salam, praise Allah, send durood, then recite the du''a below. At ''hadhal-amra'' (this matter), name or bring to mind your matter."}}, {"type": "arabic", "label": {"bn": "ইস্তিখারার দোয়া", "en": "Du''a of istikhara"}, "ar": "اللّٰهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ، وَتَعْلَمُ وَلَا أَعْلَمُ، وَأَنْتَ عَلَّامُ الْغُيُوبِ. اللّٰهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هٰذَا الْأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي، فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي، ثُمَّ بَارِكْ لِي فِيهِ. وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هٰذَا الْأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي، فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِيَ الْخَيْرَ حَيْثُ كَانَ، ثُمَّ أَرْضِنِي بِهِ", "pron": {"bn": "আল্লাহুম্মা ইন্নী আসতাখীরুকা বিইলমিকা, ওয়া আসতাকদিরুকা বিকুদরাতিকা, ওয়া আসআলুকা মিন ফাদলিকাল আযীম। ফাইন্নাকা তাকদিরু ওয়া লা আকদিরু, ওয়া তা''লামু ওয়া লা আ''লামু, ওয়া আনতা আল্লামুল গুয়ূব। আল্লাহুম্মা ইন কুনতা তা''লামু আন্না হাযাল আমরা খাইরুল লী ফী দীনী ওয়া মাআশী ওয়া আকিবাতি আমরী, ফাকদুরহু লী ওয়া ইয়াসসিরহু লী, সুম্মা বারিক লী ফীহ। ওয়া ইন কুনতা তা''লামু আন্না হাযাল আমরা শাররুল লী ফী দীনী ওয়া মাআশী ওয়া আকিবাতি আমরী, ফাসরিফহু আন্নী ওয়াসরিফনী আনহু, ওয়াকদুর লিয়াল খাইরা হাইসু কানা, সুম্মা আরদিনী বিহ।", "en": "Allahumma inni astakhiruka bi''ilmika, wa astaqdiruka biqudratika, wa as''aluka min fadlikal-''azim, fa innaka taqdiru wa la aqdiru, wa ta''lamu wa la a''lamu, wa anta ''allamul-ghuyub. Allahumma in kunta ta''lamu anna hadhal-amra khayrun li fi dini wa ma''ashi wa ''aqibati amri, faqdurhu li wa yassirhu li, thumma barik li fih. Wa in kunta ta''lamu anna hadhal-amra sharrun li fi dini wa ma''ashi wa ''aqibati amri, fasrifhu ''anni wasrifni ''anhu, waqdur liyal-khayra haythu kana, thumma ardini bih."}, "meaning": {"bn": "হে আল্লাহ, আমি তোমার জ্ঞানের ওসিলায় তোমার কাছে কল্যাণ চাই, তোমার কুদরতের ওসিলায় তোমার কাছে শক্তি চাই এবং তোমার মহান অনুগ্রহ প্রার্থনা করি। কারণ তুমি ক্ষমতা রাখো, আমি রাখি না; তুমি জানো, আমি জানি না; আর তুমি সকল অদৃশ্য বিষয়ে সম্যক জ্ঞাত। হে আল্লাহ, যদি তুমি জানো যে এই কাজটি আমার দ্বীন, আমার জীবন-জীবিকা ও আমার পরিণামের জন্য কল্যাণকর, তবে এটি আমার জন্য নির্ধারণ করো, সহজ করে দাও, তারপর এতে বরকত দাও। আর যদি জানো যে এই কাজটি আমার দ্বীন, জীবন-জীবিকা ও পরিণামের জন্য অকল্যাণকর, তবে এটিকে আমার থেকে ফিরিয়ে দাও এবং আমাকেও এ থেকে ফিরিয়ে রাখো; আর যেখানেই কল্যাণ থাকুক, তা আমার জন্য নির্ধারণ করো, তারপর তাতে আমাকে সন্তুষ্ট রাখো।", "en": "O Allah, I ask You for good through Your knowledge, and ask You for ability through Your power, and I ask You of Your great bounty; for You are able and I am not, You know and I do not, and You are the Knower of the unseen. O Allah, if You know this matter is good for me in my religion, my livelihood and the outcome of my affairs, then decree it for me, make it easy for me, and bless me in it. And if You know this matter is bad for me in my religion, my livelihood and the outcome of my affairs, then turn it away from me and turn me away from it, and decree for me the good wherever it may be, then make me content with it."}, "ref": {"bn": "সহিহ বুখারি ৬৩৮২ (জাবির রা.); একই হাদিস তাহাজ্জুদ অধ্যায়েও আছে", "en": "Sahih al-Bukhari 6382 (Jabir); also in the chapter on tahajjud"}, "check": true}, {"type": "note", "tone": "info", "text": {"bn": "হাদিসে বর্ণনাকারী ‘ওয়া আকিবাতি আমরী’-এর জায়গায় ‘আজিলি আমরী ওয়া আজিলিহ’ (আমার কাজের নিকট ও দূর ভবিষ্যৎ) বলারও উল্লেখ করেছেন। কোনো কোনো আলেম দুটোই বলতে বলেন। বুখারির আরেক বর্ণনায় শেষে ‘সুম্মা রাদ্দিনী বিহ’ আছে; অর্থ একই।", "en": "The narrator also mentions ''in the near and far future of my affairs'' instead of ''the outcome of my affairs''; some scholars advise saying both. Another narration in al-Bukhari ends ''thumma raddini bih'', with the same meaning."}}, {"type": "heading", "text": {"bn": "মনে রাখার বিষয়", "en": "Points to remember"}}, {"type": "list", "items": [{"bn": "ইস্তিখারা কেবল বৈধ (হালাল) বিষয়ে; ফরজ পালন বা হারাম বর্জনের জন্য ইস্তিখারা নেই।", "en": "Istikhara is only for permissible matters, not for doing a duty or avoiding a sin."}, {"bn": "হাদিসে ইস্তিখারার পর ঘুমানো বা স্বপ্ন দেখার কথা নেই। স্বপ্নের অপেক্ষা জরুরি নয়।", "en": "The hadith says nothing about sleeping or seeing a dream afterwards; waiting for a dream is not required."}, {"bn": "দোয়ার পর বিষয়টি ভেবে দেখুন, অভিজ্ঞ ও বিশ্বস্ত মানুষের পরামর্শ নিন, তারপর যেদিকে মন স্থির হয় ও পথ সহজ হয়, আল্লাহর ওপর ভরসা করে এগিয়ে যান।", "en": "After the du''a, think, consult experienced and trustworthy people, then proceed with what your heart settles on and what becomes easy, trusting Allah."}, {"bn": "বিষয়টি পরিষ্কার না হলে একাধিকবার ইস্তিখারা করা যায়।", "en": "You may repeat istikhara if the matter is still unclear."}, {"bn": "নারীরা ঋতুস্রাবের সময় নামাজ ছাড়া শুধু দোয়াটি পড়তে পারেন।", "en": "A woman in her period may recite the du''a without the prayer."}]}, {"type": "note", "tone": "tip", "text": {"bn": "নিয়ত মনে মনে করাই যথেষ্ট। উদাহরণ (প্রচলিত বাংলা): ‘আমি আল্লাহর জন্য দুই রাকাত ইস্তিখারার নামাজ পড়ছি।’", "en": "The intention in the heart is enough. Example (common Bangla phrasing): ''I am praying two rak''ahs of istikhara for Allah.''"}}]', 'in_review', 70 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '03d04b56-de79-5535-b575-1b15ad3dca02', id, 'salatut-tasbih', '{"bn": "সালাতুত তাসবিহ", "en": "Salat al-Tasbih"}', '{"bn": "চার রাকাতে মোট ৩০০ বার তাসবিহ পড়ার বিশেষ নফল নামাজ: পদ্ধতি, গণনার ছক এবং হাদিসটির মান নিয়ে আলোচনা।", "en": "A special voluntary prayer of four rak''ahs with 300 tasbihs: the method, a counting table, and the discussion on the hadith''s grading."}', 'detail', '[{"type": "text", "text": {"bn": "নবীজি (সা.) তাঁর চাচা আব্বাস (রা.)-কে এই নামাজ শিখিয়েছিলেন এবং বলেছিলেন, পারলে প্রতিদিন, না পারলে সপ্তাহে একবার, না পারলে মাসে একবার, না পারলে বছরে একবার, না পারলে জীবনে অন্তত একবার পড়তে।", "en": "The Prophet taught this prayer to his uncle al-''Abbas and said to pray it daily if possible, otherwise weekly, monthly, yearly, or at least once in a lifetime."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ১২৯৭; সুনান ইবনে মাজাহ ১৩৮৭ (ইবনে আব্বাস রা.); জামে তিরমিজি ৪৮২ (আবু রাফে রা.)", "en": "Sunan Abi Dawud 1297; Sunan Ibn Majah 1387 (Ibn ''Abbas); Jami'' al-Tirmidhi 482 (Abu Rafi'')"}}, {"type": "note", "tone": "info", "text": {"bn": "হাদিসটির মান নিয়ে মুহাদ্দিসদের মতভেদ আছে। একাধিক সনদের কারণে ইমাম আবু দাউদ, ইবনে হাজার আসকালানি (তাঁর কিছু লেখায়) ও শাইখ আলবানিসহ অনেকে একে হাসান বা সহিহ বলেছেন; আবদুল্লাহ ইবনুল মুবারক (রহ.) এ নামাজ পড়তেন। অন্যদিকে ইবনুল জাওযি একে জাল হাদিসের তালিকায় রেখেছেন এবং আরও কিছু আলেম দুর্বল বলেছেন। তাই কেউ পড়লে তাকে বাধা দেওয়া বা কেউ না পড়লে তাকে দোষ দেওয়া উচিত নয়।", "en": "Scholars differ on this hadith''s grading. Because of its several chains, many (including Abu Dawud, Ibn Hajar in some works, and al-Albani) graded it hasan or sahih, and ''Abdullah ibn al-Mubarak practised it. Ibn al-Jawzi listed it among fabrications and some others called it weak. So neither criticise one who prays it nor blame one who does not."}, "check": true}, {"type": "arabic", "label": {"bn": "যে তাসবিহ পড়া হয়", "en": "The tasbih"}, "ar": "سُبْحَانَ اللّٰهِ وَالْحَمْدُ لِلّٰهِ وَلَا إِلٰهَ إِلَّا اللّٰهُ وَاللّٰهُ أَكْبَرُ", "pron": {"bn": "সুবহানাল্লাহি ওয়াল হামদু লিল্লাহি ওয়া লা ইলাহা ইল্লাল্লাহু ওয়াল্লাহু আকবার।", "en": "Subhanallahi wal-hamdu lillahi wa la ilaha illallahu wallahu akbar."}, "meaning": {"bn": "আল্লাহ পবিত্র, সকল প্রশংসা আল্লাহর, আল্লাহ ছাড়া কোনো ইলাহ নেই, আল্লাহ সবচেয়ে বড়।", "en": "Glory be to Allah, all praise is for Allah, there is no god but Allah, and Allah is the Greatest."}, "ref": {"bn": "সুনান আবু দাউদ ১২৯৭", "en": "Sunan Abi Dawud 1297"}}, {"type": "heading", "text": {"bn": "চার রাকাত, প্রতি রাকাতে ৭৫ বার", "en": "Four rak''ahs, 75 per rak''ah"}}, {"type": "text", "text": {"bn": "চার রাকাত নফলের নিয়ত করুন (এক সালামে চার রাকাত, অথবা দুই দুই রাকাত করে)। প্রতি রাকাতে সূরা ফাতিহা ও আরেকটি সূরা পড়ুন। নিচের দুটি পদ্ধতির যেকোনোটিতে প্রতি রাকাতে ৭৫ বার, চার রাকাতে মোট ৩০০ বার তাসবিহ হয়। রুকু ও সিজদায় আগে স্বাভাবিক তাসবিহ (সুবহানা রাব্বিয়াল আযীম / আ''লা) পড়ে তারপর এই তাসবিহ পড়বেন।", "en": "Intend four rak''ahs of nafl (all four with one salam, or two and two). Recite al-Fatihah and a surah in each. Either method below gives 75 per rak''ah and 300 in total. In ruku'' and sajdah say the usual tasbih first, then this one."}}, {"type": "differ", "title": {"bn": "দুটি প্রচলিত পদ্ধতি", "en": "The two known methods"}, "views": [{"label": {"bn": "পদ্ধতি ১: ইবনে আব্বাস (রা.)-এর হাদিস অনুযায়ী", "en": "Method 1: per the hadith of Ibn ''Abbas"}, "text": {"bn": "কিরাতের পর দাঁড়িয়ে ১৫, রুকুতে ১০, রুকু থেকে উঠে ১০, প্রথম সিজদায় ১০, দুই সিজদার মাঝে বসে ১০, দ্বিতীয় সিজদায় ১০, দ্বিতীয় সিজদার পর দাঁড়ানোর আগে বসে ১০ = ৭৫।", "en": "After recitation standing 15; ruku'' 10; rising 10; first sajdah 10; sitting between 10; second sajdah 10; sitting after the second sajdah before standing 10 = 75."}, "evidence": {"bn": "সুনান আবু দাউদ ১২৯৭; জামে তিরমিজি ৪৮২।", "en": "Sunan Abi Dawud 1297; Jami'' al-Tirmidhi 482."}}, {"label": {"bn": "পদ্ধতি ২: আবদুল্লাহ ইবনুল মুবারক (রহ.)-এর পদ্ধতি (বাংলাদেশে বেশি প্রচলিত)", "en": "Method 2: of ''Abdullah ibn al-Mubarak (more common in Bangladesh)"}, "text": {"bn": "সানার পর কিরাতের আগে ১৫, কিরাতের পর ১০, রুকুতে ১০, রুকু থেকে উঠে ১০, প্রথম সিজদায় ১০, দুই সিজদার মাঝে ১০, দ্বিতীয় সিজদায় ১০ = ৭৫। দ্বিতীয় সিজদার পর বসে কোনো তাসবিহ নেই।", "en": "After thana before recitation 15; after recitation 10; ruku'' 10; rising 10; first sajdah 10; between sajdahs 10; second sajdah 10 = 75. Nothing in the sitting after the second sajdah."}, "evidence": {"bn": "জামে তিরমিজি ৪৮১ (ইবনুল মুবারকের বর্ণনা)।", "en": "Jami'' al-Tirmidhi 481 (Ibn al-Mubarak''s description)."}}]}, {"type": "table", "head": [{"bn": "অবস্থান", "en": "Position"}, {"bn": "পদ্ধতি ১", "en": "Method 1"}, {"bn": "পদ্ধতি ২", "en": "Method 2"}], "rows": [[{"bn": "সানার পর, কিরাতের আগে", "en": "After thana, before recitation"}, {"bn": "—", "en": "—"}, {"bn": "১৫", "en": "15"}], [{"bn": "কিরাতের পর", "en": "After recitation"}, {"bn": "১৫", "en": "15"}, {"bn": "১০", "en": "10"}], [{"bn": "রুকু", "en": "Ruku''"}, {"bn": "১০", "en": "10"}, {"bn": "১০", "en": "10"}], [{"bn": "রুকু থেকে উঠে", "en": "Standing after ruku''"}, {"bn": "১০", "en": "10"}, {"bn": "১০", "en": "10"}], [{"bn": "প্রথম সিজদা", "en": "First sajdah"}, {"bn": "১০", "en": "10"}, {"bn": "১০", "en": "10"}], [{"bn": "দুই সিজদার মাঝে", "en": "Between sajdahs"}, {"bn": "১০", "en": "10"}, {"bn": "১০", "en": "10"}], [{"bn": "দ্বিতীয় সিজদা", "en": "Second sajdah"}, {"bn": "১০", "en": "10"}, {"bn": "১০", "en": "10"}], [{"bn": "দ্বিতীয় সিজদার পর বসে", "en": "Sitting after second sajdah"}, {"bn": "১০", "en": "10"}, {"bn": "—", "en": "—"}], [{"bn": "প্রতি রাকাতে মোট", "en": "Total per rak''ah"}, {"bn": "৭৫", "en": "75"}, {"bn": "৭৫", "en": "75"}]]}, {"type": "note", "tone": "tip", "text": {"bn": "আঙুল চেপে মনে মনে গুনুন; মুখে গোনা বা তাসবিহদানা হাতে নেওয়া এড়িয়ে চলুন। কোনো জায়গায় কিছু তাসবিহ ছুটে গেলে পরের অবস্থানে তা যোগ করে নেওয়ার কথা আলেমরা বলেছেন; অনেকে বলেন, রুকু থেকে ওঠা ও দুই সিজদার মাঝের বৈঠক ছোট রাখতে সেখানে যোগ না করে পরের সিজদায় যোগ করবেন। ইবনুল মুবারক (রহ.) বলেছেন, সাহু সিজদায় এই তাসবিহ পড়তে হয় না।", "en": "Count silently by pressing your fingers; avoid counting aloud or holding beads. If you miss some in one position, scholars say to add them in the next; many say not to add them while rising or in the short sitting, but in the next sajdah. Ibn al-Mubarak said these tasbihs are not said in sajdah al-sahw."}}]', 'in_review', 80 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '885d627e-ab20-5763-afe0-38addc84ec3a', id, 'qasr-travel-prayer', '{"bn": "কসর: মুসাফিরের নামাজ", "en": "Qasr: The Traveller''s Prayer"}', '{"bn": "সফরে চার রাকাতের ফরজ নামাজ দুই রাকাত পড়ার বিধান: কত দূরত্বে, কত দিন, সুন্নত ও জামাতের মাসআলা, দুই ওয়াক্ত একসাথে পড়া।", "en": "Shortening four-rak''ah prayers to two when travelling: distance, duration, sunnahs, praying behind an imam, and combining prayers."}', 'basic', '[{"type": "arabic", "ar": "وَإِذَا ضَرَبْتُمْ فِي الْأَرْضِ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَقْصُرُوا مِنَ الصَّلَاةِ", "pron": {"bn": "ওয়া ইযা দারাবতুম ফিল আরদি ফালাইসা আলাইকুম জুনাহুন আন তাকসুরূ মিনাস সালাহ।", "en": "Wa idha darabtum fil-ardi falaysa ''alaykum junahun an taqsuru minas-salah."}, "meaning": {"bn": "আর যখন তোমরা জমিনে সফর করো, তখন নামাজ সংক্ষিপ্ত করলে তোমাদের কোনো গুনাহ নেই।", "en": "When you travel in the land, there is no blame on you for shortening the prayer."}, "ref": {"bn": "সূরা নিসা ৪:১০১ (আয়াতের অংশ)", "en": "An-Nisa 4:101 (part of the verse)"}}, {"type": "text", "text": {"bn": "সফরে জোহর, আসর ও ইশার চার রাকাত ফরজ দুই রাকাত পড়তে হয়। ফজর (২) ও মাগরিব (৩) অপরিবর্তিত থাকে। বিতর পূর্ণ তিন রাকাতই পড়তে হয়।", "en": "On a journey, the four-rak''ah fard of Dhuhr, ''Asr and ''Isha become two. Fajr (2) and Maghrib (3) stay the same. Witr stays three."}}, {"type": "table", "head": [{"bn": "নামাজ", "en": "Prayer"}, {"bn": "বাড়িতে ফরজ", "en": "At home (fard)"}, {"bn": "সফরে ফরজ", "en": "Travelling (fard)"}], "rows": [[{"bn": "ফজর", "en": "Fajr"}, {"bn": "২", "en": "2"}, {"bn": "২", "en": "2"}], [{"bn": "জোহর", "en": "Dhuhr"}, {"bn": "৪", "en": "4"}, {"bn": "২", "en": "2"}], [{"bn": "আসর", "en": "''Asr"}, {"bn": "৪", "en": "4"}, {"bn": "২", "en": "2"}], [{"bn": "মাগরিব", "en": "Maghrib"}, {"bn": "৩", "en": "3"}, {"bn": "৩", "en": "3"}], [{"bn": "ইশা", "en": "''Isha"}, {"bn": "৪", "en": "4"}, {"bn": "২", "en": "2"}]]}, {"type": "text", "text": {"bn": "নিজের এলাকা (শহর বা গ্রামের বসতি) পার হওয়ার পর থেকে কসর শুরু হয়, আর ফিরে নিজের এলাকায় ঢুকলে শেষ হয়। আনাস (রা.) বলেন, আমরা নবীজি (সা.)-এর সাথে মদিনা থেকে মক্কা গিয়েছি; ফেরা পর্যন্ত তিনি দুই রাকাত করে পড়েছেন (সহিহ বুখারি ১০৮১)।", "en": "Qasr begins once you leave the built-up area of your town and ends when you re-enter it. Anas said: we travelled with the Prophet from Madinah to Makkah and he prayed two rak''ahs until we returned (Sahih al-Bukhari 1081)."}}, {"type": "differ", "title": {"bn": "কতটুকু দূরত্বে মুসাফির হয়", "en": "Distance that makes one a traveller"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "তিন দিনের পায়ে হাঁটা পথ; বাংলাদেশের আলেমরা সাধারণত ৪৮ মাইল, প্রায় ৭৭–৭৮ কিলোমিটার ধরেন। যানবাহনে অল্প সময়ে গেলেও একই হুকুম।", "en": "Three days'' walking; scholars in Bangladesh usually take this as 48 miles, about 77–78 km, regardless of how fast the vehicle is."}, "evidence": {"bn": "মুসাফিরকে তিন দিন-তিন রাত মোজার ওপর মাসেহ করার অনুমতি (সহিহ মুসলিম ২৭৬), অর্থাৎ সফরের সর্বনিম্ন সময় তিন দিন ধরা হয়েছে।", "en": "Travellers may wipe over socks for three days and nights (Sahih Muslim 276), taken to indicate that travel is at least three days."}}, {"label": {"bn": "শাফেয়ি, মালেকি ও হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "চার ‘বারিদ’ (১৬ ফারসাখ), আধুনিক হিসাবে প্রায় ৮০–৮৯ কিলোমিটার (হিসাবে কিছু ভিন্নতা আছে)।", "en": "Four burud (16 farsakh), roughly 80–89 km by modern estimates (estimates vary)."}, "evidence": {"bn": "ইবনে উমর ও ইবনে আব্বাস (রা.) চার বারিদ দূরত্বে কসর করতেন (সহিহ বুখারিতে অধ্যায়ের শিরোনামে উল্লেখিত)।", "en": "Ibn ''Umar and Ibn ''Abbas shortened at four burud (mentioned in a chapter heading of Sahih al-Bukhari)."}}, {"label": {"bn": "কিছু আলেম (যেমন ইবনে তাইমিয়া)", "en": "Some scholars (e.g. Ibn Taymiyyah)"}, "text": {"bn": "নির্দিষ্ট দূরত্ব নেই; প্রচলিত অর্থে যাকে সফর বলা হয়, তাতেই কসর।", "en": "No fixed distance; whatever is customarily called a journey."}, "evidence": {"bn": "কুরআন সফরের কোনো দূরত্ব নির্ধারণ করেনি (সূরা নিসা ৪:১০১)।", "en": "The Quran sets no distance (An-Nisa 4:101)."}}], "check": true}, {"type": "differ", "title": {"bn": "কত দিন থাকলে আর মুসাফির থাকে না", "en": "How long a stay ends traveller status"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "কোনো এক জায়গায় ১৫ দিন বা তার বেশি থাকার নিয়ত করলে পূর্ণ নামাজ পড়বে; ১৫ দিনের কম হলে কসর। কবে ফিরবে ঠিক না থাকলে (আজ-কাল করে) যত দিনই থাকুক, কসর চলবে।", "en": "Intending to stay 15 days or more in one place means full prayers; less than 15 means qasr. If the return date is uncertain, qasr continues however long it lasts."}, "evidence": {"bn": "ইবনে উমর ও ইবনে আব্বাস (রা.)-এর ফতোয়া (১৫ দিন); নবীজি (সা.) এক সফরে ১৯ দিন থেকে কসর করেছেন (সহিহ বুখারি ১০৮০)।", "en": "Fatwa of Ibn ''Umar and Ibn ''Abbas (15 days); the Prophet stayed 19 days on a journey and shortened (Sahih al-Bukhari 1080)."}}, {"label": {"bn": "শাফেয়ি, মালেকি ও হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "চার দিন বা তার বেশি থাকার নিয়ত করলে পূর্ণ নামাজ (আসা-যাওয়ার দিন বাদে হিসাব; হাম্বলি মতে ২০ ওয়াক্তের বেশি)।", "en": "Intending to stay four days or more means full prayers (excluding arrival/departure days; Hanbali: more than 20 prayers)."}, "evidence": {"bn": "হজের পর মুহাজিরদের মক্কায় তিন দিন থাকার অনুমতি দেওয়া হয়েছিল (সহিহ মুসলিম ১৩৫২), অর্থাৎ তিন দিন পর্যন্ত সফরের হুকুম।", "en": "Emigrants were allowed to stay three days in Makkah after Hajj (Sahih Muslim 1352), implying up to three days is still travel."}}], "check": true}, {"type": "differ", "title": {"bn": "কসর বাধ্যতামূলক না ঐচ্ছিক", "en": "Is shortening required or optional"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "কসর ওয়াজিব। মুসাফির ইচ্ছা করে চার রাকাত পড়লে গুনাহগার হবে; দ্বিতীয় রাকাতে বৈঠক করলে প্রথম দুই রাকাত ফরজ ও বাকি দুই নফল গণ্য হবে।", "en": "Qasr is wajib. A traveller who deliberately prays four does wrong; if he sat after two, the first two count as fard and the rest as nafl."}, "evidence": {"bn": "আয়েশা (রা.): নামাজ প্রথমে দুই রাকাত করে ফরজ হয়েছিল; সফরের নামাজ সেভাবেই রাখা হয়েছে, আর মুকিমের নামাজ বাড়ানো হয়েছে (সহিহ বুখারি ৩৫০; সহিহ মুসলিম ৬৮৫)।", "en": "''A''ishah: prayer was first prescribed as two rak''ahs; the travel prayer was kept so and the resident''s prayer increased (Sahih al-Bukhari 350; Sahih Muslim 685)."}}, {"label": {"bn": "শাফেয়ি, মালেকি ও হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "কসর একটি ছাড় (রুখসত) ও সুন্নত; পূর্ণ পড়লেও নামাজ হয়ে যায়, তবে কসর উত্তম।", "en": "Qasr is a concession and sunnah; full prayer is valid, but shortening is better."}, "evidence": {"bn": "আয়াতে ‘কোনো গুনাহ নেই’ বলা হয়েছে, যা অনুমতি বোঝায় (সূরা নিসা ৪:১০১)।", "en": "The verse says ''no blame on you'', which indicates permission (An-Nisa 4:101)."}}]}, {"type": "heading", "text": {"bn": "জামাত ও সুন্নতের মাসআলা", "en": "Congregation and sunnah rulings"}}, {"type": "list", "items": [{"bn": "মুসাফির যদি মুকিম ইমামের পেছনে পড়ে, তবে ইমামের সাথে পূর্ণ চার রাকাত পড়বে।", "en": "A traveller behind a resident imam prays the full four with him."}, {"bn": "মুকিম যদি মুসাফির ইমামের পেছনে পড়ে, ইমাম দুই রাকাতে সালাম ফেরাবেন; মুকিমরা দাঁড়িয়ে বাকি দুই রাকাত নিজে নিজে পূর্ণ করবেন (কিরাত ছাড়া, হানাফি মত)। ইমাম আগেই জানিয়ে দেবেন যে তিনি মুসাফির।", "en": "Residents behind a travelling imam: he ends after two; they stand and complete the remaining two themselves (without recitation, Hanafi view). The imam should tell them he is travelling."}, {"bn": "সফরে সুন্নত নামাজ: তাড়াহুড়া থাকলে ছেড়ে দেওয়া যায়; স্থির ও নিরাপদ অবস্থায় পড়া ভালো। ফজরের সুন্নত ও বিতর নবীজি (সা.) সফরেও ছাড়তেন না। ইবনে উমর (রা.) বলেন, তিনি সফরে (ফরজের আগে-পরে) নফল পড়তে দেখেননি (সহিহ বুখারি ১১০১)।", "en": "Sunnah prayers when travelling: may be left if in a hurry, better prayed when settled. The Prophet kept the Fajr sunnah and witr even when travelling. Ibn ''Umar said he did not see him pray the regular sunnahs on journeys (Sahih al-Bukhari 1101)."}, {"bn": "সফরে ছুটে যাওয়া নামাজ বাড়িতে কাজা করলেও দুই রাকাত; বাড়িতে ছুটে যাওয়া নামাজ সফরে কাজা করলে চার রাকাত।", "en": "A prayer missed while travelling is made up as two even at home; one missed at home is made up as four even while travelling."}]}, {"type": "differ", "title": {"bn": "সফরে দুই ওয়াক্ত একসাথে পড়া (জমা)", "en": "Combining two prayers when travelling"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "হজে আরাফা ও মুজদালিফা ছাড়া এক ওয়াক্তের নামাজ অন্য ওয়াক্তে পড়া যায় না। তবে জোহর তার শেষ ওয়াক্তে আর আসর তার প্রথম ওয়াক্তে পড়া যায়, যাতে দেখতে একসাথে মনে হয় (জমায়ে সুরি)।", "en": "Apart from ''Arafah and Muzdalifah in Hajj, no prayer may be moved into another''s time. But Dhuhr may be prayed at the end of its time and ''Asr at the start of its time, so they appear joined."}, "evidence": {"bn": "‘নিশ্চয়ই নামাজ মুমিনদের ওপর নির্দিষ্ট সময়ে ফরজ’ (সূরা নিসা ৪:১০৩); ইবনে মাসউদ (রা.): মুজদালিফা ছাড়া নবীজি (সা.)-কে কখনো নামাজ তার সময় ছাড়া পড়তে দেখিনি (সহিহ বুখারি ১৬৮২)।", "en": "''Prayer is prescribed for the believers at fixed times'' (An-Nisa 4:103); Ibn Mas''ud: I never saw the Prophet pray outside its time except at Muzdalifah (Sahih al-Bukhari 1682)."}}, {"label": {"bn": "শাফেয়ি, হাম্বলি ও মালেকি", "en": "Shafi''i, Hanbali, Maliki"}, "text": {"bn": "সফরে জোহর-আসর এবং মাগরিব-ইশা একটির ওয়াক্তে একসাথে পড়া জায়েজ (আগে বা পরে নিয়ে)।", "en": "When travelling, Dhuhr with ''Asr and Maghrib with ''Isha may be joined in the time of either."}, "evidence": {"bn": "তাড়া থাকলে নবীজি (সা.) সফরে মাগরিব ও ইশা একসাথে পড়তেন (সহিহ বুখারি ১১০৬); সহিহ মুসলিম ৭০৫।", "en": "When in a hurry on a journey, the Prophet combined Maghrib and ''Isha (Sahih al-Bukhari 1106); Sahih Muslim 705."}}]}]', 'in_review', 90 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '3bcd21e8-8f0e-5a98-b83a-2b4ff0eaf7f7', id, 'qada-prayer', '{"bn": "কাজা নামাজ", "en": "Making Up Missed Prayers (Qada)"}', '{"bn": "ঘুম, ভুল বা অন্য কারণে ছুটে যাওয়া নামাজ কীভাবে আদায় করবেন: ধারাবাহিকতা, অনেক দিনের কাজা ও কিছু মতভেদ।", "en": "How to make up prayers missed through sleep, forgetfulness or otherwise: order, many years of missed prayers, and points of difference."}', 'basic', '[{"type": "arabic", "ar": "مَنْ نَسِيَ صَلَاةً فَلْيُصَلِّ إِذَا ذَكَرَهَا، لَا كَفَّارَةَ لَهَا إِلَّا ذٰلِكَ", "pron": {"bn": "মান নাসিয়া সালাতান ফালইউসাল্লি ইযা যাকারাহা, লা কাফফারাতা লাহা ইল্লা যালিক।", "en": "Man nasiya salatan falyusalli idha dhakaraha, la kaffarata laha illa dhalik."}, "meaning": {"bn": "যে কোনো নামাজ ভুলে যায়, সে যেন মনে পড়লেই তা পড়ে নেয়; এ ছাড়া এর আর কোনো কাফফারা নেই।", "en": "Whoever forgets a prayer, let him pray it when he remembers; there is no expiation for it except that."}, "ref": {"bn": "সহিহ বুখারি ৫৯৭; সহিহ মুসলিম ৬৮৪", "en": "Sahih al-Bukhari 597; Sahih Muslim 684"}}, {"type": "text", "text": {"bn": "ফরজ নামাজ ছুটে গেলে কাজা করা ফরজ, আর বিতর ছুটে গেলে হানাফি মতে কাজা করা ওয়াজিব। ঘুম বা ভুলের কারণে ছুটে গেলে গুনাহ নেই, তবে মনে পড়ামাত্র পড়ে নিতে হবে। ঋতুস্রাব ও প্রসবোত্তর রক্তস্রাবের সময়ের নামাজের কাজা নেই (সহিহ মুসলিম ৩৩৫)।", "en": "Making up a missed fard prayer is obligatory, and in the Hanafi school also witr. Missing through sleep or forgetfulness is not sinful, but pray as soon as you remember. Prayers during menstruation and post-natal bleeding are not made up (Sahih Muslim 335)."}}, {"type": "heading", "text": {"bn": "কীভাবে কাজা পড়বেন", "en": "How to make up"}}, {"type": "step", "title": {"bn": "নিয়ত", "en": "Intention"}, "text": {"bn": "যে নামাজ কাজা করছেন, মনে মনে সেটি নির্দিষ্ট করুন, যেমন ‘আজকের ছুটে যাওয়া ফজরের দুই রাকাত ফরজ’। মুখে বলা জরুরি নয়।", "en": "Specify in your heart which prayer you are making up, e.g. ''today''s missed two rak''ahs of Fajr fard''. Saying it aloud is not required."}}, {"type": "step", "title": {"bn": "যেভাবে ছুটেছে সেভাবে", "en": "As it was missed"}, "text": {"bn": "নামাজ যেমন ছিল তেমনই পড়ুন: ফজর দুই, মাগরিব তিন। সফরে ছুটে যাওয়া চার রাকাতের নামাজ দুই রাকাত।", "en": "Pray it as it was: Fajr two, Maghrib three; a four-rak''ah prayer missed while travelling is two."}}, {"type": "step", "title": {"bn": "সাধারণত শুধু ফরজ ও বিতর", "en": "Usually only fard and witr"}, "text": {"bn": "কাজা হয় ফরজ ও বিতরের। হানাফি মতে ফজর ফরজসহ ছুটে গেলে সেদিন জাওয়ালের আগে কাজা করলে সুন্নতসহ পড়বে; অন্য সুন্নতের কাজা নেই।", "en": "Qada is for fard and witr. In the Hanafi school, if Fajr is missed with its sunnah and made up before noon the same day, the sunnah is included; other sunnahs are not made up."}}, {"type": "step", "title": {"bn": "সময়", "en": "When"}, "text": {"bn": "যেকোনো সময় কাজা পড়া যায়, তবে সূর্যোদয়, ঠিক দুপুর ও সূর্যাস্তের সময় (হানাফি মতে) নয়। ফজরের পর ও আসরের পর কাজা পড়া যায়, যদিও তখন নফল পড়া যায় না।", "en": "Any time, except (in the Hanafi school) at sunrise, true noon and sunset. Qada may be prayed after Fajr and after ''Asr, though nafl may not."}}, {"type": "differ", "title": {"bn": "কাজা ও ওয়াক্তিয়া নামাজের ধারাবাহিকতা (তারতিব)", "en": "Keeping the order between missed and current prayers"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "যার জিম্মায় ছয় ওয়াক্তের কম কাজা আছে (সাহিবে তারতিব), তাকে আগে কাজা পরে ওয়াক্তিয়া পড়তে হবে; তবে ওয়াক্ত সংকীর্ণ হলে, ভুলে গেলে বা কাজা ছয় ওয়াক্ত বা বেশি হলে এই ধারাবাহিকতা বাধ্যতামূলক নয়।", "en": "Someone with fewer than six missed prayers must pray them before the current one, unless time is short, he forgot, or the missed prayers are six or more."}, "evidence": {"bn": "খন্দকের যুদ্ধে ছুটে যাওয়া নামাজগুলো নবীজি (সা.) ক্রমানুসারে আদায় করেছেন (জামে তিরমিজি; সুনান নাসায়ি)।", "en": "At the Battle of the Trench the Prophet made up the missed prayers in order (Jami'' al-Tirmidhi; Sunan al-Nasa''i)."}}, {"label": {"bn": "হাম্বলি ও মালেকি", "en": "Hanbali and Maliki"}, "text": {"bn": "ধারাবাহিকতা রক্ষা করা ওয়াজিব (বিস্তারিত শর্তে কিছু ভিন্নতা আছে)।", "en": "Order is required (with some differences in the details)."}, "evidence": {"bn": "একই হাদিস।", "en": "The same hadith."}}, {"label": {"bn": "শাফেয়ি", "en": "Shafi''i"}, "text": {"bn": "ধারাবাহিকতা রক্ষা করা সুন্নত, বাধ্যতামূলক নয়।", "en": "Order is recommended, not required."}, "evidence": {"bn": "হাদিসে কেবল নবীজি (সা.)-এর আমল বর্ণিত, স্পষ্ট নির্দেশ নয়।", "en": "The hadith reports the Prophet''s practice, not an explicit command."}}], "check": true}, {"type": "heading", "text": {"bn": "অনেক বছরের কাজা (উমরি কাজা)", "en": "Many years of missed prayers"}}, {"type": "text", "text": {"bn": "যদি দীর্ঘদিন নামাজ না পড়ে থাকেন, আন্তরিক তওবা করুন এবং আনুমানিক হিসাব করুন কত ওয়াক্ত ছুটেছে; সন্দেহ হলে বেশির দিকে ধরুন। তারপর প্রতিদিন সাধ্যমতো কাজা পড়তে থাকুন, যেমন প্রতি ওয়াক্তের সাথে এক ওয়াক্ত কাজা। নিয়তে বলবেন (মনে মনে), ‘আমার জিম্মায় থাকা প্রথম (বা শেষ) ফজরের কাজা’।", "en": "If you did not pray for a long time, repent sincerely and estimate how many prayers were missed, erring on the higher side. Then make them up steadily, e.g. one with each daily prayer. Intend ''the first (or last) Fajr I owe''."}}, {"type": "differ", "title": {"bn": "ইচ্ছাকৃতভাবে ছেড়ে দেওয়া নামাজের কাজা", "en": "Prayers left deliberately"}, "views": [{"label": {"bn": "চার মাজহাব (অধিকাংশ আলেম)", "en": "The four schools (majority)"}, "text": {"bn": "ইচ্ছা করে ছেড়ে দিলেও কাজা করা ফরজ, সাথে তওবা করতে হবে।", "en": "They must be made up, along with repentance."}, "evidence": {"bn": "ভুলে যাওয়া ব্যক্তিকেও কাজা করতে বলা হয়েছে (সহিহ বুখারি ৫৯৭); ইচ্ছাকৃত ত্যাগকারী আরও বেশি দায়বদ্ধ। ‘আল্লাহর ঋণ পরিশোধের বেশি উপযুক্ত’ (সহিহ বুখারি ১৯৫৩)।", "en": "Even the forgetful must make up (Sahih al-Bukhari 597), so the deliberate omitter all the more. ''The debt of Allah is more deserving to be paid'' (Sahih al-Bukhari 1953)."}}, {"label": {"bn": "কিছু আলেম (যেমন ইবনে হাযম, ইবনে তাইমিয়া)", "en": "Some scholars (e.g. Ibn Hazm, Ibn Taymiyyah)"}, "text": {"bn": "ইচ্ছাকৃত ছেড়ে দেওয়া নামাজ কাজা করে আদায় হয় না; খাঁটি তওবা ও বেশি বেশি নফল পড়তে হবে।", "en": "Deliberately abandoned prayers cannot be validly made up; sincere repentance and abundant nafl are required."}, "evidence": {"bn": "হাদিসে কাজার নির্দেশ এসেছে কেবল ঘুম ও ভুলের ক্ষেত্রে (সহিহ বুখারি ৫৯৭)।", "en": "The hadith commands qada only for sleep and forgetfulness (Sahih al-Bukhari 597)."}}]}, {"type": "note", "tone": "tip", "text": {"bn": "নিরাপদ পথ হলো অধিকাংশ আলেমের মত অনুযায়ী কাজা করে যাওয়া। কাজার বোঝা যেন নতুন নামাজ ছাড়ার কারণ না হয়; আজ থেকে প্রতিটি ওয়াক্ত সময়মতো পড়ুন।", "en": "The safe course is to follow the majority and make them up. Do not let the backlog stop you praying today''s prayers on time."}}]', 'in_review', 100 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '9e55ea4c-cc2c-5d4f-89c6-fb1c3ff5525c', id, 'salatul-hajah', '{"bn": "সালাতুল হাজত", "en": "Salat al-Hajah (Prayer of Need)"}', '{"bn": "বিপদে বা কোনো প্রয়োজনে আল্লাহর কাছে চাওয়ার জন্য দুই রাকাত নামাজ ও দোয়া, হাদিসের মানসহ।", "en": "Two rak''ahs and a du''a when in need or distress, with an honest note on the narrations."}', 'basic', '[{"type": "arabic", "ar": "وَاسْتَعِينُوا بِالصَّبْرِ وَالصَّلَاةِ ۚ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى الْخَاشِعِينَ", "pron": {"bn": "ওয়াসতাঈনূ বিসসাবরি ওয়াস সালাহ, ওয়া ইন্নাহা লাকাবীরাতুন ইল্লা আলাল খাশিঈন।", "en": "Wasta''inu bis-sabri was-salah, wa innaha lakabiratun illa ''alal-khashi''in."}, "meaning": {"bn": "তোমরা ধৈর্য ও নামাজের মাধ্যমে সাহায্য চাও; আর নিশ্চয়ই তা কঠিন, তবে বিনয়ীদের জন্য নয়।", "en": "Seek help through patience and prayer; it is hard except for the humble."}, "ref": {"bn": "সূরা বাকারা ২:৪৫", "en": "Al-Baqarah 2:45"}}, {"type": "text", "text": {"bn": "হুযাইফা (রা.) বলেন, কোনো বিষয় নবীজি (সা.)-কে চিন্তিত করলে তিনি নামাজে দাঁড়াতেন (সুনান আবু দাউদ ১৩১৯)। তাই প্রয়োজন বা বিপদে নামাজ পড়ে আল্লাহর কাছে চাওয়া সুন্নাহসম্মত।", "en": "Hudhayfah said that when something worried the Prophet, he would pray (Sunan Abi Dawud 1319). So praying and then asking Allah in need is in line with the sunnah."}}, {"type": "heading", "text": {"bn": "পদ্ধতি", "en": "Method"}}, {"type": "step", "title": {"bn": "ওযু", "en": "Wudu"}, "text": {"bn": "সুন্দরভাবে ওযু করুন।", "en": "Make wudu well."}}, {"type": "step", "title": {"bn": "দুই রাকাত নফল", "en": "Two rak''ahs of nafl"}, "text": {"bn": "মাকরুহ সময় ছাড়া দুই রাকাত নফল নামাজ পড়ুন; যেকোনো সূরা পড়া যায়।", "en": "Pray two rak''ahs of nafl outside the disliked times; any surah may be recited."}}, {"type": "step", "title": {"bn": "প্রশংসা ও দরুদ", "en": "Praise and durood"}, "text": {"bn": "সালামের পর আল্লাহর প্রশংসা করুন ও নবীজি (সা.)-এর ওপর দরুদ পড়ুন।", "en": "After salam, praise Allah and send durood on the Prophet."}}, {"type": "step", "title": {"bn": "দোয়া", "en": "Ask"}, "text": {"bn": "নিচের দোয়া বা নিজের ভাষায় মন খুলে আপনার প্রয়োজন আল্লাহর কাছে চান।", "en": "Recite the du''a below or ask for your need in your own words."}}, {"type": "arabic", "label": {"bn": "সালাতুল হাজতের প্রচলিত দোয়া", "en": "The commonly used du''a of need"}, "ar": "لَا إِلٰهَ إِلَّا اللّٰهُ الْحَلِيمُ الْكَرِيمُ، سُبْحَانَ اللّٰهِ رَبِّ الْعَرْشِ الْعَظِيمِ، الْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِينَ، أَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ، وَعَزَائِمَ مَغْفِرَتِكَ، وَالْغَنِيمَةَ مِنْ كُلِّ بِرٍّ، وَالسَّلَامَةَ مِنْ كُلِّ إِثْمٍ، لَا تَدَعْ لِي ذَنْبًا إِلَّا غَفَرْتَهُ، وَلَا هَمًّا إِلَّا فَرَّجْتَهُ، وَلَا حَاجَةً هِيَ لَكَ رِضًا إِلَّا قَضَيْتَهَا، يَا أَرْحَمَ الرَّاحِمِينَ", "pron": {"bn": "লা ইলাহা ইল্লাল্লাহুল হালীমুল কারীম, সুবহানাল্লাহি রাব্বিল আরশিল আযীম, আলহামদু লিল্লাহি রাব্বিল আলামীন। আসআলুকা মূজিবাতি রাহমাতিকা, ওয়া আযাইমা মাগফিরাতিকা, ওয়াল গানীমাতা মিন কুল্লি বিররিন, ওয়াস সালামাতা মিন কুল্লি ইসমিন। লা তাদা'' লী যামবান ইল্লা গাফারতাহু, ওয়া লা হাম্মান ইল্লা ফাররাজতাহু, ওয়া লা হাজাতান হিয়া লাকা রিদান ইল্লা কাদাইতাহা, ইয়া আরহামার রাহিমীন।", "en": "La ilaha illallahul-Halimul-Karim, subhanallahi Rabbil-''arshil-''azim, al-hamdu lillahi Rabbil-''alamin. As''aluka mujibati rahmatika, wa ''aza''ima maghfiratika, wal-ghanimata min kulli birr, was-salamata min kulli ithm. La tada'' li dhanban illa ghafartahu, wa la hamman illa farrajtahu, wa la hajatan hiya laka ridan illa qadaytaha, ya Arhamar-rahimin."}, "meaning": {"bn": "আল্লাহ ছাড়া কোনো ইলাহ নেই, যিনি সহনশীল ও মহানুভব। মহান আরশের রব আল্লাহ পবিত্র। সকল প্রশংসা জগতসমূহের রব আল্লাহর। (হে আল্লাহ,) আমি তোমার কাছে চাই সেসব কাজ যা তোমার রহমত নিশ্চিত করে, যা তোমার ক্ষমা অবধারিত করে, প্রতিটি নেক কাজের অংশ এবং প্রতিটি গুনাহ থেকে নিরাপত্তা। আমার কোনো গুনাহ ক্ষমা না করে রেখো না, কোনো দুশ্চিন্তা দূর না করে রেখো না, আর তোমার পছন্দনীয় কোনো প্রয়োজন পূরণ না করে রেখো না, হে সর্বশ্রেষ্ঠ দয়ালু।", "en": "There is no god but Allah, the Forbearing, the Generous. Glory be to Allah, Lord of the Mighty Throne. Praise be to Allah, Lord of the worlds. I ask You for what makes Your mercy certain and Your forgiveness assured, a share of every good and safety from every sin. Leave me no sin unforgiven, no worry unrelieved, and no need that pleases You unfulfilled, O Most Merciful of the merciful."}, "ref": {"bn": "জামে তিরমিজি ৪৭৯ (আবদুল্লাহ ইবনে আবি আওফা রা.)", "en": "Jami'' al-Tirmidhi 479 (''Abdullah ibn Abi Awfa)"}}, {"type": "note", "tone": "warn", "text": {"bn": "এই নির্দিষ্ট পদ্ধতি ও দোয়ার হাদিসটি দুর্বল। ইমাম তিরমিজি নিজেই বলেছেন, এর সনদে আপত্তি আছে; বর্ণনাকারী ফায়েদ ইবনে আবদুর রহমান দুর্বল। শাইখ আলবানি একে খুব দুর্বল বলেছেন। তাই দোয়াটি পড়া যায় (এর অর্থ ভালো), কিন্তু এটিকে নবীজি (সা.)-এর নিশ্চিত শিক্ষা বা নির্দিষ্ট ফজিলতের প্রমাণ মনে করবেন না। নিজের ভাষায় দোয়াও সম্পূর্ণ সঠিক।", "en": "The hadith with this specific method and du''a is weak. Al-Tirmidhi himself noted a problem in its chain (the narrator Fa''id ibn ''Abd al-Rahman is weak); al-Albani graded it very weak. You may say the du''a (its meaning is good), but do not treat it as a confirmed teaching with a fixed reward. Asking in your own words is entirely valid."}}, {"type": "note", "tone": "tip", "text": {"bn": "নিয়ত মনে মনে করাই যথেষ্ট। উদাহরণ (প্রচলিত বাংলা): ‘আমি আল্লাহর জন্য দুই রাকাত সালাতুল হাজত পড়ছি।’", "en": "The intention in the heart is enough. Example (common Bangla phrasing): ''I am praying two rak''ahs of salat al-hajah for Allah.''"}}, {"type": "ref", "text": {"bn": "আরও দেখুন: সূরা বাকারা ২:১৮৬ (‘আমি নিকটে, ডাকলে সাড়া দিই’)", "en": "See also: Al-Baqarah 2:186 (''I am near; I answer the caller'')"}}]', 'in_review', 110 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '580c8f39-81c3-5dd7-9520-9bb18dd2655a', id, 'eclipse-prayer', '{"bn": "সূর্যগ্রহণ ও চন্দ্রগ্রহণের নামাজ", "en": "Eclipse Prayer (Kusuf and Khusuf)"}', '{"bn": "সূর্যগ্রহণ (কুসুফ) ও চন্দ্রগ্রহণের (খুসুফ) সময় নামাজ, দোয়া ও সদকা; পদ্ধতি নিয়ে মাজহাবের মত।", "en": "Prayer, du''a and charity during solar and lunar eclipses, and the schools'' methods."}', 'detail', '[{"type": "text", "text": {"bn": "নবীজি (সা.)-এর পুত্র ইবরাহিমের মৃত্যুর দিন সূর্যগ্রহণ হলে মানুষ বলাবলি করছিল যে তাঁর মৃত্যুর কারণে গ্রহণ হয়েছে। নবীজি (সা.) এই ধারণা নাকচ করে নামাজ পড়েন এবং বলেন:", "en": "When the sun eclipsed on the day the Prophet''s son Ibrahim died, people said it was because of his death. The Prophet rejected this, prayed, and said:"}}, {"type": "arabic", "ar": "إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللّٰهِ، لَا يَنْخَسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ، فَإِذَا رَأَيْتُمْ ذٰلِكَ فَادْعُوا اللّٰهَ وَكَبِّرُوا، وَصَلُّوا وَتَصَدَّقُوا", "pron": {"bn": "ইন্নাশ শামসা ওয়াল কামারা আয়াতানি মিন আয়াতিল্লাহ, লা ইয়ানখাসিফানি লিমাওতি আহাদিন ওয়া লা লিহায়াতিহ; ফাইযা রাআইতুম যালিকা ফাদউল্লাহা ওয়া কাব্বিরূ, ওয়া সাল্লূ ওয়া তাসাদ্দাকূ।", "en": "Innash-shamsa wal-qamara ayatani min ayatillah, la yankhasifani limawti ahadin wa la lihayatih; fa idha ra''aytum dhalika fad''ullaha wa kabbiru, wa sallu wa tasaddaqu."}, "meaning": {"bn": "সূর্য ও চাঁদ আল্লাহর নিদর্শনসমূহের দুটি নিদর্শন; কারও মৃত্যু বা জন্মের কারণে এদের গ্রহণ হয় না। যখন তোমরা তা দেখবে, তখন আল্লাহর কাছে দোয়া করো, তাকবির বলো, নামাজ পড়ো ও সদকা করো।", "en": "The sun and moon are two of Allah''s signs; they do not eclipse for anyone''s death or life. When you see that, call upon Allah, say takbir, pray and give charity."}, "ref": {"bn": "সহিহ বুখারি ১০৪৪", "en": "Sahih al-Bukhari 1044"}}, {"type": "text", "text": {"bn": "গ্রহণের নামাজ সুন্নতে মুয়াক্কাদা। আজান বা ইকামত নেই; মানুষকে ডাকতে ‘আস-সালাতু জামি''আহ’ (নামাজ জামাতে হচ্ছে) বলা যায় (সহিহ বুখারি ১০৪৫)। গ্রহণ শুরু হলে থেকে শেষ হওয়া পর্যন্ত নামাজ, দোয়া ও জিকিরে থাকুন।", "en": "The eclipse prayer is a confirmed sunnah. There is no adhan or iqamah; people may be called with ''as-salatu jami''ah'' (Sahih al-Bukhari 1045). Stay in prayer, du''a and dhikr from the start of the eclipse until it clears."}}, {"type": "differ", "title": {"bn": "নামাজের পদ্ধতি", "en": "Method of the prayer"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "সাধারণ নফলের মতো দুই রাকাত, প্রতি রাকাতে একটি রুকু, তবে কিরাত, রুকু ও সিজদা লম্বা। সূর্যগ্রহণে জামাতে (ইমাম আবু হানিফার মতে চুপে কিরাত), চন্দ্রগ্রহণে সাধারণত প্রত্যেকে আলাদাভাবে নিজ নিজ ঘরে। নামাজের পর গ্রহণ শেষ না হওয়া পর্যন্ত দোয়া; নির্ধারিত খুতবা নেই।", "en": "Two rak''ahs like normal nafl with one ruku'' each, but with long recitation, ruku'' and sajdah. Solar eclipse in congregation (quiet recitation per Abu Hanifah); lunar eclipse usually individually at home. Du''a afterwards until it clears; no formal khutbah."}, "evidence": {"bn": "আবু বাকরা (রা.): নবীজি (সা.) আমাদের নিয়ে দুই রাকাত পড়লেন, এর মধ্যে সূর্য পরিষ্কার হয়ে গেল (সহিহ বুখারি ১০৪০); সাধারণ নামাজের মতো এক রুকুর বর্ণনাও কিছু সাহাবি থেকে এসেছে।", "en": "Abu Bakrah: the Prophet prayed two rak''ahs with us until the sun cleared (Sahih al-Bukhari 1040); some Companions'' reports describe one ruku'' per rak''ah like a normal prayer."}}, {"label": {"bn": "শাফেয়ি, মালেকি ও হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "দুই রাকাত, প্রতি রাকাতে দুইবার কিয়াম ও দুইবার রুকু: লম্বা কিরাত, লম্বা রুকু, উঠে আবার কিরাত (আগেরটির চেয়ে ছোট), আবার রুকু (আগেরটির চেয়ে ছোট), তারপর দুই সিজদা। সূর্য ও চন্দ্রগ্রহণ দুটিতেই জামাতে; শাফেয়ি মতে পরে খুতবা।", "en": "Two rak''ahs, each with two standings and two ruku''s: long recitation, long ruku'', rise and recite again (shorter), ruku'' again (shorter), then two sajdahs. Both eclipses in congregation; Shafi''is add a khutbah after."}, "evidence": {"bn": "আয়েশা (রা.)-এর বর্ণনা (সহিহ বুখারি ১০৪৪, ১০৪৬); সহিহ মুসলিম ৯০১। নবীজি (সা.) নামাজের পর খুতবা দিয়েছেন (সহিহ বুখারি ১০৪৪)।", "en": "The report of ''A''ishah (Sahih al-Bukhari 1044, 1046); Sahih Muslim 901. The Prophet addressed the people after the prayer (Sahih al-Bukhari 1044)."}}], "check": true}, {"type": "heading", "text": {"bn": "গ্রহণের সময় যা করবেন", "en": "What to do during an eclipse"}}, {"type": "list", "items": [{"bn": "নামাজ পড়া, বেশি বেশি দোয়া, তাকবির ও ইস্তিগফার", "en": "Pray, and make abundant du''a, takbir and istighfar"}, {"bn": "সদকা করা (সহিহ বুখারি ১০৪৪)", "en": "Give charity (Sahih al-Bukhari 1044)"}, {"bn": "গ্রহণকে কারও জন্ম-মৃত্যু বা ভাগ্যের সাথে জড়িয়ে কুসংস্কার না করা", "en": "Do not tie the eclipse to anyone''s birth, death or fortune"}, {"bn": "মাকরুহ সময়ে গ্রহণ হলে হানাফি মতে নামাজ না পড়ে দোয়া ও জিকির করা", "en": "If it falls in a disliked time, Hanafis make du''a and dhikr instead of praying"}]}, {"type": "note", "tone": "info", "text": {"bn": "গর্ভবতী নারীর খাওয়া-দাওয়া বা কাজকর্ম বন্ধ রাখার মতো প্রচলিত ধারণার কোনো ভিত্তি কুরআন-হাদিসে নেই।", "en": "Popular beliefs such as pregnant women having to stop eating or working during an eclipse have no basis in the Quran or hadith."}}]', 'in_review', 120 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '8294b2c5-a7c7-5ad7-be46-637318834293', id, 'istisqa-prayer', '{"bn": "ইসতিসকা: বৃষ্টির জন্য নামাজ", "en": "Istisqa: Prayer for Rain"}', '{"bn": "খরা ও অনাবৃষ্টিতে আল্লাহর কাছে বৃষ্টি চাওয়ার পদ্ধতি: ইস্তিগফার, দোয়া, নামাজ ও খুতবা।", "en": "Asking Allah for rain in drought: repentance, du''a, prayer and khutbah."}', 'detail', '[{"type": "arabic", "ar": "فَقُلْتُ اسْتَغْفِرُوا رَبَّكُمْ إِنَّهُ كَانَ غَفَّارًا ۝ يُرْسِلِ السَّمَاءَ عَلَيْكُمْ مِدْرَارًا", "pron": {"bn": "ফাকুলতুস তাগফিরূ রাব্বাকুম ইন্নাহূ কানা গাফফারা, ইউরসিলিস সামাআ আলাইকুম মিদরারা।", "en": "Faqultustaghfiru Rabbakum innahu kana ghaffara, yursilis-sama''a ''alaykum midrara."}, "meaning": {"bn": "আমি বললাম, তোমাদের রবের কাছে ক্ষমা চাও, নিশ্চয়ই তিনি অতি ক্ষমাশীল। তিনি তোমাদের ওপর প্রচুর বৃষ্টি বর্ষণ করবেন।", "en": "I said: seek forgiveness of your Lord, He is ever Forgiving. He will send the sky upon you in abundant rain."}, "ref": {"bn": "সূরা নূহ ৭১:১০–১১", "en": "Nuh 71:10–11"}}, {"type": "text", "text": {"bn": "নবীজি (সা.) খরার সময় ঈদগাহের মতো খোলা মাঠে বের হয়ে কিবলামুখী হয়ে দোয়া করেছেন, চাদর উল্টে নিয়েছেন এবং দুই রাকাত নামাজ পড়েছেন (সহিহ বুখারি ১০১২)। আবার জুমার খুতবায় হাত তুলে বৃষ্টির দোয়াও করেছেন (সহিহ বুখারি ১০১৩, ১০১৪)।", "en": "In drought the Prophet went out to the open prayer ground, faced the qiblah, made du''a, turned his cloak inside out and prayed two rak''ahs (Sahih al-Bukhari 1012). He also raised his hands in the Friday khutbah asking for rain (Sahih al-Bukhari 1013, 1014)."}}, {"type": "differ", "title": {"bn": "ইসতিসকায় নামাজ আছে কি", "en": "Is there a set prayer for istisqa"}, "views": [{"label": {"bn": "ইমাম আবু হানিফা (রহ.)", "en": "Imam Abu Hanifah"}, "text": {"bn": "ইসতিসকার মূল হলো দোয়া ও ইস্তিগফার; নির্দিষ্ট জামাতের নামাজ সুন্নত নয়, তবে কেউ একা নামাজ পড়লে ভালো।", "en": "Istisqa is essentially du''a and istighfar; a congregational prayer is not a set sunnah, though praying individually is good."}, "evidence": {"bn": "নবীজি (সা.) জুমার খুতবায় শুধু দোয়া করেছেন, তাতেই বৃষ্টি হয়েছে (সহিহ বুখারি ১০১৩); সূরা নূহ ৭১:১০–১১-এ ইস্তিগফারের কথা।", "en": "The Prophet only made du''a in the Friday khutbah and rain came (Sahih al-Bukhari 1013); Nuh 71:10–11 mentions istighfar."}}, {"label": {"bn": "ইমাম আবু ইউসুফ ও মুহাম্মাদ (রহ.) এবং শাফেয়ি, মালেকি, হাম্বলি", "en": "Abu Yusuf, Muhammad, and the Shafi''i, Maliki, Hanbali schools"}, "text": {"bn": "জামাতে দুই রাকাত নামাজ সুন্নত, জোরে কিরাত, সাথে খুতবা ও দোয়া। শাফেয়ি ও হাম্বলি মতে ঈদের মতো অতিরিক্ত তাকবিরসহ।", "en": "Two rak''ahs in congregation are sunnah, recited aloud, with a khutbah and du''a; Shafi''is and Hanbalis add the Eid takbirs."}, "evidence": {"bn": "আবদুল্লাহ ইবনে যায়েদ (রা.)-এর বর্ণনা (সহিহ বুখারি ১০১২)।", "en": "The report of ''Abdullah ibn Zayd (Sahih al-Bukhari 1012)."}}]}, {"type": "heading", "text": {"bn": "আদব ও প্রস্তুতি", "en": "Etiquette and preparation"}}, {"type": "list", "items": [{"bn": "আগে থেকে তওবা, জুলুম ও হারাম উপার্জন ছেড়ে দেওয়া, অন্যের হক ফিরিয়ে দেওয়া", "en": "Repent beforehand, stop injustice and unlawful earnings, return others'' rights"}, {"bn": "সদকা করা এবং সম্ভব হলে রোজা রাখা", "en": "Give charity and fast if possible"}, {"bn": "সাধারণ পোশাকে বিনয়ের সাথে মাঠে যাওয়া; বয়স্ক, শিশু ও দুর্বলদের সাথে নেওয়া", "en": "Go out humbly in plain clothes; bring elders, children and the weak"}, {"bn": "দোয়ার সময় হাত ভালোভাবে ওপরে তোলা", "en": "Raise the hands well in du''a"}, {"bn": "খুতবা বা দোয়ার শেষে ইমামের চাদর উল্টে নেওয়া (অবস্থা পরিবর্তনের আশার প্রতীক) (সহিহ বুখারি ১০১২)", "en": "The imam turns his cloak at the end (symbolising hope for change) (Sahih al-Bukhari 1012)"}]}, {"type": "arabic", "label": {"bn": "বৃষ্টির দোয়া", "en": "Du''a for rain"}, "ar": "اللّٰهُمَّ اسْقِنَا غَيْثًا مُغِيثًا، مَرِيئًا مَرِيعًا، نَافِعًا غَيْرَ ضَارٍّ، عَاجِلًا غَيْرَ آجِلٍ", "pron": {"bn": "আল্লাহুম্মাসকিনা গাইসান মুগীসান, মারীআন মারীআন, নাফিআন গাইরা দাররিন, আজিলান গাইরা আজিল।", "en": "Allahummasqina ghaythan mughithan, mari''an mari''an, nafi''an ghayra darr, ''ajilan ghayra ajil."}, "meaning": {"bn": "হে আল্লাহ, আমাদের এমন বৃষ্টি দাও, যা সাহায্যকারী, সুপেয় ও ফসল উৎপাদনকারী, উপকারী, ক্ষতিকর নয়, দ্রুত আসে, দেরিতে নয়।", "en": "O Allah, give us rain that relieves, wholesome and fertile, beneficial not harmful, soon and not delayed."}, "ref": {"bn": "সুনান আবু দাউদ ১১৬৯ (জাবির রা.)", "en": "Sunan Abi Dawud 1169 (Jabir)"}}, {"type": "arabic", "label": {"bn": "সংক্ষিপ্ত দোয়া", "en": "Short du''a"}, "ar": "اللّٰهُمَّ أَغِثْنَا، اللّٰهُمَّ أَغِثْنَا، اللّٰهُمَّ أَغِثْنَا", "pron": {"bn": "আল্লাহুম্মা আগিসনা, আল্লাহুম্মা আগিসনা, আল্লাহুম্মা আগিসনা।", "en": "Allahumma aghithna, Allahumma aghithna, Allahumma aghithna."}, "meaning": {"bn": "হে আল্লাহ, আমাদের বৃষ্টি দিয়ে সাহায্য করো (তিনবার)।", "en": "O Allah, relieve us with rain (three times)."}, "ref": {"bn": "সহিহ বুখারি ১০১৪", "en": "Sahih al-Bukhari 1014"}}]', 'in_review', 130 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '7572c7d2-6daf-539d-924a-9d162c2ed557', id, 'tahiyyatul-masjid-wudu', '{"bn": "তাহিয়্যাতুল মসজিদ ও তাহিয়্যাতুল ওযু", "en": "Tahiyyat al-Masjid and Tahiyyat al-Wudu"}', '{"bn": "মসজিদে ঢুকে বসার আগে দুই রাকাত, আর ওযুর পর দুই রাকাত নফল: ফজিলত ও নিয়ম।", "en": "Two rak''ahs on entering the mosque before sitting, and two after wudu: their virtue and rules."}', 'basic', '[{"type": "heading", "text": {"bn": "তাহিয়্যাতুল মসজিদ", "en": "Tahiyyat al-masjid (greeting the mosque)"}}, {"type": "arabic", "ar": "إِذَا دَخَلَ أَحَدُكُمُ الْمَسْجِدَ فَلْيَرْكَعْ رَكْعَتَيْنِ قَبْلَ أَنْ يَجْلِسَ", "pron": {"bn": "ইযা দাখালা আহাদুকুমুল মাসজিদা ফালইয়ারকা'' রাকআতাইনি কাবলা আই ইয়াজলিস।", "en": "Idha dakhala ahadukumul-masjida falyarka'' rak''atayni qabla ay yajlis."}, "meaning": {"bn": "তোমাদের কেউ মসজিদে প্রবেশ করলে বসার আগে যেন দুই রাকাত নামাজ পড়ে নেয়।", "en": "When one of you enters the mosque, let him pray two rak''ahs before sitting."}, "ref": {"bn": "সহিহ বুখারি ৪৪৪", "en": "Sahih al-Bukhari 444"}}, {"type": "list", "items": [{"bn": "হুকুম: অধিকাংশ আলেমের মতে সুন্নত (মুস্তাহাব)।", "en": "Ruling: sunnah (recommended) according to most scholars."}, {"bn": "মসজিদে ঢুকে বসার আগে পড়বেন। ঢুকেই কোনো ফরজ বা সুন্নত নামাজ পড়লে তাতেই তাহিয়্যাতুল মসজিদ আদায় হয়ে যায়; আলাদা পড়তে হয় না।", "en": "Pray before sitting. If you start a fard or sunnah prayer on entering, it counts; no separate prayer is needed."}, {"bn": "হানাফি মতে মাকরুহ সময়ে (সূর্যোদয়, ঠিক দুপুর, সূর্যাস্ত, এবং ফজর ও আসরের পর) পড়বেন না; তখন জিকির করুন। শাফেয়ি মতে এটি কারণযুক্ত নামাজ বলে সেই সময়েও পড়া যায়।", "en": "Hanafis do not pray it in the disliked times (sunrise, noon, sunset, after Fajr and ''Asr) but make dhikr instead; Shafi''is allow it then since it has a cause."}, {"bn": "জুমার খুতবা চলাকালে ঢুকলে কী করবেন, তা নিয়ে মতভেদ আছে; ‘জুমার নামাজ’ অধ্যায় দেখুন।", "en": "On entering during the Friday khutbah, scholars differ; see the Jumu''ah guide."}, {"bn": "ইকামত হয়ে গেলে তাহিয়্যাতুল মসজিদ না পড়ে জামাতে শরিক হবেন।", "en": "If the iqamah has been called, join the congregation instead."}]}, {"type": "heading", "text": {"bn": "তাহিয়্যাতুল ওযু", "en": "Tahiyyat al-wudu (prayer after wudu)"}}, {"type": "text", "text": {"bn": "ওযু করার পর দুই রাকাত নফল পড়া সুন্নত। নবীজি (সা.) বলেছেন, যে মুসলিম সুন্দরভাবে ওযু করে, তারপর মন ও মুখ পুরোপুরি নামাজে নিবদ্ধ রেখে দুই রাকাত পড়ে, তার জন্য জান্নাত অবধারিত হয়ে যায় (সহিহ মুসলিম ২৩৪)।", "en": "Praying two rak''ahs after wudu is sunnah. The Prophet said: any Muslim who performs wudu well, then prays two rak''ahs with heart and face devoted to them, Paradise becomes due for him (Sahih Muslim 234)."}}, {"type": "text", "text": {"bn": "নবীজি (সা.) বিলাল (রা.)-কে জিজ্ঞেস করলেন, ইসলামে তাঁর সবচেয়ে আশাব্যঞ্জক আমল কী, কারণ জান্নাতে তিনি বিলালের জুতার আওয়াজ শুনেছেন। বিলাল (রা.) বললেন, দিনে বা রাতে যখনই ওযু করেছি, সেই ওযু দিয়ে যতটুকু তাওফিক হয়েছে নামাজ পড়েছি (সহিহ বুখারি ১১৪৯)।", "en": "The Prophet asked Bilal about his most hopeful deed, as he had heard his footsteps in Paradise. Bilal said: whenever I made wudu, day or night, I prayed with it as much as was written for me (Sahih al-Bukhari 1149)."}}, {"type": "list", "items": [{"bn": "ওযুর অঙ্গ শুকানোর আগেই পড়া উত্তম বলে আলেমরা উল্লেখ করেছেন।", "en": "Scholars mention it is best to pray before the limbs dry."}, {"bn": "হানাফি মতে মাকরুহ সময়ে পড়বেন না।", "en": "Hanafis do not pray it in the disliked times."}, {"bn": "ওযুর পর কোনো ফরজ বা সুন্নত পড়লেও এর সওয়াব পাওয়ার আশা করা যায়।", "en": "One may hope for its reward even when praying a fard or sunnah right after wudu."}]}, {"type": "note", "tone": "tip", "text": {"bn": "নিয়ত মনে মনে করাই যথেষ্ট। উদাহরণ (প্রচলিত বাংলা): ‘আমি আল্লাহর জন্য দুই রাকাত তাহিয়্যাতুল মসজিদ (বা তাহিয়্যাতুল ওযু) নামাজ পড়ছি।’", "en": "The intention in the heart is enough. Example (common Bangla phrasing): ''I am praying two rak''ahs of tahiyyat al-masjid (or al-wudu) for Allah.''"}}]', 'in_review', 140 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'ca0d0339-e193-5ad5-a740-3f884431db8f', id, 'sajdah-tilawah', '{"bn": "সিজদায়ে তিলাওয়াত", "en": "Sajdah al-Tilawah (Prostration of Recitation)"}', '{"bn": "কুরআনের নির্দিষ্ট আয়াত পড়লে বা শুনলে যে সিজদা দিতে হয়: হুকুম, পদ্ধতি, দোয়া এবং সিজদার ১৫টি আয়াতের তালিকা।", "en": "The prostration made on reciting or hearing certain verses: ruling, method, du''a, and the list of the 15 places."}', 'basic', '[{"type": "text", "text": {"bn": "কুরআনের কিছু আয়াত পড়লে বা শুনলে একটি সিজদা দিতে হয়; একে সিজদায়ে তিলাওয়াত বলে। মুসহাফে এসব আয়াতের পাশে সাধারণত ‘۩’ চিহ্ন বা ‘সিজদা’ লেখা থাকে। নবীজি (সা.) বলেছেন, আদম সন্তান সিজদার আয়াত পড়ে সিজদা করলে শয়তান কাঁদতে কাঁদতে সরে যায় (সহিহ মুসলিম ৮১)।", "en": "Certain verses call for a prostration when recited or heard; this is sajdah al-tilawah. In the Mushaf they are usually marked with ''۩'' or the word ''sajdah''. The Prophet said that when the son of Adam recites a verse of prostration and prostrates, Shaytan withdraws weeping (Sahih Muslim 81)."}}, {"type": "differ", "title": {"bn": "হুকুম", "en": "Ruling"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "যে পড়ে এবং যে শোনে, উভয়ের ওপর ওয়াজিব।", "en": "Wajib on both the reciter and the listener."}, "evidence": {"bn": "কয়েকটি সিজদার আয়াতে সরাসরি সিজদার নির্দেশ আছে, যেমন ‘ফাসজুদূ লিল্লাহি ওয়া''বুদূ’ (সূরা নাজম ৫৩:৬২), ‘ওয়াসজুদ ওয়াকতারিব’ (সূরা আলাক ৯৬:১৯); সহিহ মুসলিম ৮১।", "en": "Some of these verses command prostration, e.g. An-Najm 53:62 and Al-''Alaq 96:19; Sahih Muslim 81."}}, {"label": {"bn": "শাফেয়ি, মালেকি ও হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "সুন্নতে মুয়াক্কাদা, ওয়াজিব নয়।", "en": "A confirmed sunnah, not obligatory."}, "evidence": {"bn": "উমর (রা.) জুমার খুতবায় সিজদার আয়াত পড়ে একবার সিজদা করেন, আরেক জুমায় করেননি এবং বলেন, আল্লাহ এটি ফরজ করেননি, তবে আমরা চাইলে করি (সহিহ বুখারি ১০৭৭); যায়েদ ইবনে সাবিত (রা.) নবীজি (সা.)-এর সামনে সূরা নাজম পড়লেন, তিনি সিজদা করেননি (সহিহ বুখারি ১০৭২)।", "en": "''Umar prostrated on the minbar one Friday and not the next, saying Allah had not made it obligatory (Sahih al-Bukhari 1077); Zayd ibn Thabit recited An-Najm before the Prophet and he did not prostrate (Sahih al-Bukhari 1072)."}}]}, {"type": "heading", "text": {"bn": "পদ্ধতি (হানাফি)", "en": "Method (Hanafi)"}}, {"type": "step", "title": {"bn": "পবিত্রতা ও কিবলা", "en": "Purity and qiblah"}, "text": {"bn": "নামাজের মতোই ওযু, পবিত্র কাপড় ও জায়গা, সতর ঢাকা ও কিবলামুখী হওয়া শর্ত (অধিকাংশ আলেমের মত)।", "en": "As for prayer: wudu, clean clothes and place, covered awrah, facing the qiblah (view of most scholars)."}}, {"type": "step", "title": {"bn": "নিয়ত", "en": "Intention"}, "text": {"bn": "মনে মনে সিজদায়ে তিলাওয়াতের নিয়ত করুন। দাঁড়িয়ে থেকে সিজদায় যাওয়া মুস্তাহাব, বসে থেকেও যাওয়া যায়।", "en": "Intend the prostration of recitation in your heart. Going down from standing is preferred; from sitting is also fine."}}, {"type": "step", "title": {"bn": "তাকবির বলে সিজদা", "en": "Takbir and prostrate"}, "text": {"bn": "হাত না তুলে ‘আল্লাহু আকবার’ বলে একটি সিজদা করুন; সিজদায় অন্তত তিনবার ‘সুবহানা রাব্বিয়াল আ''লা’ পড়ুন বা নিচের দোয়াটি পড়ুন।", "en": "Without raising your hands, say ''Allahu Akbar'' and make one sajdah; say ''Subhana Rabbiyal-A''la'' at least three times or the du''a below."}}, {"type": "step", "title": {"bn": "তাকবির বলে উঠা", "en": "Rise with takbir"}, "text": {"bn": "‘আল্লাহু আকবার’ বলে উঠে যান। হানাফি মতে নামাজের বাইরে এই সিজদায় তাশাহহুদ বা সালাম নেই।", "en": "Rise saying ''Allahu Akbar''. In the Hanafi school there is no tashahhud or salam for it outside prayer."}}, {"type": "arabic", "label": {"bn": "সিজদায়ে তিলাওয়াতের দোয়া", "en": "Du''a in the prostration of recitation"}, "ar": "سَجَدَ وَجْهِيَ لِلَّذِي خَلَقَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ بِحَوْلِهِ وَقُوَّتِهِ", "pron": {"bn": "সাজাদা ওয়াজহিয়া লিল্লাযী খালাকাহূ, ওয়া শাক্কা সাম''আহূ ওয়া বাসারাহূ বিহাওলিহী ওয়া কুওয়াতিহ।", "en": "Sajada wajhiya lilladhi khalaqahu, wa shaqqa sam''ahu wa basarahu bihawlihi wa quwwatih."}, "meaning": {"bn": "আমার মুখমণ্ডল সিজদা করল সেই সত্তার জন্য, যিনি একে সৃষ্টি করেছেন এবং নিজ শক্তি ও সামর্থ্যে এর কান ও চোখ খুলে দিয়েছেন।", "en": "My face prostrates to the One who created it and brought forth its hearing and sight by His might and power."}, "ref": {"bn": "জামে তিরমিজি ৫৮০; সুনান আবু দাউদ ১৪১৪", "en": "Jami'' al-Tirmidhi 580; Sunan Abi Dawud 1414"}}, {"type": "note", "tone": "info", "text": {"bn": "এই দোয়ার হাদিসকে শাইখ আলবানিসহ অনেকে সহিহ বলেছেন, তবে আবু দাউদের সনদে একজন অজ্ঞাত বর্ণনাকারী থাকায় কেউ কেউ দুর্বল বলেছেন। ‘সুবহানা রাব্বিয়াল আ''লা’ পড়াই যথেষ্ট।", "en": "Many, including al-Albani, graded this du''a''s hadith sahih, though some called it weak because Abu Dawud''s chain has an unnamed narrator. Saying ''Subhana Rabbiyal-A''la'' is enough."}}, {"type": "heading", "text": {"bn": "কিছু মাসআলা", "en": "Some rulings"}}, {"type": "list", "items": [{"bn": "নামাজের মধ্যে সিজদার আয়াত পড়লে সাথে সাথে (তিন আয়াত পরিমাণ দেরির আগে) সিজদা করে দাঁড়িয়ে বাকি কিরাত পড়বেন। ইমাম পড়লে মুক্তাদিরাও ইমামের সাথে সিজদা করবেন।", "en": "If recited in prayer, prostrate promptly (before about three verses'' delay), then stand and continue. Followers prostrate with the imam."}, {"bn": "নামাজের বাইরে পড়লে সাথে সাথে করা উত্তম; পরে করলেও আদায় হয়ে যায় (হানাফি)।", "en": "Outside prayer, it is best done at once, but may be done later (Hanafi)."}, {"bn": "একই বৈঠকে একই আয়াত বারবার পড়লে বা শুনলে একটি সিজদাই যথেষ্ট (হানাফি)।", "en": "Repeating the same verse in one sitting needs only one prostration (Hanafi)."}, {"bn": "সিজদার আয়াতের শুধু অনুবাদ পড়লে বা রেকর্ড করা তিলাওয়াত শুনলে সিজদা ওয়াজিব হয় কি না, তা নিয়ে আলেমদের মতভেদ আছে; অনেকের মতে রেকর্ডিং শুনলে ওয়াজিব হয় না।", "en": "Scholars differ on whether reading only a translation or hearing a recording requires it; many say a recording does not."}, {"bn": "ঋতুস্রাব বা নিফাস অবস্থায় শুনলে নারীর ওপর সিজদা ওয়াজিব হয় না (হানাফি)।", "en": "A woman in menstruation or post-natal bleeding who hears it owes no prostration (Hanafi)."}], "check": true}, {"type": "heading", "text": {"bn": "কুরআনে সিজদার আয়াতসমূহ", "en": "The verses of prostration"}}, {"type": "table", "head": [{"bn": "ক্রম", "en": "No."}, {"bn": "সূরা", "en": "Surah"}, {"bn": "আয়াত", "en": "Ayah"}, {"bn": "পারা", "en": "Juz''"}, {"bn": "মন্তব্য", "en": "Note"}], "rows": [[{"bn": "১", "en": "1"}, {"bn": "আ''রাফ (৭)", "en": "Al-A''raf (7)"}, {"bn": "২০৬", "en": "206"}, {"bn": "৯", "en": "9"}, {"bn": "সর্বসম্মত", "en": "Agreed"}], [{"bn": "২", "en": "2"}, {"bn": "রা''দ (১৩)", "en": "Ar-Ra''d (13)"}, {"bn": "১৫", "en": "15"}, {"bn": "১৩", "en": "13"}, {"bn": "সর্বসম্মত", "en": "Agreed"}], [{"bn": "৩", "en": "3"}, {"bn": "নাহল (১৬)", "en": "An-Nahl (16)"}, {"bn": "৫০", "en": "50"}, {"bn": "১৪", "en": "14"}, {"bn": "সর্বসম্মত", "en": "Agreed"}], [{"bn": "৪", "en": "4"}, {"bn": "বনি ইসরাঈল / ইসরা (১৭)", "en": "Al-Isra (17)"}, {"bn": "১০৯", "en": "109"}, {"bn": "১৫", "en": "15"}, {"bn": "সর্বসম্মত", "en": "Agreed"}], [{"bn": "৫", "en": "5"}, {"bn": "মারইয়াম (১৯)", "en": "Maryam (19)"}, {"bn": "৫৮", "en": "58"}, {"bn": "১৬", "en": "16"}, {"bn": "সর্বসম্মত", "en": "Agreed"}], [{"bn": "৬", "en": "6"}, {"bn": "হজ (২২)", "en": "Al-Hajj (22)"}, {"bn": "১৮", "en": "18"}, {"bn": "১৭", "en": "17"}, {"bn": "সর্বসম্মত", "en": "Agreed"}], [{"bn": "৭", "en": "7"}, {"bn": "হজ (২২)", "en": "Al-Hajj (22)"}, {"bn": "৭৭", "en": "77"}, {"bn": "১৭", "en": "17"}, {"bn": "শাফেয়ি ও হাম্বলি মতে সিজদা; হানাফি ও মালেকি মতে এটি নামাজের সিজদার নির্দেশ, তিলাওয়াতের সিজদা নয়", "en": "A prostration for Shafi''is and Hanbalis; Hanafis and Malikis see it as about the prayer''s sajdah, not a sajdah of recitation"}], [{"bn": "৮", "en": "8"}, {"bn": "ফুরকান (২৫)", "en": "Al-Furqan (25)"}, {"bn": "৬০", "en": "60"}, {"bn": "১৯", "en": "19"}, {"bn": "সর্বসম্মত", "en": "Agreed"}], [{"bn": "৯", "en": "9"}, {"bn": "নামল (২৭)", "en": "An-Naml (27)"}, {"bn": "২৬", "en": "26"}, {"bn": "১৯", "en": "19"}, {"bn": "সর্বসম্মত", "en": "Agreed"}], [{"bn": "১০", "en": "10"}, {"bn": "সাজদা (৩২)", "en": "As-Sajdah (32)"}, {"bn": "১৫", "en": "15"}, {"bn": "২১", "en": "21"}, {"bn": "সর্বসম্মত", "en": "Agreed"}], [{"bn": "১১", "en": "11"}, {"bn": "সোয়াদ (৩৮)", "en": "Sad (38)"}, {"bn": "২৪", "en": "24"}, {"bn": "২৩", "en": "23"}, {"bn": "হানাফি ও মালেকি মতে তিলাওয়াতের সিজদা; শাফেয়ি ও হাম্বলি মতে শুকরের সিজদা (নামাজের ভেতরে নয়)", "en": "A sajdah of recitation for Hanafis and Malikis; for Shafi''is and Hanbalis a prostration of thanks (not inside prayer)"}], [{"bn": "১২", "en": "12"}, {"bn": "হা-মিম সাজদা / ফুসসিলাত (৪১)", "en": "Fussilat (41)"}, {"bn": "৩৮", "en": "38"}, {"bn": "২৪", "en": "24"}, {"bn": "সর্বসম্মত (মালেকি মতে আয়াত ৩৭-এ)", "en": "Agreed (Maliki: at ayah 37)"}], [{"bn": "১৩", "en": "13"}, {"bn": "নাজম (৫৩)", "en": "An-Najm (53)"}, {"bn": "৬২", "en": "62"}, {"bn": "২৭", "en": "27"}, {"bn": "মালেকি প্রসিদ্ধ মতে নয়, অন্যদের মতে সিজদা", "en": "Not in the well-known Maliki view; a sajdah for the others"}], [{"bn": "১৪", "en": "14"}, {"bn": "ইনশিকাক (৮৪)", "en": "Al-Inshiqaq (84)"}, {"bn": "২১", "en": "21"}, {"bn": "৩০", "en": "30"}, {"bn": "মালেকি প্রসিদ্ধ মতে নয়, অন্যদের মতে সিজদা", "en": "Not in the well-known Maliki view; a sajdah for the others"}], [{"bn": "১৫", "en": "15"}, {"bn": "আলাক (৯৬)", "en": "Al-''Alaq (96)"}, {"bn": "১৯", "en": "19"}, {"bn": "৩০", "en": "30"}, {"bn": "মালেকি প্রসিদ্ধ মতে নয়, অন্যদের মতে সিজদা", "en": "Not in the well-known Maliki view; a sajdah for the others"}]]}, {"type": "text", "text": {"bn": "হানাফি মতে সিজদার আয়াত মোট ১৪টি (তালিকার ৭ নম্বর বাদে)। শাফেয়ি ও হাম্বলি মতেও ১৪টি (১১ নম্বর বাদে)। আয়াত নম্বর প্রচলিত মুসহাফ (হাফস) অনুযায়ী।", "en": "Hanafis count 14 (all except no. 7). Shafi''is and Hanbalis also count 14 (all except no. 11). Ayah numbers follow the common (Hafs) Mushaf."}}, {"type": "note", "tone": "info", "text": {"bn": "সূরা নাজমের সিজদা নবীজি (সা.) মক্কায় করেছেন এবং সাথের সবাই সিজদা করেছিল (সহিহ বুখারি ১০৬৭)।", "en": "The Prophet prostrated at An-Najm in Makkah and those with him did too (Sahih al-Bukhari 1067)."}}]', 'in_review', 150 FROM is_guide_topics WHERE slug = 'special_salah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '48df6e66-b152-518c-bc7d-d246bcb9653e', id, 'six-kalimas', '{"bn": "ছয় কালিমা", "en": "The Six Kalimas"}', '{"bn": "বাংলাদেশে প্রচলিতভাবে শেখানো ছয় কালিমা: আরবি, উচ্চারণ ও অর্থ, এবং প্রতিটির উৎস সম্পর্কে সংক্ষিপ্ত তথ্য।", "en": "The six kalimas as commonly taught in Bangladesh: Arabic, pronunciation and meaning, with a note on each one''s source."}', 'basic', '[{"type": "note", "tone": "info", "text": {"bn": "‘ছয় কালিমা’ নামে এই তালিকা উপমহাদেশে শিশুদের ঈমানের মৌলিক কথা শেখানোর একটি প্রচলিত পদ্ধতি; কুরআন বা হাদিসে এই ছয়টিকে একসাথে ‘ছয় কালিমা’ বলা হয়নি। প্রথম দুটির শব্দ কুরআন-হাদিসে সরাসরি আছে; বাকিগুলোর কিছু অংশ হাদিস বা কুরআন থেকে নেওয়া, আর কিছু অংশ শিক্ষার উদ্দেশ্যে সাজানো, যার অর্থ ইসলামি আকিদার সাথে সামঞ্জস্যপূর্ণ। অঞ্চলভেদে ক্রম ও শব্দেও ভিন্নতা আছে (যেমন পাকিস্তান-ভারতে ‘তামজীদ’ হিসেবে ‘সুবহানাল্লাহি ওয়াল হামদু লিল্লাহ...’ পড়ানো হয়)।", "en": "The ''six kalimas'' list is a teaching tradition in the subcontinent for teaching children the basics of faith; the Quran and hadith do not group these six together. The first two are found directly in the Quran and hadith; the others combine phrases from the Quran or hadith with wording arranged for teaching, whose meanings agree with Islamic belief. The order and wording vary by region (e.g. in Pakistan and India ''Tamjid'' is ''Subhanallahi wal-hamdu lillah...'')."}}, {"type": "heading", "text": {"bn": "১. কালিমা তাইয়্যেবা", "en": "1. Kalima Tayyibah (the pure word)"}}, {"type": "arabic", "label": {"bn": "কালিমা তাইয়্যেবা", "en": "Kalima Tayyibah"}, "ar": "لَا إِلٰهَ إِلَّا اللّٰهُ مُحَمَّدٌ رَسُولُ اللّٰهِ", "pron": {"bn": "লা ইলাহা ইল্লাল্লাহু মুহাম্মাদুর রাসূলুল্লাহ।", "en": "La ilaha illallahu Muhammadur Rasulullah."}, "meaning": {"bn": "আল্লাহ ছাড়া কোনো ইলাহ (সত্য উপাস্য) নেই, মুহাম্মাদ (সা.) আল্লাহর রাসুল।", "en": "There is no god (worthy of worship) but Allah; Muhammad is the Messenger of Allah."}, "ref": {"bn": "দুই অংশ কুরআনে: সূরা মুহাম্মাদ ৪৭:১৯ ও সূরা ফাতহ ৪৮:২৯", "en": "Both parts in the Quran: Muhammad 47:19 and Al-Fath 48:29"}}, {"type": "heading", "text": {"bn": "২. কালিমা শাহাদাত", "en": "2. Kalima Shahadah (testimony)"}}, {"type": "arabic", "label": {"bn": "কালিমা শাহাদাত", "en": "Kalima Shahadah"}, "ar": "أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ", "pron": {"bn": "আশহাদু আল লা ইলাহা ইল্লাল্লাহু ওয়াহদাহূ লা শারীকা লাহূ, ওয়া আশহাদু আন্না মুহাম্মাদান আবদুহূ ওয়া রাসূলুহ।", "en": "Ashhadu al la ilaha illallahu wahdahu la sharika lah, wa ashhadu anna Muhammadan ''abduhu wa rasuluh."}, "meaning": {"bn": "আমি সাক্ষ্য দিচ্ছি যে আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি এক, তাঁর কোনো শরিক নেই; এবং আমি সাক্ষ্য দিচ্ছি যে মুহাম্মাদ (সা.) তাঁর বান্দা ও রাসুল।", "en": "I bear witness that there is no god but Allah, alone, without partner, and I bear witness that Muhammad is His servant and Messenger."}, "ref": {"bn": "সহিহ মুসলিম ২৩৪ (ওযুর পর এই শাহাদাত পড়ার ফজিলত)", "en": "Sahih Muslim 234 (virtue of saying it after wudu)"}}, {"type": "heading", "text": {"bn": "৩. কালিমা তাওহীদ", "en": "3. Kalima Tawhid (oneness)"}}, {"type": "arabic", "label": {"bn": "কালিমা তাওহীদ (বাংলাদেশে প্রচলিত পাঠ)", "en": "Kalima Tawhid (as taught in Bangladesh)"}, "ar": "لَا إِلٰهَ إِلَّا أَنْتَ وَاحِدًا لَا ثَانِيَ لَكَ، مُحَمَّدٌ رَسُولُ اللّٰهِ إِمَامُ الْمُتَّقِينَ رَسُولُ رَبِّ الْعَالَمِينَ", "pron": {"bn": "লা ইলাহা ইল্লা আনতা ওয়াহিদাল লা সানিয়া লাকা, মুহাম্মাদুর রাসূলুল্লাহি ইমামুল মুত্তাকীনা রাসূলু রাব্বিল আলামীন।", "en": "La ilaha illa anta wahidan la thaniya lak, Muhammadur Rasulullahi imamul-muttaqina rasulu Rabbil-''alamin."}, "meaning": {"bn": "(হে আল্লাহ,) তুমি ছাড়া কোনো ইলাহ নেই, তুমি এক, তোমার কোনো দ্বিতীয় নেই। মুহাম্মাদ (সা.) আল্লাহর রাসুল, মুত্তাকিদের ইমাম, জগতসমূহের রবের রাসুল।", "en": "There is no god but You, One, with no second to You. Muhammad is the Messenger of Allah, leader of the God-fearing, messenger of the Lord of the worlds."}, "ref": {"bn": "শিক্ষার উদ্দেশ্যে সাজানো পাঠ; হুবহু এই শব্দে কোনো হাদিস জানা নেই", "en": "A teaching text; no hadith with this exact wording is known"}, "check": true}, {"type": "heading", "text": {"bn": "৪. কালিমা তামজীদ", "en": "4. Kalima Tamjid (glorification)"}}, {"type": "arabic", "label": {"bn": "কালিমা তামজীদ (বাংলাদেশে প্রচলিত পাঠ)", "en": "Kalima Tamjid (as taught in Bangladesh)"}, "ar": "لَا إِلٰهَ إِلَّا أَنْتَ نُورًا يَهْدِي اللّٰهُ لِنُورِهِ مَنْ يَشَاءُ، مُحَمَّدٌ رَسُولُ اللّٰهِ إِمَامُ الْمُرْسَلِينَ خَاتَمُ النَّبِيِّينَ", "pron": {"bn": "লা ইলাহা ইল্লা আনতা নূরাই ইয়াহদিয়াল্লাহু লিনূরিহী মাই ইয়াশাউ, মুহাম্মাদুর রাসূলুল্লাহি ইমামুল মুরসালীনা খাতামুন নাবিয়্যীন।", "en": "La ilaha illa anta nuran yahdillahu linurihi man yasha'', Muhammadur Rasulullahi imamul-mursalina khatamun-nabiyyin."}, "meaning": {"bn": "(হে আল্লাহ,) তুমি ছাড়া কোনো ইলাহ নেই, তুমি নূর (আলো); আল্লাহ যাকে চান তাঁর নূরের দিকে পথ দেখান। মুহাম্মাদ (সা.) আল্লাহর রাসুল, রাসুলদের ইমাম, সর্বশেষ নবী।", "en": "There is no god but You, the Light; Allah guides to His light whom He wills. Muhammad is the Messenger of Allah, leader of the messengers, the last of the prophets."}, "ref": {"bn": "শিক্ষার উদ্দেশ্যে সাজানো পাঠ; ‘ইয়াহদিল্লাহু লিনূরিহী মাই ইয়াশা’ অংশ সূরা নূর ২৪:৩৫ থেকে, ‘খাতামুন নাবিয়্যীন’ সূরা আহযাব ৩৩:৪০ থেকে", "en": "A teaching text; ''Allah guides to His light whom He wills'' is from An-Nur 24:35 and ''last of the prophets'' from Al-Ahzab 33:40"}, "check": true}, {"type": "heading", "text": {"bn": "৫. কালিমা রদ্দে কুফর", "en": "5. Kalima Radd al-Kufr (rejecting disbelief)"}}, {"type": "arabic", "label": {"bn": "কালিমা রদ্দে কুফর", "en": "Kalima Radd al-Kufr"}, "ar": "اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ أَنْ أُشْرِكَ بِكَ شَيْئًا وَأَنَا أَعْلَمُ بِهِ، وَأَسْتَغْفِرُكَ لِمَا لَا أَعْلَمُ بِهِ، تُبْتُ عَنْهُ، وَتَبَرَّأْتُ مِنَ الْكُفْرِ وَالشِّرْكِ وَالْمَعَاصِي كُلِّهَا، وَأَسْلَمْتُ وَآمَنْتُ، وَأَقُولُ: لَا إِلٰهَ إِلَّا اللّٰهُ مُحَمَّدٌ رَسُولُ اللّٰهِ", "pron": {"bn": "আল্লাহুম্মা ইন্নী আঊযুবিকা মিন আন উশরিকা বিকা শাইআও ওয়া আনা আ''লামু বিহী, ওয়া আসতাগফিরুকা লিমা লা আ''লামু বিহী, তুবতু আনহু, ওয়া তাবাররা''তু মিনাল কুফরি ওয়াশ শিরকি ওয়াল মাআসী কুল্লিহা, ওয়া আসলামতু ওয়া আমানতু, ওয়া আকূলু লা ইলাহা ইল্লাল্লাহু মুহাম্মাদুর রাসূলুল্লাহ।", "en": "Allahumma inni a''udhu bika min an ushrika bika shay''an wa ana a''lamu bih, wa astaghfiruka lima la a''lamu bih, tubtu ''anhu, wa tabarra''tu minal-kufri wash-shirki wal-ma''asi kulliha, wa aslamtu wa amantu, wa aqulu la ilaha illallahu Muhammadur Rasulullah."}, "meaning": {"bn": "হে আল্লাহ, জেনে-বুঝে তোমার সাথে কিছু শরিক করা থেকে আমি তোমার আশ্রয় চাই, আর না জেনে যা করে ফেলি তার জন্য তোমার কাছে ক্ষমা চাই; আমি তা থেকে তওবা করলাম। আমি কুফর, শিরক ও সকল গুনাহ থেকে সম্পর্কমুক্ত হলাম। আমি ইসলাম গ্রহণ করলাম ও ঈমান আনলাম, এবং বলছি: আল্লাহ ছাড়া কোনো ইলাহ নেই, মুহাম্মাদ (সা.) আল্লাহর রাসুল।", "en": "O Allah, I seek refuge in You from knowingly associating anything with You, and I seek Your forgiveness for what I do unknowingly; I repent from it. I disown disbelief, shirk and all sins. I submit and I believe, and I say: there is no god but Allah, Muhammad is the Messenger of Allah."}, "ref": {"bn": "প্রথম অংশের কাছাকাছি দোয়া (শিরক থেকে আশ্রয়) ইমাম বুখারির আল-আদাবুল মুফরাদে বর্ণিত; বাকি অংশ শিক্ষার উদ্দেশ্যে সাজানো", "en": "A du''a close to the first part (refuge from shirk) is in al-Bukhari''s al-Adab al-Mufrad; the rest is arranged for teaching"}, "check": true}, {"type": "heading", "text": {"bn": "৬. কালিমা ইস্তেগফার", "en": "6. Kalima Istighfar (seeking forgiveness)"}}, {"type": "arabic", "label": {"bn": "কালিমা ইস্তেগফার", "en": "Kalima Istighfar"}, "ar": "أَسْتَغْفِرُ اللّٰهَ رَبِّي مِنْ كُلِّ ذَنْبٍ أَذْنَبْتُهُ عَمْدًا أَوْ خَطَأً، سِرًّا أَوْ عَلَانِيَةً، وَأَتُوبُ إِلَيْهِ مِنَ الذَّنْبِ الَّذِي أَعْلَمُ، وَمِنَ الذَّنْبِ الَّذِي لَا أَعْلَمُ، إِنَّكَ أَنْتَ عَلَّامُ الْغُيُوبِ، وَسَتَّارُ الْعُيُوبِ، وَغَفَّارُ الذُّنُوبِ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ الْعَلِيِّ الْعَظِيمِ", "pron": {"bn": "আসতাগফিরুল্লাহা রাব্বী মিন কুল্লি যামবিন আযনাবতুহূ আমদান আও খাতাআন, সিররান আও আলানিয়াতান, ওয়া আতূবু ইলাইহি মিনায যামবিল্লাযী আ''লামু, ওয়া মিনায যামবিল্লাযী লা আ''লামু, ইন্নাকা আনতা আল্লামুল গুয়ূবি, ওয়া সাত্তারুল উয়ূবি, ওয়া গাফফারুয যুনূবি, ওয়া লা হাওলা ওয়া লা কুওয়াতা ইল্লা বিল্লাহিল আলিয়্যিল আযীম।", "en": "Astaghfirullaha Rabbi min kulli dhanbin adhnabtuhu ''amdan aw khata''an, sirran aw ''alaniyah, wa atubu ilayhi minadh-dhanbil-ladhi a''lamu, wa minadh-dhanbil-ladhi la a''lamu, innaka anta ''allamul-ghuyubi, wa sattarul-''uyubi, wa ghaffarudh-dhunubi, wa la hawla wa la quwwata illa billahil-''aliyyil-''azim."}, "meaning": {"bn": "আমি আমার রব আল্লাহর কাছে ক্ষমা চাই সেই সব গুনাহের জন্য, যা আমি ইচ্ছায় বা ভুলে, গোপনে বা প্রকাশ্যে করেছি; আর তাঁর কাছে তওবা করি সেই গুনাহ থেকে যা আমি জানি এবং যা আমি জানি না। নিশ্চয়ই তুমি অদৃশ্য বিষয়ে সর্বজ্ঞ, দোষ গোপনকারী ও গুনাহ ক্ষমাকারী। মহান ও সুউচ্চ আল্লাহর সাহায্য ছাড়া গুনাহ থেকে বাঁচার ও নেক কাজ করার কোনো শক্তি নেই।", "en": "I seek forgiveness from Allah, my Lord, for every sin I committed, deliberately or by mistake, secretly or openly, and I turn to Him in repentance from the sin I know and the sin I do not know. You are the Knower of the unseen, the Concealer of faults, the Forgiver of sins. There is no power or strength except with Allah, the Most High, the Most Great."}, "ref": {"bn": "শিক্ষার উদ্দেশ্যে সাজানো পাঠ; ‘লা হাওলা ওয়া লা কুওয়াতা ইল্লা বিল্লাহ’ সহিহ হাদিসে প্রমাণিত", "en": "A teaching text; ''la hawla wa la quwwata illa billah'' is established in sahih hadith"}, "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "ইস্তিগফারের জন্য সহিহ হাদিসে সবচেয়ে শ্রেষ্ঠ দোয়া হলো ‘সাইয়্যিদুল ইস্তিগফার’ (সহিহ বুখারি ৬৩০৬)। কালিমাগুলো মুখস্থ করার পাশাপাশি অর্থ বোঝা এবং জীবনে তাওহীদ মেনে চলাই আসল উদ্দেশ্য।", "en": "The best istighfar in sahih hadith is ''Sayyid al-Istighfar'' (Sahih al-Bukhari 6306). Beyond memorising, the real aim is to understand the meaning and live by tawhid."}}]', 'in_review', 10 FROM is_guide_topics WHERE slug = 'kalima' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'c6ff5b70-7cc4-58d9-a5ed-3f1b5535b00b', id, 'iman-mujmal-mufassal', '{"bn": "ঈমানে মুজমাল ও ঈমানে মুফাসসাল", "en": "Iman Mujmal and Iman Mufassal"}', '{"bn": "ঈমানের সংক্ষিপ্ত (মুজমাল) ও বিস্তারিত (মুফাসসাল) ঘোষণা: আরবি, উচ্চারণ, অর্থ ও কুরআন-হাদিসে এর ভিত্তি।", "en": "The brief (mujmal) and detailed (mufassal) declarations of faith: Arabic, pronunciation, meaning and their basis in the Quran and hadith."}', 'basic', '[{"type": "text", "text": {"bn": "ঈমানে মুজমাল ও ঈমানে মুফাসসাল ঈমানের মূল বিষয়গুলো সংক্ষেপে মনে রাখার জন্য সাজানো দুটি ঘোষণা। হুবহু এই শব্দে কোনো হাদিস নেই, তবে এর প্রতিটি বিষয় কুরআন ও হাদিসে জিবরিলে (সহিহ মুসলিম ৮) প্রমাণিত।", "en": "Iman mujmal and iman mufassal are two declarations arranged to help remember the essentials of faith. No hadith has this exact wording, but every item is established in the Quran and the Hadith of Jibril (Sahih Muslim 8)."}}, {"type": "heading", "text": {"bn": "ঈমানে মুজমাল (সংক্ষিপ্ত ঈমান)", "en": "Iman Mujmal (faith in brief)"}}, {"type": "arabic", "label": {"bn": "ঈমানে মুজমাল", "en": "Iman Mujmal"}, "ar": "آمَنْتُ بِاللّٰهِ كَمَا هُوَ بِأَسْمَائِهِ وَصِفَاتِهِ، وَقَبِلْتُ جَمِيعَ أَحْكَامِهِ وَأَرْكَانِهِ", "pron": {"bn": "আমানতু বিল্লাহি কামা হুয়া বিআসমায়িহী ওয়া সিফাতিহী, ওয়া কাবিলতু জামীআ আহকামিহী ওয়া আরকানিহ।", "en": "Amantu billahi kama huwa bi-asma''ihi wa sifatihi, wa qabiltu jami''a ahkamihi wa arkanih."}, "meaning": {"bn": "আমি আল্লাহর প্রতি ঈমান আনলাম, তিনি যেমন আছেন তাঁর সব নাম ও গুণাবলিসহ; এবং আমি তাঁর সকল বিধান ও রুকন (মৌলিক বিষয়) মেনে নিলাম।", "en": "I believe in Allah as He is, with His names and attributes, and I accept all His commands and pillars."}, "ref": {"bn": "শিক্ষার উদ্দেশ্যে সাজানো ঘোষণা", "en": "A declaration arranged for teaching"}, "check": true}, {"type": "heading", "text": {"bn": "ঈমানে মুফাসসাল (বিস্তারিত ঈমান)", "en": "Iman Mufassal (faith in detail)"}}, {"type": "arabic", "label": {"bn": "ঈমানে মুফাসসাল", "en": "Iman Mufassal"}, "ar": "آمَنْتُ بِاللّٰهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَالْيَوْمِ الْآخِرِ وَالْقَدْرِ خَيْرِهِ وَشَرِّهِ مِنَ اللّٰهِ تَعَالَىٰ وَالْبَعْثِ بَعْدَ الْمَوْتِ", "pron": {"bn": "আমানতু বিল্লাহি ওয়া মালাইকাতিহী ওয়া কুতুবিহী ওয়া রুসুলিহী ওয়াল ইয়াওমিল আখিরি ওয়াল কাদরি খাইরিহী ওয়া শাররিহী মিনাল্লাহি তাআলা ওয়াল বা''সি বা''দাল মাওত।", "en": "Amantu billahi wa mala''ikatihi wa kutubihi wa rusulihi wal-yawmil-akhiri wal-qadri khayrihi wa sharrihi minallahi ta''ala wal-ba''thi ba''dal-mawt."}, "meaning": {"bn": "আমি ঈমান আনলাম আল্লাহর প্রতি, তাঁর ফেরেশতাদের প্রতি, তাঁর কিতাবসমূহের প্রতি, তাঁর রাসুলদের প্রতি, আখেরাতের দিনের প্রতি, তাকদিরের প্রতি যে ভালো-মন্দ সবই আল্লাহর পক্ষ থেকে, এবং মৃত্যুর পর পুনরুত্থানের প্রতি।", "en": "I believe in Allah, His angels, His books, His messengers, the Last Day, the decree, its good and its bad being from Allah the Exalted, and resurrection after death."}, "ref": {"bn": "মূল বিষয়গুলো: সূরা বাকারা ২:২৮৫; সূরা নিসা ৪:১৩৬; সহিহ মুসলিম ৮ (হাদিসে জিবরিল)", "en": "Its contents: Al-Baqarah 2:285; An-Nisa 4:136; Sahih Muslim 8 (Hadith of Jibril)"}}, {"type": "text", "text": {"bn": "ঈমানে মুফাসসালে সাতটি বিষয় বলা হয়। হাদিসে জিবরিলে ছয়টি বিষয় এসেছে; ‘মৃত্যুর পর পুনরুত্থান’ মূলত আখেরাতের প্রতি ঈমানেরই অংশ, স্পষ্ট করার জন্য আলাদা বলা হয়েছে।", "en": "Iman mufassal names seven items. The Hadith of Jibril names six; ''resurrection after death'' is part of belief in the Last Day, stated separately for emphasis."}}, {"type": "arabic", "label": {"bn": "কুরআনের ঘোষণা", "en": "The Quranic declaration"}, "ar": "آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ ۚ وَقَالُوا سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ", "pron": {"bn": "আমানার রাসূলু বিমা উনযিলা ইলাইহি মির রাব্বিহী ওয়াল মু''মিনূন, কুল্লুন আমানা বিল্লাহি ওয়া মালাইকাতিহী ওয়া কুতুবিহী ওয়া রুসুলিহ, লা নুফাররিকু বাইনা আহাদিম মির রুসুলিহ, ওয়া কালূ সামি''না ওয়া আতা''না, গুফরানাকা রাব্বানা ওয়া ইলাইকাল মাসীর।", "en": "Amanar-rasulu bima unzila ilayhi mir-Rabbihi wal-mu''minun, kullun amana billahi wa mala''ikatihi wa kutubihi wa rusulih, la nufarriqu bayna ahadim mir-rusulih, wa qalu sami''na wa ata''na, ghufranaka Rabbana wa ilaykal-masir."}, "meaning": {"bn": "রাসুল ঈমান এনেছেন তাঁর রবের পক্ষ থেকে তাঁর প্রতি যা নাজিল হয়েছে তার প্রতি, এবং মুমিনরাও। সবাই ঈমান এনেছে আল্লাহ, তাঁর ফেরেশতা, তাঁর কিতাব ও তাঁর রাসুলদের প্রতি। (তারা বলে,) আমরা তাঁর রাসুলদের কারও মধ্যে পার্থক্য করি না। আর তারা বলে, আমরা শুনলাম ও মানলাম; হে আমাদের রব, আমরা তোমার ক্ষমা চাই, আর তোমার দিকেই প্রত্যাবর্তন।", "en": "The Messenger believes in what was sent down to him from his Lord, and so do the believers. Each believes in Allah, His angels, His books and His messengers: ''We make no distinction between any of His messengers.'' And they say: ''We hear and obey. Your forgiveness, our Lord; to You is the return.''"}, "ref": {"bn": "সূরা বাকারা ২:২৮৫", "en": "Al-Baqarah 2:285"}}]', 'in_review', 20 FROM is_guide_topics WHERE slug = 'kalima' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'f6ffc93b-7862-50eb-aedf-54e2fbf35f0c', id, 'six-articles-of-faith', '{"bn": "ঈমানের ছয়টি রুকন", "en": "The Six Articles of Faith"}', '{"bn": "হাদিসে জিবরিলের আলোকে ঈমানের ছয়টি মূল বিষয় সহজভাবে, কুরআন-হাদিসের রেফারেন্সসহ।", "en": "The six articles of faith from the Hadith of Jibril, explained simply with Quran and hadith references."}', 'basic', '[{"type": "text", "text": {"bn": "একদিন সাদা পোশাক ও কালো চুলের এক ব্যক্তি নবীজি (সা.)-এর কাছে এসে ইসলাম, ঈমান, ইহসান ও কিয়ামত সম্পর্কে প্রশ্ন করেন। পরে নবীজি (সা.) জানান, তিনি ছিলেন জিবরিল (আ.), মানুষকে দ্বীন শেখাতে এসেছিলেন। এই হাদিসকে ‘হাদিসে জিবরিল’ বলা হয়।", "en": "One day a man in white clothes with black hair came to the Prophet and asked about Islam, iman, ihsan and the Hour. The Prophet later said it was Jibril, who came to teach people their religion. This is the ''Hadith of Jibril''."}}, {"type": "arabic", "label": {"bn": "ঈমানের সংজ্ঞা (হাদিসে জিবরিল)", "en": "Definition of iman (Hadith of Jibril)"}, "ar": "أَنْ تُؤْمِنَ بِاللّٰهِ، وَمَلَائِكَتِهِ، وَكُتُبِهِ، وَرُسُلِهِ، وَالْيَوْمِ الْآخِرِ، وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ", "pron": {"bn": "আন তু''মিনা বিল্লাহি, ওয়া মালাইকাতিহী, ওয়া কুতুবিহী, ওয়া রুসুলিহী, ওয়াল ইয়াওমিল আখিরি, ওয়া তু''মিনা বিলকাদারি খাইরিহী ওয়া শাররিহ।", "en": "An tu''mina billahi, wa mala''ikatihi, wa kutubihi, wa rusulihi, wal-yawmil-akhiri, wa tu''mina bil-qadari khayrihi wa sharrih."}, "meaning": {"bn": "(ঈমান হলো) তুমি ঈমান আনবে আল্লাহর প্রতি, তাঁর ফেরেশতাদের প্রতি, তাঁর কিতাবসমূহের প্রতি, তাঁর রাসুলদের প্রতি, আখেরাতের দিনের প্রতি, এবং ঈমান আনবে তাকদিরের ভালো-মন্দের প্রতি।", "en": "(Iman is) that you believe in Allah, His angels, His books, His messengers and the Last Day, and that you believe in the decree, its good and its bad."}, "ref": {"bn": "সহিহ মুসলিম ৮; সহিহ বুখারি ৫০", "en": "Sahih Muslim 8; Sahih al-Bukhari 50"}}, {"type": "step", "title": {"bn": "আল্লাহর প্রতি ঈমান", "en": "Belief in Allah"}, "text": {"bn": "আল্লাহ এক, তাঁর কোনো শরিক নেই; তিনিই সৃষ্টিকর্তা, প্রতিপালক ও একমাত্র উপাস্য। তাঁর সুন্দর নাম ও গুণাবলি আছে, কোনো কিছুই তাঁর মতো নয়। ইবাদত কেবল তাঁরই জন্য। (সূরা ইখলাস ১১২:১–৪; সূরা শূরা ৪২:১১)", "en": "Allah is One, without partner; He alone creates, sustains and deserves worship. He has beautiful names and attributes, and nothing is like Him. Worship is for Him alone. (Al-Ikhlas 112:1–4; Ash-Shura 42:11)"}}, {"type": "step", "title": {"bn": "ফেরেশতাদের প্রতি ঈমান", "en": "Belief in the angels"}, "text": {"bn": "ফেরেশতারা নূরের তৈরি আল্লাহর সম্মানিত সৃষ্টি; তারা আল্লাহর অবাধ্য হয় না, যা আদেশ করা হয় তা-ই করে (সূরা তাহরিম ৬৬:৬)। যেমন জিবরিল (আ.) ওহি নিয়ে আসেন (সূরা বাকারা ২:৯৭), আর দুই ফেরেশতা আমাদের কথা ও কাজ লিখে রাখেন (সূরা কাফ ৫০:১৭–১৮)।", "en": "Angels are honoured creations of Allah; they never disobey Him and do as they are commanded (At-Tahrim 66:6). Jibril brings revelation (Al-Baqarah 2:97), and two angels record our words and deeds (Qaf 50:17–18)."}}, {"type": "step", "title": {"bn": "কিতাবসমূহের প্রতি ঈমান", "en": "Belief in the books"}, "text": {"bn": "আল্লাহ নবীদের ওপর কিতাব নাজিল করেছেন: মুসা (আ.)-এর ওপর তাওরাত, দাউদ (আ.)-এর ওপর যাবুর (সূরা নিসা ৪:১৬৩), ঈসা (আ.)-এর ওপর ইনজিল (সূরা মায়িদা ৫:৪৬), আর মুহাম্মাদ (সা.)-এর ওপর কুরআন। ইবরাহিম ও মুসা (আ.)-কে সহিফাও দেওয়া হয়েছিল (সূরা আ''লা ৮৭:১৮–১৯)। কুরআন সর্বশেষ কিতাব, আল্লাহ নিজেই এর হেফাজতকারী (সূরা হিজর ১৫:৯)।", "en": "Allah revealed books to prophets: the Torah to Musa, the Zabur to Dawud (An-Nisa 4:163), the Injil to ''Isa (Al-Ma''idah 5:46), and the Quran to Muhammad. Ibrahim and Musa were also given scriptures (Al-A''la 87:18–19). The Quran is the final book, preserved by Allah (Al-Hijr 15:9)."}}, {"type": "step", "title": {"bn": "রাসুলদের প্রতি ঈমান", "en": "Belief in the messengers"}, "text": {"bn": "আল্লাহ প্রত্যেক জাতির কাছে রাসুল পাঠিয়েছেন, যারা এক আল্লাহর ইবাদতের দিকে ডেকেছেন (সূরা নাহল ১৬:৩৬)। কারও কথা আমাদের জানানো হয়েছে, কারও কথা জানানো হয়নি (সূরা নিসা ৪:১৬৪)। আমরা সবার প্রতি ঈমান রাখি, কারও মধ্যে পার্থক্য করি না (সূরা বাকারা ২:২৮৫)। মুহাম্মাদ (সা.) সর্বশেষ নবী, তাঁর পরে আর কোনো নবী নেই (সূরা আহযাব ৩৩:৪০)।", "en": "Allah sent a messenger to every nation calling to worship Him alone (An-Nahl 16:36). Some are told to us, some not (An-Nisa 4:164). We believe in all of them without distinction (Al-Baqarah 2:285). Muhammad is the last prophet; there is none after him (Al-Ahzab 33:40)."}}, {"type": "step", "title": {"bn": "আখেরাতের প্রতি ঈমান", "en": "Belief in the Last Day"}, "text": {"bn": "মৃত্যুর পর কবরের জীবন, কিয়ামত, পুনরুত্থান, হিসাব, মিজান (পাল্লা), জান্নাত ও জাহান্নাম সত্য। প্রত্যেকে তার অণু পরিমাণ ভালো ও মন্দ কাজও দেখতে পাবে (সূরা যিলযাল ৯৯:৭–৮)। প্রত্যেক প্রাণ মৃত্যুর স্বাদ গ্রহণ করবে, আর কিয়ামতের দিন পূর্ণ প্রতিদান দেওয়া হবে (সূরা আলে ইমরান ৩:১৮৫)।", "en": "Life in the grave, the Hour, resurrection, reckoning, the scale, Paradise and Hell are true. Everyone will see even an atom''s weight of good or evil (Az-Zalzalah 99:7–8). Every soul will taste death and be paid in full on the Day of Resurrection (Al ''Imran 3:185)."}}, {"type": "step", "title": {"bn": "তাকদিরের প্রতি ঈমান", "en": "Belief in the decree (qadr)"}, "text": {"bn": "যা কিছু ঘটে, সবই আল্লাহর জ্ঞান, লিখন, ইচ্ছা ও সৃষ্টির অধীন: ‘আমি সবকিছু সৃষ্টি করেছি নির্ধারিত পরিমাপে’ (সূরা কামার ৫৪:৪৯)। আসমান-জমিন সৃষ্টির পঞ্চাশ হাজার বছর আগে আল্লাহ সৃষ্টির তাকদির লিখে রেখেছেন (সহিহ মুসলিম ২৬৫৩)। তাকদিরে বিশ্বাস চেষ্টা ছেড়ে দেওয়া নয়; মানুষ নিজের পছন্দে কাজ করে এবং সে অনুযায়ী প্রতিদান পায় (সূরা লাইল ৯২:৫–১০)।", "en": "Everything happens within Allah''s knowledge, writing, will and creation: ''We created everything according to a measure'' (Al-Qamar 54:49). Allah wrote the decrees fifty thousand years before creating the heavens and earth (Sahih Muslim 2653). Belief in qadr does not mean giving up effort; people act by choice and are rewarded accordingly (Al-Layl 92:5–10)."}}, {"type": "ref", "text": {"bn": "ছয়টি রুকন একসাথে কুরআনে: সূরা বাকারা ২:১৭৭, ২:২৮৫; সূরা নিসা ৪:১৩৬; তাকদির: সূরা কামার ৫৪:৪৯", "en": "The articles together in the Quran: Al-Baqarah 2:177, 2:285; An-Nisa 4:136; decree: Al-Qamar 54:49"}}]', 'in_review', 30 FROM is_guide_topics WHERE slug = 'kalima' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '60db2333-53a8-543c-9939-ee25e3356e02', id, 'five-pillars-of-islam', '{"bn": "ইসলামের পাঁচটি স্তম্ভ", "en": "The Five Pillars of Islam"}', '{"bn": "যে পাঁচটি ভিত্তির ওপর ইসলাম দাঁড়িয়ে আছে: শাহাদাত, নামাজ, যাকাত, রোজা ও হজ; সাথে ইসলাম, ঈমান ও ইহসানের সম্পর্ক।", "en": "The five foundations of Islam: shahadah, prayer, zakat, fasting and Hajj, and how Islam, iman and ihsan relate."}', 'basic', '[{"type": "arabic", "label": {"bn": "ইসলামের পাঁচ ভিত্তি", "en": "The five foundations"}, "ar": "بُنِيَ الْإِسْلَامُ عَلَىٰ خَمْسٍ: شَهَادَةِ أَنْ لَا إِلٰهَ إِلَّا اللّٰهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللّٰهِ، وَإِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَالْحَجِّ، وَصَوْمِ رَمَضَانَ", "pron": {"bn": "বুনিয়াল ইসলামু আলা খামস: শাহাদাতি আল লা ইলাহা ইল্লাল্লাহু ওয়া আন্না মুহাম্মাদার রাসূলুল্লাহ, ওয়া ইকামিস সালাহ, ওয়া ঈতায়িয যাকাহ, ওয়াল হাজ্জ, ওয়া সাওমি রামাদান।", "en": "Buniyal-Islamu ''ala khams: shahadati al la ilaha illallahu wa anna Muhammadar Rasulullah, wa iqamis-salah, wa ita''iz-zakah, wal-hajj, wa sawmi Ramadan."}, "meaning": {"bn": "ইসলাম পাঁচটি ভিত্তির ওপর প্রতিষ্ঠিত: এই সাক্ষ্য দেওয়া যে আল্লাহ ছাড়া কোনো ইলাহ নেই এবং মুহাম্মাদ (সা.) আল্লাহর রাসুল; নামাজ কায়েম করা; যাকাত দেওয়া; হজ করা; এবং রমজানের রোজা রাখা।", "en": "Islam is built on five: testifying that there is no god but Allah and that Muhammad is the Messenger of Allah, establishing prayer, giving zakat, Hajj, and fasting Ramadan."}, "ref": {"bn": "সহিহ বুখারি ৮; সহিহ মুসলিম ১৬", "en": "Sahih al-Bukhari 8; Sahih Muslim 16"}}, {"type": "step", "title": {"bn": "শাহাদাত (কালিমার সাক্ষ্য)", "en": "Shahadah (testimony of faith)"}, "text": {"bn": "অন্তরে বিশ্বাস করে মুখে সাক্ষ্য দেওয়া যে আল্লাহ ছাড়া কোনো সত্য ইলাহ নেই এবং মুহাম্মাদ (সা.) আল্লাহর রাসুল; আর সেই অনুযায়ী জীবন চালানো। এটিই ইসলামের প্রবেশদ্বার (সূরা মুহাম্মাদ ৪৭:১৯)।", "en": "To believe in the heart and declare that there is no true god but Allah and that Muhammad is His Messenger, and to live by it. It is the door of Islam (Muhammad 47:19)."}}, {"type": "step", "title": {"bn": "নামাজ", "en": "Salah (prayer)"}, "text": {"bn": "প্রতিদিন পাঁচ ওয়াক্ত ফরজ নামাজ নির্দিষ্ট সময়ে আদায় করা (সূরা নিসা ৪:১০৩)। ঈমানের পর সবচেয়ে গুরুত্বপূর্ণ আমল; প্রাপ্তবয়স্ক ও সুস্থ মস্তিষ্কের প্রত্যেক মুসলিমের ওপর ফরজ।", "en": "Five obligatory prayers each day at their fixed times (An-Nisa 4:103). The most important deed after faith, obligatory on every adult sane Muslim."}}, {"type": "step", "title": {"bn": "যাকাত", "en": "Zakat"}, "text": {"bn": "নিসাব পরিমাণ সম্পদ এক বছর থাকলে নির্দিষ্ট অংশ (সাধারণত আড়াই শতাংশ) নির্ধারিত হকদারদের দেওয়া (সূরা বাকারা ২:৪৩; হকদারদের তালিকা: সূরা তাওবা ৯:৬০)। এটি সম্পদকে পবিত্র করে।", "en": "Giving a set share (usually 2.5%) of wealth above the nisab held for a year to the eligible recipients (Al-Baqarah 2:43; recipients: At-Tawbah 9:60). It purifies wealth."}}, {"type": "step", "title": {"bn": "রোজা", "en": "Sawm (fasting)"}, "text": {"bn": "রমজান মাসে সুবহে সাদিক থেকে সূর্যাস্ত পর্যন্ত পানাহার ও স্ত্রী-সহবাস থেকে বিরত থাকা, তাকওয়া অর্জনের জন্য (সূরা বাকারা ২:১৮৩)।", "en": "Abstaining from food, drink and marital relations from dawn to sunset during Ramadan, to attain taqwa (Al-Baqarah 2:183)."}}, {"type": "step", "title": {"bn": "হজ", "en": "Hajj"}, "text": {"bn": "শারীরিক ও আর্থিকভাবে সামর্থ্যবান মুসলিমের ওপর জীবনে একবার কাবা ঘরের হজ করা ফরজ (সূরা আলে ইমরান ৩:৯৭)।", "en": "Pilgrimage to the Ka''bah once in a lifetime for every Muslim who is physically and financially able (Al ''Imran 3:97)."}}, {"type": "heading", "text": {"bn": "ইসলাম, ঈমান ও ইহসান", "en": "Islam, iman and ihsan"}}, {"type": "text", "text": {"bn": "হাদিসে জিবরিলে দ্বীনের তিনটি স্তর বলা হয়েছে: ইসলাম (বাহ্যিক আমল, যেমন এই পাঁচ স্তম্ভ), ঈমান (অন্তরের বিশ্বাস, ছয় রুকন), এবং ইহসান (সর্বোচ্চ স্তর)।", "en": "The Hadith of Jibril describes three levels of the religion: Islam (outward deeds, such as these five pillars), iman (belief in the heart, the six articles), and ihsan (the highest level)."}}, {"type": "arabic", "label": {"bn": "ইসলামের সংজ্ঞা", "en": "Definition of Islam"}, "ar": "الْإِسْلَامُ أَنْ تَشْهَدَ أَنْ لَا إِلٰهَ إِلَّا اللّٰهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللّٰهِ، وَتُقِيمَ الصَّلَاةَ، وَتُؤْتِيَ الزَّكَاةَ، وَتَصُومَ رَمَضَانَ، وَتَحُجَّ الْبَيْتَ إِنِ اسْتَطَعْتَ إِلَيْهِ سَبِيلًا", "pron": {"bn": "আল ইসলামু আন তাশহাদা আল লা ইলাহা ইল্লাল্লাহু ওয়া আন্না মুহাম্মাদার রাসূলুল্লাহ, ওয়া তুকীমাস সালাতা, ওয়া তু''তিয়ায যাকাতা, ওয়া তাসূমা রামাদানা, ওয়া তাহুজ্জাল বাইতা ইনিসতাতা''তা ইলাইহি সাবীলা।", "en": "Al-Islamu an tashhada al la ilaha illallahu wa anna Muhammadar Rasulullah, wa tuqimas-salata, wa tu''tiyaz-zakata, wa tasuma Ramadana, wa tahujjal-bayta inistata''ta ilayhi sabila."}, "meaning": {"bn": "ইসলাম হলো: তুমি সাক্ষ্য দেবে যে আল্লাহ ছাড়া কোনো ইলাহ নেই ও মুহাম্মাদ (সা.) আল্লাহর রাসুল, নামাজ কায়েম করবে, যাকাত দেবে, রমজানের রোজা রাখবে, এবং সামর্থ্য থাকলে কাবা ঘরের হজ করবে।", "en": "Islam is that you testify there is no god but Allah and Muhammad is the Messenger of Allah, establish prayer, give zakat, fast Ramadan, and make Hajj to the House if you are able."}, "ref": {"bn": "সহিহ মুসলিম ৮", "en": "Sahih Muslim 8"}}, {"type": "arabic", "label": {"bn": "ইহসানের সংজ্ঞা", "en": "Definition of ihsan"}, "ar": "أَنْ تَعْبُدَ اللّٰهَ كَأَنَّكَ تَرَاهُ، فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ", "pron": {"bn": "আন তা''বুদাল্লাহা কাআন্নাকা তারাহ, ফাইল লাম তাকুন তারাহু ফাইন্নাহূ ইয়ারাক।", "en": "An ta''budallaha ka-annaka tarah, fa il lam takun tarahu fa innahu yarak."}, "meaning": {"bn": "(ইহসান হলো) তুমি আল্লাহর ইবাদত এমনভাবে করবে যেন তুমি তাঁকে দেখছ; আর যদি তুমি তাঁকে না দেখো, তবে (জেনে রাখো) তিনি তোমাকে দেখছেন।", "en": "(Ihsan is) that you worship Allah as though you see Him; and if you do not see Him, He surely sees you."}, "ref": {"bn": "সহিহ মুসলিম ৮; সহিহ বুখারি ৫০", "en": "Sahih Muslim 8; Sahih al-Bukhari 50"}}, {"type": "note", "tone": "tip", "text": {"bn": "পাঁচ স্তম্ভের প্রতিটির বিস্তারিত নিয়ম এই অ্যাপের নামাজ, রোজা, যাকাত ও হজ অংশে দেখুন।", "en": "See the prayer, fasting, zakat and Hajj sections of this app for the details of each pillar."}}]', 'in_review', 40 FROM is_guide_topics WHERE slug = 'kalima' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '4c0a3cd4-525f-5439-8dc3-3889a0c19c76', id, 'sawm-basics', '{"bn": "রোজা: কার ওপর ফরজ ও কেন", "en": "Fasting: who must fast and why"}', '{"bn": "রমজানের রোজা ইসলামের পাঁচ স্তম্ভের একটি। কার ওপর রোজা ফরজ, রোজার ফজিলত ও আদব এখানে সংক্ষেপে।", "en": "Fasting Ramadan is one of the five pillars of Islam. Who must fast, its virtues and its manners in brief."}', 'basic', '[{"type": "arabic", "label": {"bn": "রোজা ফরজ হওয়ার আয়াত", "en": "The verse of fasting"}, "ar": "يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ", "pron": {"bn": "ইয়া আইয়ুহাল্লাযীনা আমানূ কুতিবা আলাইকুমুস সিয়ামু কামা কুতিবা আলাল্লাযীনা মিন কাবলিকুম লাআল্লাকুম তাত্তাকূন", "en": "Ya ayyuhal-ladhina amanu kutiba ''alaykumus-siyamu kama kutiba ''alal-ladhina min qablikum la''allakum tattaqun"}, "meaning": {"bn": "হে ঈমানদারগণ! তোমাদের ওপর রোজা ফরজ করা হয়েছে, যেমন ফরজ করা হয়েছিল তোমাদের পূর্ববর্তীদের ওপর, যাতে তোমরা তাকওয়া অর্জন করতে পারো।", "en": "O you who believe, fasting is prescribed for you as it was prescribed for those before you, so that you may become mindful of Allah."}, "ref": {"bn": "সূরা বাকারা ২:১৮৩", "en": "Al-Baqarah 2:183"}}, {"type": "text", "text": {"bn": "রোজা মানে সুবহে সাদিক (ফজরের সময় শুরু) থেকে সূর্যাস্ত পর্যন্ত আল্লাহর সন্তুষ্টির নিয়তে খাওয়া, পান করা ও স্ত্রী-সহবাস থেকে বিরত থাকা। রমজান মাসের রোজা প্রত্যেক প্রাপ্তবয়স্ক মুসলিমের ওপর ফরজ।", "en": "Fasting (sawm) means refraining from food, drink and marital relations from true dawn (start of Fajr) until sunset, with the intention of pleasing Allah. Fasting the month of Ramadan is obligatory on every adult Muslim."}}, {"type": "heading", "text": {"bn": "কার ওপর রোজা ফরজ", "en": "Who must fast"}}, {"type": "list", "items": [{"bn": "মুসলিম", "en": "A Muslim"}, {"bn": "বালেগ বা প্রাপ্তবয়স্ক (ছেলে-মেয়ের বয়ঃসন্ধির লক্ষণ দেখা দিলে, নয়তো চাঁদের হিসাবে ১৫ বছর হলে)", "en": "Adult (has reached puberty, or otherwise 15 lunar years of age)"}, {"bn": "সুস্থ মস্তিষ্কের অধিকারী", "en": "Of sound mind"}, {"bn": "রোজা রাখতে সক্ষম; গুরুতর অসুস্থ নয়", "en": "Able to fast, not seriously ill"}, {"bn": "মুকিম, অর্থাৎ শরিয়তসম্মত সফরে নেই", "en": "Resident, i.e. not on a journey by the Shariah definition"}, {"bn": "নারীর ক্ষেত্রে: হায়েজ (মাসিক) ও নিফাস (প্রসব-পরবর্তী রক্তস্রাব) থেকে পবিত্র", "en": "For women: free of menstruation (hayd) and post-natal bleeding (nifas)"}]}, {"type": "note", "tone": "info", "text": {"bn": "অসুস্থ, মুসাফির, গর্ভবতী-দুগ্ধদানকারী মা ও বৃদ্ধদের বিধান আলাদা গাইডে দেওয়া আছে। তাদের অনেকের জন্য পরে কাজা বা ফিদইয়া আছে, রোজা পুরোপুরি মাফ নয়।", "en": "The rulings for the sick, travellers, pregnant and nursing mothers and the elderly are in a separate guide. For most of them the fast is made up later or compensated with fidya; it is not simply cancelled."}}, {"type": "text", "text": {"bn": "ছোট শিশুদের ওপর রোজা ফরজ নয়, তবে সাহাবিরা অভ্যাস করানোর জন্য শিশুদের রোজা রাখাতেন এবং ক্ষুধায় কাঁদলে খেলনা দিয়ে ভুলিয়ে রাখতেন।", "en": "Fasting is not obligatory on young children, but the Companions trained their children to fast and gave them toys to distract them when they cried from hunger."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৯৬০", "en": "Sahih al-Bukhari 1960"}}, {"type": "heading", "text": {"bn": "রোজার কিছু ফজিলত", "en": "Some virtues of fasting"}}, {"type": "list", "items": [{"bn": "যে ব্যক্তি ঈমানের সাথে ও সওয়াবের আশায় রমজানের রোজা রাখে, তার আগের গুনাহ ক্ষমা করা হয়।", "en": "Whoever fasts Ramadan with faith and hoping for reward, his past sins are forgiven."}, {"bn": "রোজা ঢালস্বরূপ, গুনাহ ও জাহান্নাম থেকে রক্ষা করে।", "en": "Fasting is a shield, protecting from sin and the Fire."}, {"bn": "জান্নাতে ''রাইয়ান'' নামে একটি দরজা আছে, শুধু রোজাদাররা সেখান দিয়ে প্রবেশ করবে।", "en": "Paradise has a gate called Ar-Rayyan through which only those who fast will enter."}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৩৮; সহিহ বুখারি ১৮৯৪; সহিহ বুখারি ১৮৯৬", "en": "Sahih al-Bukhari 38; Sahih al-Bukhari 1894; Sahih al-Bukhari 1896"}}, {"type": "heading", "text": {"bn": "রোজার আদব", "en": "Manners of the fast"}}, {"type": "text", "text": {"bn": "রোজা শুধু না খেয়ে থাকা নয়। মিথ্যা কথা, গালিগালাজ, গিবত ও ঝগড়া থেকেও বাঁচতে হবে। নবী (সা.) বলেছেন, যে মিথ্যা কথা ও মিথ্যা অনুযায়ী কাজ ছাড়ে না, তার খাবার-পানীয় ত্যাগ করায় আল্লাহর কোনো প্রয়োজন নেই। কেউ ঝগড়া করতে এলে বলবে: ''আমি রোজাদার।''", "en": "Fasting is not only going without food. One must also avoid lies, abuse, backbiting and quarrels. The Prophet (peace be upon him) said that whoever does not give up false speech and acting on it, Allah has no need of his leaving food and drink. If someone picks a fight, say: ''I am fasting.''"}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৯০৩; সহিহ বুখারি ১৯০৪", "en": "Sahih al-Bukhari 1903; Sahih al-Bukhari 1904"}}]', 'in_review', 10 FROM is_guide_topics WHERE slug = 'sawm' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '82d71d49-a2c2-5659-9854-50a38bf180d5', id, 'sawm-niyyah-sehri-iftar', '{"bn": "নিয়ত, সেহরি ও ইফতার", "en": "Niyyah, sehri and iftar"}', '{"bn": "রোজার নিয়ত কীভাবে করবেন, সেহরি ও ইফতারের সুন্নত এবং ইফতারের সহিহ দোয়া।", "en": "How to make the intention, the sunnahs of sehri and iftar, and the authentic iftar dua."}', 'basic', '[{"type": "heading", "text": {"bn": "নিয়ত", "en": "Niyyah (intention)"}}, {"type": "text", "text": {"bn": "নিয়ত মানে মনের ইচ্ছা। আপনি যে আগামীকাল রোজা রাখবেন বলে মনে মনে ঠিক করেছেন, সেটাই নিয়ত। সেহরি খেতে ওঠাও নিয়তের প্রমাণ। মুখে উচ্চারণ করা জরুরি নয়, আর নির্দিষ্ট কোনো আরবি বাক্য বলাও শর্ত নয়।", "en": "Niyyah is the intention in the heart. Having decided in your heart that you will fast tomorrow is the intention; getting up for sehri itself shows it. Saying it aloud is not required, and no particular Arabic wording is a condition."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১; সহিহ মুসলিম ১৯০৭", "en": "Sahih al-Bukhari 1; Sahih Muslim 1907"}}, {"type": "note", "tone": "tip", "text": {"bn": "উদাহরণ (মুখে বলা জরুরি নয়): ''আমি আগামীকাল আল্লাহর সন্তুষ্টির জন্য রমজানের ফরজ রোজা রাখার নিয়ত করছি।'' এটি শুধু একটি প্রচলিত বাংলা উদাহরণ; মনে এই ইচ্ছা থাকলেই যথেষ্ট।", "en": "Example (saying it is not required): ''I intend to keep tomorrow''s obligatory Ramadan fast for the sake of Allah.'' This is only a common example phrasing; having this intention in the heart is enough."}}, {"type": "differ", "title": {"bn": "নিয়ত কখন করতে হবে", "en": "When must the intention be made"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "রমজানের রোজা, নির্দিষ্ট দিনের মানতের রোজা ও নফল রোজার নিয়ত রাত থেকে শুরু করে পরদিন দুপুরের আগে (শরয়ি অর্ধদিবসের আগে) পর্যন্ত করা যায়, যদি এর মধ্যে কিছু খাওয়া না হয়। তবে রাতেই নিয়ত করা উত্তম। কাজা, কাফফারা ও অনির্দিষ্ট মানতের রোজার নিয়ত রাতেই করতে হয়।", "en": "For Ramadan, a vow for a fixed day and voluntary fasts, the intention may be made from the night until before midday (the Shariah half-day) if nothing has been eaten; making it at night is better. Make-up, kaffarah and unfixed vow fasts need the intention at night."}, "evidence": {"bn": "নবী (সা.) দিনের বেলায় ঘরে খাবার না পেয়ে বলেছেন, ''তাহলে আমি রোজা রাখলাম'' (নফল); আশুরার দিনে দিনের বেলায় রোজা রাখার ঘোষণা দেওয়া হয়েছিল।", "en": "The Prophet, finding no food at home during the day, said ''Then I am fasting'' (voluntary); and on Ashura it was announced during the day that people should fast."}}, {"label": {"bn": "শাফেয়ি, মালেকি, হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "ফরজ রোজার (রমজান, কাজা, মানত) নিয়ত ফজরের আগে রাতেই করতে হবে। নফল রোজার নিয়ত দিনের বেলায়ও করা যায় (মালেকিদের মতে নফলেও রাতে)।", "en": "For obligatory fasts (Ramadan, make-up, vows) the intention must be made at night before Fajr. For voluntary fasts it may be made during the day (Malikis require night for these too)."}, "evidence": {"bn": "হাদিস: ''যে ফজরের আগে রোজার নিয়ত করে না, তার রোজা হয় না।'' (হাফসা রা. থেকে বর্ণিত)", "en": "Hadith: ''Whoever does not resolve to fast before Fajr has no fast.'' (narrated from Hafsah)"}}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১১৫৪; সুনান আবু দাউদ ২৪৫৪", "en": "Sahih Muslim 1154; Sunan Abi Dawud 2454"}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি (আশুরার দিনে দিনের বেলায় রোজার ঘোষণা)", "en": "Sahih al-Bukhari (the daytime announcement to fast on Ashura)"}, "check": true}, {"type": "heading", "text": {"bn": "সেহরি", "en": "Sehri (pre-dawn meal)"}}, {"type": "list", "items": [{"bn": "সেহরি খাওয়া সুন্নত; এতে বরকত আছে। অল্প কিছু, এমনকি এক ঢোক পানি হলেও খাবেন।", "en": "Eating sehri is sunnah and has blessing; eat something, even a sip of water."}, {"bn": "সেহরি দেরিতে, অর্থাৎ ফজরের সময় শুরু হওয়ার কিছু আগে খাওয়া সুন্নত। নবী (সা.)-এর সেহরি ও ফজরের নামাজের মাঝে প্রায় পঞ্চাশ আয়াত পড়ার সময় থাকত।", "en": "Delaying sehri to shortly before Fajr is sunnah; between the Prophet''s sehri and the Fajr prayer was about the time of reciting fifty verses."}, {"bn": "ফজরের সময় শুরু হয়ে গেলে খাওয়া বন্ধ করতে হবে। আজান শুনে খাওয়া চালিয়ে না গিয়ে স্থানীয় নির্ভরযোগ্য সময়সূচি দেখে কয়েক মিনিট আগেই থামা নিরাপদ।", "en": "Stop eating once Fajr time begins. Rather than eating on through the adhan, it is safer to stop a few minutes early by a reliable local timetable."}, {"bn": "সেহরিই আমাদের রোজা ও আহলে কিতাবের রোজার পার্থক্য।", "en": "Sehri is the difference between our fasting and that of the People of the Book."}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৯২৩; সহিহ বুখারি ১৯২১; সহিহ মুসলিম ১০৯৬", "en": "Sahih al-Bukhari 1923; Sahih al-Bukhari 1921; Sahih Muslim 1096"}}, {"type": "arabic", "ar": "وَكُلُوا وَاشْرَبُوا حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الْأَبْيَضُ مِنَ الْخَيْطِ الْأَسْوَدِ مِنَ الْفَجْرِ", "pron": {"bn": "ওয়া কুলূ ওয়াশরাবূ হাত্তা ইয়াতাবাইয়ানা লাকুমুল খাইতুল আবইয়াদু মিনাল খাইতিল আসওয়াদি মিনাল ফাজর", "en": "Wa kulu washrabu hatta yatabayyana lakumul-khaytul-abyadu minal-khaytil-aswadi minal-fajr"}, "meaning": {"bn": "আর খাও ও পান করো, যতক্ষণ না রাতের কালো রেখা থেকে ভোরের সাদা রেখা স্পষ্ট হয়।", "en": "And eat and drink until the white thread of dawn becomes distinct to you from the black thread."}, "ref": {"bn": "সূরা বাকারা ২:১৮৭", "en": "Al-Baqarah 2:187"}}, {"type": "heading", "text": {"bn": "ইফতার", "en": "Iftar (breaking the fast)"}}, {"type": "list", "items": [{"bn": "সূর্য ডোবার সঙ্গে সঙ্গে দেরি না করে ইফতার করা সুন্নত। মানুষ যতদিন তাড়াতাড়ি ইফতার করবে, ততদিন কল্যাণে থাকবে।", "en": "Breaking the fast promptly at sunset is sunnah; people will remain in good as long as they hasten the iftar."}, {"bn": "তাজা খেজুর দিয়ে ইফতার করা সুন্নত; না পেলে শুকনো খেজুর, তাও না পেলে কয়েক ঢোক পানি।", "en": "Break the fast with fresh dates, if not then dried dates, and if not then a few sips of water."}, {"bn": "ইফতারের সময় দোয়া করুন; রোজাদারকে ইফতার করানোরও বড় সওয়াব আছে।", "en": "Make dua at iftar; feeding a fasting person also carries great reward."}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৯৫৭; সহিহ মুসলিম ১০৯৮; সুনান আবু দাউদ ২৩৫৬", "en": "Sahih al-Bukhari 1957; Sahih Muslim 1098; Sunan Abi Dawud 2356"}}, {"type": "arabic", "label": {"bn": "ইফতারের দোয়া (সহিহ সনদে বর্ণিত)", "en": "Iftar dua (authentic)"}, "ar": "ذَهَبَ الظَّمَأُ، وَابْتَلَّتِ الْعُرُوقُ، وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ", "pron": {"bn": "যাহাবায যামাউ, ওয়াবতাল্লাতিল উরূকু, ওয়া সাবাতাল আজরু ইনশাআল্লাহ", "en": "Dhahabaz-zama''u, wabtallatil-''uruqu, wa thabatal-ajru in sha Allah"}, "meaning": {"bn": "পিপাসা দূর হয়েছে, শিরাগুলো সিক্ত হয়েছে, আর আল্লাহ চাইলে প্রতিদান নিশ্চিত হয়েছে।", "en": "The thirst is gone, the veins are moistened, and the reward is certain, if Allah wills."}, "ref": {"bn": "সুনান আবু দাউদ ২৩৫৭", "en": "Sunan Abi Dawud 2357"}}, {"type": "note", "tone": "info", "text": {"bn": "এই দোয়াটি নবী (সা.) ইফতার করার পরে পড়তেন, তাই প্রথমে ''বিসমিল্লাহ'' বলে ইফতার শুরু করুন, তারপর এটি পড়ুন। হাদিসবিশারদদের অনেকে এর সনদকে হাসান (গ্রহণযোগ্য) বলেছেন।", "en": "The Prophet said this after breaking the fast, so start eating with ''Bismillah'' and then say it. Many hadith scholars graded its chain hasan (acceptable)."}}, {"type": "arabic", "label": {"bn": "প্রচলিত দোয়া (সনদ দুর্বল)", "en": "Common dua (weak chain)"}, "ar": "اللَّهُمَّ لَكَ صُمْتُ، وَعَلَى رِزْقِكَ أَفْطَرْتُ", "pron": {"bn": "আল্লাহুম্মা লাকা সুমতু, ওয়া আলা রিযক্বিকা আফতারতু", "en": "Allahumma laka sumtu, wa ''ala rizqika aftartu"}, "meaning": {"bn": "হে আল্লাহ! তোমার জন্যই রোজা রেখেছি এবং তোমার দেওয়া রিজিক দিয়েই ইফতার করছি।", "en": "O Allah, for You I fasted and with Your provision I break my fast."}, "ref": {"bn": "সুনান আবু দাউদ ২৩৫৮", "en": "Sunan Abi Dawud 2358"}}, {"type": "note", "tone": "warn", "text": {"bn": "এই দোয়াটি মুরসাল সূত্রে বর্ণিত, তাই সনদ দুর্বল; অর্থ সুন্দর বলে পড়া যায়, তবে সহিহ দোয়া হিসেবে প্রথমটিই অগ্রাধিকার পাবে। বাংলাদেশে প্রচলিত ''ওয়া বিকা আমানতু ওয়া আলাইকা তাওয়াক্কালতু'' অংশটুকু কোনো হাদিসে পাওয়া যায় না।", "en": "This dua comes through a mursal chain and is weak; its meaning is fine, but the first dua is the authentic one to prefer. The addition ''wa bika amantu wa ''alayka tawakkaltu'' common in Bangladesh is not found in any hadith."}}]', 'in_review', 20 FROM is_guide_topics WHERE slug = 'sawm' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '6b8fe835-3994-5468-b106-194fcad2cd49', id, 'sawm-what-breaks', '{"bn": "যেসব কারণে রোজা ভাঙে, যেসবে ভাঙে না", "en": "What breaks the fast and what does not"}', '{"bn": "কোন কাজে রোজা ভেঙে যায় আর কোনটায় ভাঙে না, একনজরে টেবিলে। যেসব বিষয়ে আলেমদের মতভেদ আছে, তা আলাদা দেখানো হয়েছে।", "en": "At a glance: what breaks the fast and what does not, with the points scholars differ on shown separately."}', 'basic', '[{"type": "text", "text": {"bn": "মূলনীতি: ইচ্ছাকৃতভাবে খাওয়া, পান করা, স্ত্রী-সহবাস, আর এ জাতীয় কিছু দিয়ে রোজা ভাঙে। ভুলে গিয়ে খেলে বা অনিচ্ছায় কিছু হলে রোজা ভাঙে না।", "en": "The principle: the fast is broken by deliberate eating, drinking, marital relations and things of that kind. Eating by mistake or anything that happens unintentionally does not break it."}}, {"type": "heading", "text": {"bn": "যেসব কারণে রোজা ভেঙে যায়", "en": "What breaks the fast"}}, {"type": "table", "head": [{"bn": "কাজ", "en": "Act"}, {"bn": "করণীয়", "en": "What is due"}], "rows": [[{"bn": "ইচ্ছাকৃতভাবে খাওয়া বা পান করা", "en": "Deliberately eating or drinking"}, {"bn": "কাজা; হানাফি ও মালেকি মতে কাফফারাও", "en": "Make-up; also kaffarah in the Hanafi and Maliki view"}], [{"bn": "রোজা অবস্থায় ইচ্ছাকৃত স্ত্রী-সহবাস", "en": "Deliberate intercourse while fasting"}, {"bn": "কাজা ও কাফফারা (সব মাজহাবে একমত)", "en": "Make-up and kaffarah (agreed)"}], [{"bn": "ইচ্ছা করে বমি করা (হানাফি মতে মুখভর্তি হলে)", "en": "Deliberately making oneself vomit (Hanafi: a mouthful)"}, {"bn": "কাজা", "en": "Make-up"}], [{"bn": "হায়েজ বা নিফাস শুরু হওয়া, দিনের যেকোনো সময়ে", "en": "Menstruation or post-natal bleeding starting, at any time of the day"}, {"bn": "কাজা", "en": "Make-up"}], [{"bn": "ধূমপান বা ইচ্ছা করে ধোঁয়া টেনে নেওয়া", "en": "Smoking or deliberately inhaling smoke"}, {"bn": "কাজা", "en": "Make-up"}], [{"bn": "পুষ্টিকর ইনজেকশন বা স্যালাইন (খাবারের বিকল্প)", "en": "Nutritive injection or IV drip (a substitute for food)"}, {"bn": "কাজা (সমকালীন আলেমদের অধিকাংশের মত)", "en": "Make-up (view of most contemporary scholars)"}], [{"bn": "ইচ্ছাকৃত হস্তমৈথুন বা স্পর্শে বীর্যপাত", "en": "Deliberate ejaculation by masturbation or touching"}, {"bn": "কাজা", "en": "Make-up"}], [{"bn": "নাক বা কানে ওষুধ দিয়ে তা গলা পর্যন্ত পৌঁছানো", "en": "Nose or ear drops that reach the throat"}, {"bn": "কাজা", "en": "Make-up"}], [{"bn": "ফজর শুরু হয়ে গেছে বা সূর্য ডুবেছে ভেবে ভুল সময়ে খাওয়া", "en": "Eating at the wrong time thinking Fajr had not begun or the sun had set"}, {"bn": "কাজা (অধিকাংশ আলেমের মত)", "en": "Make-up (majority view)"}]]}, {"type": "ref", "text": {"bn": "জামে তিরমিজি ৭২০; সুনান আবু দাউদ ২৩৮০; সহিহ মুসলিম ৩৩৫", "en": "Jami'' at-Tirmidhi 720; Sunan Abi Dawud 2380; Sahih Muslim 335"}}, {"type": "heading", "text": {"bn": "যেসব কারণে রোজা ভাঙে না", "en": "What does not break the fast"}}, {"type": "table", "head": [{"bn": "কাজ", "en": "Act"}, {"bn": "হুকুম", "en": "Ruling"}], "rows": [[{"bn": "ভুলে গিয়ে খাওয়া বা পান করা", "en": "Eating or drinking forgetfully"}, {"bn": "ভাঙে না; মনে পড়লেই থামবেন", "en": "Does not break; stop as soon as you remember"}], [{"bn": "অনিচ্ছায় বমি হওয়া", "en": "Vomiting unintentionally"}, {"bn": "ভাঙে না", "en": "Does not break"}], [{"bn": "স্বপ্নদোষ, বা গোসল ফরজ অবস্থায় ফজর হয়ে যাওয়া", "en": "A wet dream, or being in a state of janabah at Fajr"}, {"bn": "ভাঙে না; গোসল করে নেবেন", "en": "Does not break; take the ghusl"}], [{"bn": "মিসওয়াক বা পেস্ট ছাড়া ব্রাশ করা", "en": "Miswak, or brushing without toothpaste"}, {"bn": "ভাঙে না; পেস্ট ব্যবহার মাকরুহ, গিলে ফেললে ভেঙে যাবে", "en": "Does not break; toothpaste is disliked and breaks the fast if swallowed"}], [{"bn": "গোসল করা, গায়ে পানি ঢালা", "en": "Bathing, pouring water over oneself"}, {"bn": "ভাঙে না, যদি পানি গলায় না যায়", "en": "Does not break if water does not go down the throat"}], [{"bn": "রক্ত পরীক্ষার জন্য রক্ত দেওয়া", "en": "Giving blood for a test"}, {"bn": "ভাঙে না", "en": "Does not break"}], [{"bn": "পুষ্টিহীন ইনজেকশন (যেমন ইনসুলিন, টিকা) মাংসে বা চামড়ায়", "en": "Non-nutritive injections (e.g. insulin, vaccines) into muscle or skin"}, {"bn": "ভাঙে না (অধিকাংশ সমকালীন আলেম)", "en": "Does not break (most contemporary scholars)"}], [{"bn": "নিজের থুথু গিলে ফেলা", "en": "Swallowing one''s own saliva"}, {"bn": "ভাঙে না", "en": "Does not break"}], [{"bn": "অনিচ্ছায় ধুলা, ধোঁয়া বা মাছি গলায় ঢুকে যাওয়া", "en": "Dust, smoke or a fly entering the throat unintentionally"}, {"bn": "ভাঙে না", "en": "Does not break"}], [{"bn": "সুগন্ধি লাগানো, তেল বা মলম মাখা", "en": "Applying perfume, oil or ointment"}, {"bn": "ভাঙে না", "en": "Does not break"}], [{"bn": "প্রয়োজনে রান্নার স্বাদ জিভে দেখে ফেলে দেওয়া", "en": "Tasting food on the tongue when needed and spitting it out"}, {"bn": "ভাঙে না; বিনা প্রয়োজনে মাকরুহ", "en": "Does not break; disliked without need"}]]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৯৩৩; সহিহ মুসলিম ১১৫৫", "en": "Sahih al-Bukhari 1933; Sahih Muslim 1155"}}, {"type": "note", "tone": "tip", "text": {"bn": "ভুলে খেয়ে ফেললে নবী (সা.) বলেছেন: সে যেন রোজা পূর্ণ করে, কেননা আল্লাহই তাকে খাইয়েছেন ও পান করিয়েছেন।", "en": "If you eat by mistake, the Prophet said: let him complete his fast, for it is Allah who fed him and gave him drink."}}, {"type": "heading", "text": {"bn": "যেসব বিষয়ে মতভেদ আছে", "en": "Points of difference"}}, {"type": "differ", "title": {"bn": "চোখে ড্রপ ও সুরমা", "en": "Eye drops and kohl"}, "views": [{"label": {"bn": "হানাফি ও শাফেয়ি", "en": "Hanafi and Shafi''i"}, "text": {"bn": "চোখে ড্রপ বা সুরমা দিলে রোজা ভাঙে না, গলায় স্বাদ পেলেও।", "en": "Eye drops or kohl do not break the fast, even if a taste is felt in the throat."}, "evidence": {"bn": "চোখ খাদ্য প্রবেশের স্বাভাবিক পথ নয়।", "en": "The eye is not a normal passage for food to enter."}}, {"label": {"bn": "মালেকি ও হাম্বলি", "en": "Maliki and Hanbali"}, "text": {"bn": "গলায় স্বাদ পৌঁছালে রোজা ভেঙে যায়; সতর্কতার জন্য দিনের বেলা না দিয়ে রাতে দেওয়া ভালো।", "en": "If the taste reaches the throat the fast is broken; to be careful, use them at night rather than in the day."}, "evidence": {"bn": "যা গলা পর্যন্ত পৌঁছায় তা ভেতরে প্রবেশ করেছে বলে গণ্য।", "en": "What reaches the throat is counted as having entered the body."}}]}, {"type": "differ", "title": {"bn": "হাঁপানির ইনহেলার", "en": "Asthma inhaler"}, "views": [{"label": {"bn": "রোজা ভাঙে (দেশের হানাফি ফতোয়া বোর্ডসহ অনেকের মত)", "en": "Breaks the fast (many, incl. Hanafi fatwa bodies in the subcontinent)"}, "text": {"bn": "ইনহেলারের ওষুধের কণা গলা হয়ে ভেতরে যায়, তাই রোজা ভেঙে যায়; প্রয়োজন হলে ব্যবহার করবেন এবং পরে কাজা করবেন।", "en": "The medicine particles of an inhaler pass down the throat, so the fast is broken; use it if needed and make the day up later."}, "evidence": {"bn": "ইচ্ছাকৃতভাবে কোনো বস্তু মুখ দিয়ে ভেতরে নেওয়ার বিধানের ওপর কিয়াস।", "en": "Analogy with deliberately taking any substance in through the mouth."}}, {"label": {"bn": "রোজা ভাঙে না (সৌদি স্থায়ী ফতোয়া কমিটিসহ অনেকের মত)", "en": "Does not break (many, incl. the Saudi Permanent Committee)"}, "text": {"bn": "ইনহেলারের ওষুধ খুব সামান্য ও মূলত ফুসফুসে যায়; এটি খাবার বা পানীয় নয়।", "en": "The amount is tiny and goes mainly to the lungs; it is neither food nor drink."}, "evidence": {"bn": "কুলি করার পর মুখে যে সামান্য আর্দ্রতা থাকে তার সঙ্গে তুলনা।", "en": "Compared to the slight moisture left in the mouth after rinsing it."}}]}, {"type": "differ", "title": {"bn": "শিঙ্গা লাগানো বা রক্তদান", "en": "Cupping or donating blood"}, "views": [{"label": {"bn": "হানাফি, মালেকি, শাফেয়ি", "en": "Hanafi, Maliki, Shafi''i"}, "text": {"bn": "রোজা ভাঙে না, তবে দুর্বল হয়ে পড়ার আশঙ্কা থাকলে মাকরুহ।", "en": "Does not break the fast, but is disliked if it may weaken the person."}, "evidence": {"bn": "নবী (সা.) রোজা অবস্থায় শিঙ্গা লাগিয়েছেন বলে সহিহ বুখারিতে বর্ণিত।", "en": "Sahih al-Bukhari reports that the Prophet was cupped while fasting."}}, {"label": {"bn": "হাম্বলি", "en": "Hanbali"}, "text": {"bn": "শিঙ্গা লাগালে বা লাগিয়ে দিলে রোজা ভেঙে যায়।", "en": "Cupping breaks the fast of both the one cupped and the one cupping."}, "evidence": {"bn": "হাদিস: ''শিঙ্গা লাগানো ও যাকে লাগানো হলো, দুজনেরই রোজা ভেঙে গেল।'' (আবু দাউদ ও অন্যান্য)", "en": "Hadith: ''The one who cups and the one cupped have broken their fast.'' (Abu Dawud and others)"}}], "check": true}, {"type": "note", "tone": "info", "text": {"bn": "চিকিৎসা-সংক্রান্ত নতুন প্রশ্নে (এন্ডোস্কপি, ডায়ালাইসিস ইত্যাদি) নির্ভরযোগ্য মুফতির কাছ থেকে জেনে নিন।", "en": "For new medical questions (endoscopy, dialysis and so on), ask a reliable mufti."}}]', 'in_review', 30 FROM is_guide_topics WHERE slug = 'sawm' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'c6c88280-80f5-5413-8b83-f0a127d5d424', id, 'sawm-qaza-kaffarah-fidya', '{"bn": "কাজা, কাফফারা ও ফিদইয়া", "en": "Qaza, kaffarah and fidya"}', '{"bn": "ভাঙা বা ছুটে যাওয়া রোজার কাজা, কাফফারা কখন লাগে, আর ফিদইয়া কার জন্য।", "en": "Making up missed fasts, when kaffarah is due, and who pays fidya."}', 'detail', '[{"type": "heading", "text": {"bn": "কাজা", "en": "Qaza (make-up)"}}, {"type": "text", "text": {"bn": "কাজা মানে ছুটে যাওয়া বা ভেঙে যাওয়া প্রতিটি রোজার বদলে পরে একটি করে রোজা রাখা। অসুস্থতা, সফর, হায়েজ-নিফাস বা অন্য কোনো কারণে রোজা ছুটে গেলে কাজা করতে হয়।", "en": "Qaza means keeping one fast later for each fast missed or broken. Fasts missed through illness, travel, menstruation, post-natal bleeding or other reasons must be made up."}}, {"type": "arabic", "ar": "فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ", "pron": {"bn": "ফামান কানা মিনকুম মারীদান আও আলা সাফারিন ফাইদ্দাতুম মিন আইয়ামিন উখার", "en": "Faman kana minkum maridan aw ''ala safarin fa''iddatum min ayyamin ukhar"}, "meaning": {"bn": "তোমাদের মধ্যে কেউ অসুস্থ হলে বা সফরে থাকলে অন্য দিনগুলোতে সেই সংখ্যা পূরণ করবে।", "en": "Whoever of you is ill or on a journey, then an equal number of other days."}, "ref": {"bn": "সূরা বাকারা ২:১৮৪", "en": "Al-Baqarah 2:184"}}, {"type": "list", "items": [{"bn": "পরবর্তী রমজানের আগেই কাজা করে নেওয়া উত্তম; একটানা রাখা জরুরি নয়।", "en": "It is best to make up before the next Ramadan; the days need not be consecutive."}, {"bn": "কোনো ওজর ছাড়া দেরি করা ঠিক নয়। শাফেয়ি ও হাম্বলি মতে বিনা ওজরে পরের রমজান পার হয়ে গেলে কাজার সাথে প্রতিদিনের জন্য ফিদইয়াও দিতে হয়; হানাফি মতে শুধু কাজা।", "en": "Do not delay without excuse. In the Shafi''i and Hanbali view, if the next Ramadan passes without excuse, a fidya per day is due with the make-up; in the Hanafi view only the make-up."}, {"bn": "নিয়ত রাতেই করবেন: ''আমি রমজানের একটি কাজা রোজা রাখছি'' এমন ইচ্ছা মনে রাখাই যথেষ্ট।", "en": "Make the intention at night; the intention in the heart that ''I am keeping a missed Ramadan fast'' is enough."}]}, {"type": "heading", "text": {"bn": "কাফফারা", "en": "Kaffarah (expiation)"}}, {"type": "text", "text": {"bn": "রমজানের রোজা অবস্থায় ইচ্ছাকৃতভাবে স্ত্রী-সহবাস করলে কাজার সাথে কাফফারাও দিতে হয়। এক ব্যক্তি এমন করে নবী (সা.)-এর কাছে এলে তিনি তাকে ক্রমানুসারে এই তিনটির কথা বলেন:", "en": "Deliberate intercourse while fasting in Ramadan requires kaffarah in addition to the make-up. When a man who had done this came to the Prophet, he told him these three, in order:"}}, {"type": "step", "title": {"bn": "দাস মুক্ত করা", "en": "Free a slave"}, "text": {"bn": "বর্তমানে এর সুযোগ নেই, তাই পরের ধাপ প্রযোজ্য।", "en": "This is not possible today, so the next option applies."}}, {"type": "step", "title": {"bn": "একটানা ৬০ দিন রোজা", "en": "Fast 60 consecutive days"}, "text": {"bn": "মাঝে এক দিনও বাদ পড়লে (নারীর হায়েজ ছাড়া) নতুন করে শুরু করতে হবে।", "en": "If even one day is missed (except a woman''s menstruation), it must be started again."}}, {"type": "step", "title": {"bn": "৬০ জন মিসকিনকে খাওয়ানো", "en": "Feed 60 poor people"}, "text": {"bn": "অসুস্থতা বা বার্ধক্যের কারণে ৬০ রোজা রাখতে অক্ষম হলে ৬০ জন মিসকিনকে দুই বেলা পেট ভরে খাওয়াবেন, অথবা (হানাফি মতে) প্রত্যেককে একটি ফিতরা পরিমাণ দেবেন।", "en": "If unable to fast 60 days due to illness or old age, feed 60 poor people two full meals each, or (Hanafi view) give each the amount of one sadaqatul fitr."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৯৩৬; সহিহ মুসলিম ১১১১", "en": "Sahih al-Bukhari 1936; Sahih Muslim 1111"}}, {"type": "differ", "title": {"bn": "ইচ্ছাকৃত খাওয়া-দাওয়ায় কাফফারা আছে কি না", "en": "Is kaffarah due for deliberate eating and drinking"}, "views": [{"label": {"bn": "হানাফি ও মালেকি", "en": "Hanafi and Maliki"}, "text": {"bn": "বিনা ওজরে রমজানের রোজা ইচ্ছাকৃতভাবে খেয়ে বা পান করে ভাঙলেও কাজা ও কাফফারা দুটোই লাগবে।", "en": "Deliberately breaking a Ramadan fast by eating or drinking without excuse also requires both make-up and kaffarah."}, "evidence": {"bn": "কাফফারার কারণ রমজানের পবিত্রতা ইচ্ছাকৃতভাবে নষ্ট করা, যা খাওয়া-দাওয়াতেও পাওয়া যায়।", "en": "The cause of kaffarah is deliberately violating the sanctity of Ramadan, which also happens by eating."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "কাফফারা শুধু সহবাসের ক্ষেত্রে; খাওয়া-দাওয়ায় শুধু কাজা এবং তওবা।", "en": "Kaffarah is only for intercourse; for eating and drinking only make-up and repentance."}, "evidence": {"bn": "হাদিসে কাফফারা শুধু সহবাসের ঘটনায় এসেছে; অন্য কিছুকে এর সাথে মেলানো যায় না।", "en": "The hadith mentions kaffarah only for intercourse; other cases are not joined to it."}}]}, {"type": "heading", "text": {"bn": "ফিদইয়া", "en": "Fidya (compensation)"}}, {"type": "text", "text": {"bn": "যে ব্যক্তি বার্ধক্য বা আরোগ্যের আশা নেই এমন রোগের কারণে রোজা রাখতে পারেন না এবং পরে কাজা করারও সম্ভাবনা নেই, তিনি প্রতিটি রোজার বদলে একজন মিসকিনকে খাবার দেবেন। একে ফিদইয়া বলে।", "en": "A person who cannot fast because of old age or an illness with no hope of recovery, and who has no prospect of making it up later, feeds one poor person for each day missed. This is called fidya."}}, {"type": "arabic", "ar": "وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ طَعَامُ مِسْكِينٍ", "pron": {"bn": "ওয়া আলাল্লাযীনা ইউতীকূনাহূ ফিদইয়াতুন তাআমু মিসকীন", "en": "Wa ''alal-ladhina yutiqunahu fidyatun ta''amu miskin"}, "meaning": {"bn": "আর যাদের জন্য এটা অত্যন্ত কষ্টকর, তাদের ওপর ফিদইয়া: একজন মিসকিনকে খাওয়ানো।", "en": "And upon those who can only do it with great hardship, a compensation: feeding a poor person."}, "ref": {"bn": "সূরা বাকারা ২:১৮৪", "en": "Al-Baqarah 2:184"}}, {"type": "differ", "title": {"bn": "ফিদইয়ার পরিমাণ", "en": "Amount of fidya"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "প্রতি রোজার জন্য একটি সদকাতুল ফিতরের সমান (অর্ধ সা'' গম বা এক সা'' খেজুর/যব), অথবা তার বাজারমূল্য; কিংবা একজন মিসকিনকে দুই বেলা পেট ভরে খাওয়ানো।", "en": "For each fast, the amount of one sadaqatul fitr (half a sa'' of wheat or a sa'' of dates/barley) or its market value; or two full meals for one poor person."}, "evidence": {"bn": "সদকাতুল ফিতরের পরিমাণের ওপর কিয়াস; হানাফি মতে মূল্য দেওয়াও জায়েজ।", "en": "Analogy with sadaqatul fitr; Hanafis allow giving the value."}}, {"label": {"bn": "শাফেয়ি, মালেকি, হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "প্রতি রোজার জন্য এক মুদ (প্রায় ৫০০–৬০০ গ্রাম) খাদ্যশস্য; হাম্বলি মতে গম হলে এক মুদ, অন্য শস্য হলে অর্ধ সা''। টাকা দিলে আদায় হবে না।", "en": "One mudd (about 500–600 g) of staple food per fast; Hanbalis: a mudd of wheat or half a sa'' of other grain. Money does not count."}, "evidence": {"bn": "সাহাবিদের আমল, যেমন ইবনে আব্বাস (রা.) ও আনাস (রা.)-এর ফতোয়া।", "en": "Practice of the Companions, e.g. the fatwas of Ibn Abbas and Anas."}}]}, {"type": "note", "tone": "warn", "text": {"bn": "সুস্থ মানুষ, যিনি পরে কাজা করতে পারবেন, তার জন্য ফিদইয়া দিয়ে রোজা ছেড়ে দেওয়া জায়েজ নয়। ফিদইয়া দেওয়ার পর আল্লাহর রহমতে সুস্থ হয়ে গেলে হানাফি মতে কাজা করতে হবে।", "en": "A healthy person who can make up later may not skip fasts by paying fidya. If someone pays fidya and later recovers, in the Hanafi view he must make up the fasts."}}]', 'in_review', 40 FROM is_guide_topics WHERE slug = 'sawm' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '3b72a95f-8b60-524e-b519-bbe73b272a75', id, 'sawm-excused', '{"bn": "যাদের জন্য রোজা না রাখার অনুমতি আছে", "en": "Who is excused from fasting"}', '{"bn": "অসুস্থ, মুসাফির, গর্ভবতী ও দুগ্ধদানকারী মা, বৃদ্ধ, আর হায়েজ-নিফাস অবস্থায় নারীর বিধান।", "en": "Rulings for the sick, travellers, pregnant and nursing mothers, the elderly, and women in menstruation or post-natal bleeding."}', 'basic', '[{"type": "arabic", "ar": "يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْرَ", "pron": {"bn": "ইউরীদুল্লাহু বিকুমুল ইউসরা ওয়ালা ইউরীদু বিকুমুল উসর", "en": "Yuridullahu bikumul-yusra wa la yuridu bikumul-''usr"}, "meaning": {"bn": "আল্লাহ তোমাদের জন্য সহজ চান, কঠিন চান না।", "en": "Allah intends ease for you and does not intend hardship."}, "ref": {"bn": "সূরা বাকারা ২:১৮৫", "en": "Al-Baqarah 2:185"}}, {"type": "table", "head": [{"bn": "কে", "en": "Who"}, {"bn": "রোজা", "en": "Fasting"}, {"bn": "পরে করণীয়", "en": "Afterwards"}], "rows": [[{"bn": "অসুস্থ (রোজায় রোগ বাড়ার বা দেরিতে সারার আশঙ্কা)", "en": "Sick (fasting may worsen or prolong the illness)"}, {"bn": "না রাখার অনুমতি", "en": "May leave it"}, {"bn": "সুস্থ হলে কাজা", "en": "Make up when well"}], [{"bn": "মুসাফির (শরিয়তসম্মত সফর)", "en": "Traveller (Shariah-defined journey)"}, {"bn": "রাখা বা না রাখা দুটোই জায়েজ", "en": "May fast or not"}, {"bn": "না রাখলে কাজা", "en": "Make up if not fasted"}], [{"bn": "গর্ভবতী বা দুগ্ধদানকারী মা (নিজের বা সন্তানের ক্ষতির আশঙ্কা)", "en": "Pregnant or nursing mother (fears harm to herself or the child)"}, {"bn": "না রাখার অনুমতি", "en": "May leave it"}, {"bn": "কাজা; ফিদইয়া নিয়ে মতভেদ নিচে", "en": "Make up; fidya is differed on, see below"}], [{"bn": "অতি বৃদ্ধ বা চিরস্থায়ী রোগী", "en": "Very elderly or chronically ill"}, {"bn": "না রাখার অনুমতি", "en": "May leave it"}, {"bn": "প্রতিদিনের জন্য ফিদইয়া", "en": "Fidya for each day"}], [{"bn": "হায়েজ বা নিফাস অবস্থায় নারী", "en": "Woman in menstruation or post-natal bleeding"}, {"bn": "রাখা নিষেধ", "en": "Must not fast"}, {"bn": "পরে কাজা", "en": "Make up later"}]]}, {"type": "heading", "text": {"bn": "অসুস্থ ব্যক্তি", "en": "The sick"}}, {"type": "text", "text": {"bn": "শুধু সামান্য অসুবিধা নয়, বরং অভিজ্ঞ চিকিৎসকের মতামত বা নিজের অভিজ্ঞতা থেকে যদি প্রবল ধারণা হয় যে রোজা রাখলে রোগ বাড়বে, দেরিতে সারবে বা মারাত্মক ক্ষতি হবে, তাহলে রোজা না রেখে পরে কাজা করবেন। প্রাণের আশঙ্কা থাকলে রোজা ভেঙে ফেলাই আবশ্যক।", "en": "Not a minor discomfort, but when an experienced doctor''s opinion or one''s own experience strongly suggests that fasting will worsen the illness, delay recovery or cause serious harm, one does not fast and makes it up later. If life is at risk, breaking the fast is required."}}, {"type": "heading", "text": {"bn": "মুসাফির", "en": "The traveller"}}, {"type": "text", "text": {"bn": "শরিয়তসম্মত সফরে (হানাফি মতে প্রায় ৪৮ মাইল বা ৭৭–৭৮ কিলোমিটার বা তার বেশি দূরত্বের সফর) রোজা না রাখার অনুমতি আছে। কষ্ট না হলে রাখাই উত্তম, কষ্ট হলে না রাখা উত্তম। সফর শুরুর দিন সকালে বাড়িতে রোজা শুরু করলে হানাফি মতে সেদিনের রোজা পূর্ণ করাই উচিত।", "en": "On a Shariah journey (Hanafi: about 48 miles / 77–78 km or more) one may leave the fast. If it is not hard, fasting is better; if it is hard, not fasting is better. If you began the fast at home on the morning you set out, Hanafis say you should complete that day."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৯৪৩; সহিহ মুসলিম ১১২১", "en": "Sahih al-Bukhari 1943; Sahih Muslim 1121"}}, {"type": "heading", "text": {"bn": "গর্ভবতী ও দুগ্ধদানকারী মা", "en": "Pregnant and nursing mothers"}}, {"type": "text", "text": {"bn": "নিজের বা সন্তানের স্বাস্থ্যের ক্ষতির আশঙ্কা থাকলে তারা রোজা না রেখে পরে রাখতে পারেন। নবী (সা.) বলেছেন, আল্লাহ মুসাফির, গর্ভবতী ও দুগ্ধদানকারী মায়ের জন্য রোজায় ছাড় দিয়েছেন।", "en": "If they fear harm to their own health or the child''s, they may leave the fast and keep it later. The Prophet said that Allah has relieved the traveller, the pregnant and the nursing woman of fasting."}}, {"type": "ref", "text": {"bn": "জামে তিরমিজি; সুনান আবু দাউদ (আনাস ইবনে মালিক আল-কা''বি রা.-এর বর্ণনা)", "en": "Jami'' at-Tirmidhi; Sunan Abi Dawud (narration of Anas ibn Malik al-Ka''bi)"}, "check": true}, {"type": "differ", "title": {"bn": "কাজার সঙ্গে ফিদইয়াও লাগবে কি না", "en": "Is fidya due along with the make-up"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "শুধু কাজা; ফিদইয়া লাগবে না, ক্ষতির আশঙ্কা নিজের জন্য হোক বা সন্তানের জন্য।", "en": "Only make-up, no fidya, whether the fear was for herself or the child."}, "evidence": {"bn": "তারা অসুস্থ ব্যক্তির মতো, যার জন্য কুরআনে শুধু কাজার কথা বলা হয়েছে।", "en": "They are like the sick person, for whom the Quran mentions only make-up."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "শুধু নিজের জন্য ভয় হলে কাজা; সন্তানের জন্য ভয়ে রোজা না রাখলে কাজার সাথে প্রতিদিন এক মুদ ফিদইয়াও।", "en": "If she feared only for herself, make-up; if she left it fearing for the child, make-up plus one mudd of fidya per day."}, "evidence": {"bn": "ইবনে আব্বাস (রা.) ও ইবনে উমর (রা.)-এর ফতোয়া।", "en": "Fatwas of Ibn Abbas and Ibn Umar."}}, {"label": {"bn": "মালেকি", "en": "Maliki"}, "text": {"bn": "গর্ভবতী শুধু কাজা করবেন; দুগ্ধদানকারী মা কাজা ও ফিদইয়া দুটোই।", "en": "The pregnant woman only makes up; the nursing mother makes up and pays fidya."}, "evidence": {"bn": "গর্ভাবস্থাকে অসুস্থতার মতো ধরা হয়, দুধ খাওয়ানোকে নয়।", "en": "Pregnancy is treated like illness, nursing is not."}}]}, {"type": "heading", "text": {"bn": "বৃদ্ধ ও স্থায়ী রোগী", "en": "The elderly and chronically ill"}}, {"type": "text", "text": {"bn": "যে বৃদ্ধ রোজা রাখার শক্তি রাখেন না, বা যার রোগ সারার আশা নেই, তিনি প্রতিটি রোজার বদলে ফিদইয়া দেবেন। বিস্তারিত ''কাজা, কাফফারা ও ফিদইয়া'' গাইডে।", "en": "An elderly person without the strength to fast, or someone with no hope of recovery, gives fidya for each day. Details are in the ''Qaza, kaffarah and fidya'' guide."}}, {"type": "heading", "text": {"bn": "হায়েজ ও নিফাস", "en": "Menstruation and post-natal bleeding"}}, {"type": "list", "items": [{"bn": "হায়েজ বা নিফাস অবস্থায় রোজা রাখা জায়েজ নয়; পরে কাজা করতে হবে। নামাজের কাজা নেই, রোজার কাজা আছে।", "en": "Fasting is not allowed during menstruation or post-natal bleeding; the fasts are made up later. Prayers are not made up, fasts are."}, {"bn": "দিনের বেলায় রক্ত শুরু হলে সেদিনের রোজা ভেঙে যায়, ইফতারের এক মিনিট আগে হলেও।", "en": "If bleeding starts during the day, that day''s fast is broken, even a minute before sunset."}, {"bn": "ফজরের আগে পবিত্র হয়ে গেলে রোজা রাখবেন, গোসল ফজরের পরে করলেও সমস্যা নেই।", "en": "If she becomes pure before Fajr she fasts, even if she takes the ghusl after Fajr."}, {"bn": "দিনের বেলায় পবিত্র হলে হানাফি মতে সন্ধ্যা পর্যন্ত খাওয়া-দাওয়া থেকে বিরত থাকা উচিত, তবে সেদিনের কাজা করতে হবে।", "en": "If she becomes pure during the day, Hanafis say she should refrain from eating until sunset, but still make up that day."}, {"bn": "ওষুধ খেয়ে মাসিক পিছিয়ে দেওয়া স্বাস্থ্যের ক্ষতি না হলে অনেক আলেমের মতে জায়েজ, তবে স্বাভাবিক নিয়মে চলাই উত্তম।", "en": "Delaying the period with pills is allowed by many scholars if it causes no harm, though following the natural course is better."}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৩৩৫", "en": "Sahih Muslim 335"}}]', 'in_review', 50 FROM is_guide_topics WHERE slug = 'sawm' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '5891afe3-03f2-5fb7-bea1-0c36aba5b830', id, 'sawm-laylatul-qadr-itikaf', '{"bn": "লাইলাতুল কদর ও ইতিকাফ", "en": "Laylatul Qadr and i''tikaf"}', '{"bn": "হাজার মাসের চেয়ে উত্তম রাত খোঁজা, এ রাতের দোয়া এবং শেষ দশকের ইতিকাফের নিয়ম।", "en": "Seeking the night better than a thousand months, its dua, and i''tikaf in the last ten nights."}', 'basic', '[{"type": "heading", "text": {"bn": "লাইলাতুল কদর (শবে কদর)", "en": "Laylatul Qadr"}}, {"type": "arabic", "ar": "لَيْلَةُ الْقَدْرِ خَيْرٌ مِنْ أَلْفِ شَهْرٍ", "pron": {"bn": "লাইলাতুল কাদরি খাইরুম মিন আলফি শাহর", "en": "Laylatul-qadri khayrum min alfi shahr"}, "meaning": {"bn": "কদরের রাত হাজার মাসের চেয়েও উত্তম।", "en": "The Night of Decree is better than a thousand months."}, "ref": {"bn": "সূরা কদর ৯৭:৩", "en": "Al-Qadr 97:3"}}, {"type": "text", "text": {"bn": "এই রাতে কুরআন নাজিল হয়েছে। যে ব্যক্তি ঈমানের সাথে ও সওয়াবের আশায় এ রাতে ইবাদত করে, তার আগের গুনাহ ক্ষমা করা হয়। নির্দিষ্ট তারিখ জানানো হয়নি; রমজানের শেষ দশকের বেজোড় রাতগুলোতে খুঁজতে বলা হয়েছে (২১, ২৩, ২৫, ২৭, ২৯-এর রাত)। ২৭-এর রাতের কথা অনেক সাহাবি বলেছেন, তবে শুধু এক রাতে সীমাবদ্ধ না থেকে পুরো শেষ দশকে চেষ্টা করুন।", "en": "The Quran was revealed on this night. Whoever stands in worship on it with faith and hoping for reward has his past sins forgiven. Its date was not fixed; we are told to seek it in the odd nights of the last ten of Ramadan (the nights before the 21st, 23rd, 25th, 27th, 29th). Many Companions held it to be the 27th, but strive through all of the last ten rather than one night."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৯০১; সহিহ বুখারি ২০১৭; সহিহ মুসলিম ৭৬২", "en": "Sahih al-Bukhari 1901; Sahih al-Bukhari 2017; Sahih Muslim 762"}}, {"type": "arabic", "label": {"bn": "লাইলাতুল কদরের দোয়া", "en": "Dua for Laylatul Qadr"}, "ar": "اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي", "pron": {"bn": "আল্লাহুম্মা ইন্নাকা আফুওউন তুহিব্বুল আফওয়া ফা''ফু আন্নি", "en": "Allahumma innaka ''afuwwun tuhibbul-''afwa fa''fu ''anni"}, "meaning": {"bn": "হে আল্লাহ! তুমি ক্ষমাশীল, ক্ষমা করতে ভালোবাসো, অতএব আমাকে ক্ষমা করো।", "en": "O Allah, You are Pardoning and love to pardon, so pardon me."}, "ref": {"bn": "জামে তিরমিজি ৩৫১৩; সুনান ইবনে মাজাহ ৩৮৫০", "en": "Jami'' at-Tirmidhi 3513; Sunan Ibn Majah 3850"}}, {"type": "note", "tone": "info", "text": {"bn": "আয়েশা (রা.) জিজ্ঞেস করেছিলেন, কদরের রাত পেলে কী বলবেন; নবী (সা.) এই দোয়াটি শিখিয়ে দেন। কিছু ছাপা বইয়ে ''আফুওউন''-এর পরে ''কারীম'' শব্দটি আছে, তবে নির্ভরযোগ্য বর্ণনায় এটি নেই।", "en": "Aishah asked what she should say if she found the Night of Decree, and the Prophet taught her this dua. Some printed editions add ''karim'' after ''''afuwwun'', but the reliable narrations do not have it."}}, {"type": "list", "items": [{"bn": "নফল নামাজ, কুরআন তিলাওয়াত, জিকির, দোয়া ও ইস্তিগফার করুন।", "en": "Pray voluntary prayers, recite the Quran, do dhikr, make dua and seek forgiveness."}, {"bn": "এ রাতের জন্য নির্দিষ্ট রাকাত সংখ্যা বা বিশেষ সূরা দিয়ে নির্দিষ্ট পদ্ধতির নামাজ হাদিসে নেই; প্রচলিত এমন পদ্ধতিগুলো ভিত্তিহীন।", "en": "No hadith sets a particular number of rakats or special surahs for a ''Qadr prayer''; such popular methods have no basis."}, {"bn": "ভোরে সূর্য আলোকরশ্মি ছাড়া স্নিগ্ধভাবে ওঠা এ রাতের একটি আলামত হিসেবে বর্ণিত।", "en": "One reported sign is that the sun rises the next morning soft, without strong rays."}]}, {"type": "heading", "text": {"bn": "ইতিকাফ", "en": "I''tikaf"}}, {"type": "text", "text": {"bn": "ইতিকাফ মানে ইবাদতের নিয়তে মসজিদে অবস্থান করা। নবী (সা.) ইন্তেকাল পর্যন্ত প্রতি রমজানের শেষ দশ দিন ইতিকাফ করেছেন। হানাফি মতে রমজানের শেষ দশকের ইতিকাফ সুন্নতে মুয়াক্কাদা আলাল কিফায়া: মহল্লার কেউ একজন করলে সবার পক্ষ থেকে আদায় হয়।", "en": "I''tikaf means staying in the masjid with the intention of worship. The Prophet did i''tikaf in the last ten days of every Ramadan until he passed away. For Hanafis the i''tikaf of the last ten of Ramadan is a communal emphasised sunnah: if one person of the locality does it, the duty is fulfilled for all."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২০২৬; সহিহ মুসলিম ১১৭২", "en": "Sahih al-Bukhari 2026; Sahih Muslim 1172"}}, {"type": "arabic", "ar": "وَلَا تُبَاشِرُوهُنَّ وَأَنْتُمْ عَاكِفُونَ فِي الْمَسَاجِدِ", "pron": {"bn": "ওয়ালা তুবাশিরূহুন্না ওয়া আনতুম আকিফূনা ফিল মাসাজিদ", "en": "Wa la tubashiruhunna wa antum ''akifuna fil-masajid"}, "meaning": {"bn": "আর মসজিদে ইতিকাফ অবস্থায় তোমরা স্ত্রীদের সঙ্গে মেলামেশা করো না।", "en": "And do not have relations with them while you are in i''tikaf in the masjids."}, "ref": {"bn": "সূরা বাকারা ২:১৮৭", "en": "Al-Baqarah 2:187"}}, {"type": "step", "title": {"bn": "শুরু", "en": "Start"}, "text": {"bn": "২০ রমজান সূর্যাস্তের আগে ইতিকাফের নিয়তে মসজিদে প্রবেশ করুন (মনে মনে নিয়তই যথেষ্ট)।", "en": "Enter the masjid before sunset on the 20th of Ramadan with the intention of i''tikaf (an intention in the heart is enough)."}}, {"type": "step", "title": {"bn": "অবস্থান", "en": "Stay"}, "text": {"bn": "শেষ দশ দিন মসজিদেই থাকবেন; ঘুম, খাওয়া সব মসজিদে। সময় কাটান নামাজ, তিলাওয়াত, জিকির, দোয়া ও দ্বীনি পড়াশোনায়।", "en": "Stay in the masjid for the last ten days, sleeping and eating there. Spend the time in prayer, recitation, dhikr, dua and religious study."}}, {"type": "step", "title": {"bn": "বের হওয়া", "en": "Going out"}, "text": {"bn": "শুধু প্রয়োজনে বের হওয়া যায়: প্রস্রাব-পায়খানা, ফরজ গোসল, খাবার এনে দেওয়ার কেউ না থাকলে খাবার আনা, আর মসজিদে জুমা না হলে জুমার জন্য। প্রয়োজন শেষ হলেই ফিরে আসবেন।", "en": "Leave only for needs: the toilet, an obligatory ghusl, fetching food if no one can bring it, and Jumu''ah if it is not held in that masjid. Return as soon as the need is done."}}, {"type": "step", "title": {"bn": "শেষ", "en": "End"}, "text": {"bn": "শাওয়ালের চাঁদ দেখা গেলে (ঈদের আগের সন্ধ্যায়) ইতিকাফ শেষ।", "en": "I''tikaf ends when the Shawwal moon is sighted (the evening before Eid)."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২০২৯", "en": "Sahih al-Bukhari 2029"}}, {"type": "note", "tone": "warn", "text": {"bn": "বিনা প্রয়োজনে মসজিদ থেকে বের হলে বা স্ত্রী-সহবাস করলে ইতিকাফ ভেঙে যায়। অপ্রয়োজনীয় গল্প, মোবাইল ঘাঁটা ও অনর্থক কাজ থেকে দূরে থাকুন।", "en": "Leaving the masjid without need or marital relations break the i''tikaf. Avoid idle chatter, endless phone scrolling and pointless activity."}}, {"type": "differ", "title": {"bn": "নারীদের ইতিকাফ কোথায়", "en": "Where women do i''tikaf"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "নারীরা ঘরের নামাজের জন্য নির্দিষ্ট স্থানে (মসজিদে বাইত) ইতিকাফ করবেন; এটাই তাদের জন্য উত্তম।", "en": "Women do i''tikaf in the place set aside for prayer in the home (masjid al-bayt); this is better for them."}, "evidence": {"bn": "নারীদের নামাজ ঘরে উত্তম হওয়ার হাদিসগুলোর ওপর কিয়াস।", "en": "Analogy with the hadiths that a woman''s prayer at home is better."}}, {"label": {"bn": "শাফেয়ি, মালেকি, হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "নারী-পুরুষ সবার ইতিকাফ মসজিদেই হতে হবে, যদি নিরাপদ ব্যবস্থা থাকে।", "en": "I''tikaf for men and women alike must be in a masjid, where it is safe and suitable."}, "evidence": {"bn": "আয়াতে ''মসজিদে'' বলা হয়েছে, আর নবীপত্নীগণ মসজিদে ইতিকাফ করেছেন।", "en": "The verse says ''in the masjids'', and the Prophet''s wives did i''tikaf in the masjid."}}]}]', 'in_review', 60 FROM is_guide_topics WHERE slug = 'sawm' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '4d92f55d-3e37-5f12-83f3-12dda2e9ccfb', id, 'sawm-sadaqatul-fitr', '{"bn": "সদকাতুল ফিতর (ফিতরা)", "en": "Sadaqatul fitr (fitrah)"}', '{"bn": "ঈদুল ফিতরের আগে আদায় করা ওয়াজিব দান: কার ওপর, কত, কখন এবং কাকে দেবেন।", "en": "The charity due before Eid al-Fitr: who pays, how much, when and to whom."}', 'basic', '[{"type": "text", "text": {"bn": "সদকাতুল ফিতর রোজার ভুলত্রুটি থেকে রোজাদারকে পবিত্র করে এবং গরিবদের ঈদের দিনের খাবারের ব্যবস্থা করে। নবী (সা.) প্রত্যেক মুসলিম নারী-পুরুষ, ছোট-বড়, স্বাধীন-দাস সবার পক্ষ থেকে ঈদের নামাজে যাওয়ার আগে এক সা'' খেজুর বা এক সা'' যব দেওয়ার নির্দেশ দিয়েছেন।", "en": "Sadaqatul fitr purifies the fasting person from idle and indecent talk and provides food for the poor on Eid. The Prophet ordered one sa'' of dates or one sa'' of barley on behalf of every Muslim, male and female, young and old, free and slave, to be given before people go out to the Eid prayer."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৫০৩; সুনান আবু দাউদ ১৬০৯", "en": "Sahih al-Bukhari 1503; Sunan Abi Dawud 1609"}}, {"type": "heading", "text": {"bn": "কার ওপর ওয়াজিব", "en": "Who must pay"}}, {"type": "differ", "title": {"bn": "ফিতরা কার ওপর ওয়াজিব", "en": "On whom fitrah is due"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "ঈদের দিন সুবহে সাদিকের সময় যে মুসলিম মৌলিক প্রয়োজনের অতিরিক্ত নিসাব পরিমাণ সম্পদের মালিক, তার ওপর ওয়াজিব (এক বছর পূর্ণ হওয়া শর্ত নয়)। নিজের ও নাবালেগ সন্তানের পক্ষ থেকে দেবেন।", "en": "Due on a Muslim who, at dawn on Eid day, owns wealth of nisab value beyond basic needs (a full year is not required). He pays for himself and his minor children."}, "evidence": {"bn": "হাদিস: ''সদকা কেবল সচ্ছলতা থেকেই।''", "en": "Hadith: ''Charity is only from surplus wealth.''"}}, {"label": {"bn": "শাফেয়ি, মালেকি, হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "ঈদের দিন ও রাতের খাবারের অতিরিক্ত এক সা'' খাদ্য যার কাছে আছে, তার ওপরই ওয়াজিব; নিসাব শর্ত নয়। পরিবারের যাদের ভরণপোষণ তার দায়িত্বে, তাদের পক্ষ থেকেও দেবেন।", "en": "Due on anyone who has one sa'' of food beyond what he needs for Eid day and night; nisab is not required. He also pays for those he must support."}, "evidence": {"bn": "হাদিসে ''প্রত্যেক মুসলিমের ওপর'' বলা হয়েছে, ধনী হওয়ার শর্ত নেই।", "en": "The hadith says ''on every Muslim'' without a condition of wealth."}}]}, {"type": "note", "tone": "tip", "text": {"bn": "রোজা রাখতে না পারলেও ফিতরা দিতে হবে। ঈদের দিন ফজরের আগে জন্ম নেওয়া শিশুর পক্ষ থেকেও দিতে হয়।", "en": "Fitrah is due even from someone who could not fast, and also for a child born before Fajr on Eid day."}}, {"type": "heading", "text": {"bn": "পরিমাণ", "en": "Amount"}}, {"type": "table", "head": [{"bn": "খাদ্য", "en": "Food"}, {"bn": "হানাফি মতে পরিমাণ", "en": "Hanafi amount"}, {"bn": "অন্য তিন মাজহাব", "en": "Other three madhhabs"}], "rows": [[{"bn": "গম বা আটা", "en": "Wheat or flour"}, {"bn": "অর্ধ সা'' (প্রায় ১ কেজি ৬৫০ গ্রাম)", "en": "Half a sa'' (about 1.65 kg)"}, {"bn": "এক সা''", "en": "One sa''"}], [{"bn": "খেজুর", "en": "Dates"}, {"bn": "এক সা'' (প্রায় ৩ কেজি ৩০০ গ্রাম)", "en": "One sa'' (about 3.3 kg)"}, {"bn": "এক সা''", "en": "One sa''"}], [{"bn": "যব", "en": "Barley"}, {"bn": "এক সা''", "en": "One sa''"}, {"bn": "এক সা''", "en": "One sa''"}], [{"bn": "কিশমিশ", "en": "Raisins"}, {"bn": "এক সা'' (এক বর্ণনায় অর্ধ সা'')", "en": "One sa'' (half in one report)"}, {"bn": "এক সা''", "en": "One sa''"}], [{"bn": "পনির", "en": "Dried cheese (aqit)"}, {"bn": "এক সা''", "en": "One sa''"}, {"bn": "এক সা''", "en": "One sa''"}], [{"bn": "চাল বা অন্য প্রধান খাদ্য", "en": "Rice or other staple"}, {"bn": "মূল্য হিসেবে ওপরের কোনোটির সমান", "en": "Equal in value to one of the above"}, {"bn": "এক সা'' (প্রায় ২.৫–৩ কেজি; সা''-এর ওজন নিয়ে মতভেদ আছে)", "en": "One sa'' (about 2.5–3 kg; the weight of a sa'' is differed on)"}]]}, {"type": "differ", "title": {"bn": "টাকা দিয়ে ফিতরা দেওয়া যাবে কি না", "en": "Can fitrah be paid in money"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "খাদ্য বা তার বাজারমূল্য দুটোই দেওয়া যায়; গরিবের প্রয়োজন বিবেচনায় টাকা দেওয়া অনেক সময় উত্তম। বাংলাদেশে প্রতি বছর ইসলামিক ফাউন্ডেশন গম, যব, খেজুর, কিশমিশ ও পনিরের দাম ধরে সর্বনিম্ন ও সর্বোচ্চ পরিমাণ ঘোষণা করে; সামর্থ্য অনুযায়ী উচ্চতর খাদ্যের মূল্যে দেওয়া উত্তম।", "en": "Food or its market value may be given; money is often better given the needs of the poor. In Bangladesh the Islamic Foundation announces each year the amounts based on wheat, barley, dates, raisins and cheese; giving at the rate of a higher food is better for those who can."}, "evidence": {"bn": "উদ্দেশ্য গরিবের প্রয়োজন পূরণ; উমর ইবনে আবদুল আজিজসহ কিছু তাবেয়ির আমল এবং মুয়াজ (রা.) থেকে যাকাতে পণ্যের বদলে মূল্য গ্রহণের বর্ণনা।", "en": "The aim is to meet the needs of the poor; the practice of some Successors such as Umar ibn Abd al-Aziz, and reports from Mu''adh of taking value in zakat."}}, {"label": {"bn": "শাফেয়ি, মালেকি, হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "নির্ধারিত খাদ্যই দিতে হবে (দেশের প্রধান খাদ্য, যেমন চাল); টাকা দিলে আদায় হবে না।", "en": "It must be given as food (the local staple, such as rice); money does not discharge it."}, "evidence": {"bn": "নবী (সা.) ও সাহাবিরা দিনার-দিরহাম থাকা সত্ত্বেও খাদ্য দিয়েছেন, এবং হাদিসে খাদ্যের নাম উল্লেখ করা হয়েছে।", "en": "The Prophet and Companions gave food although coins existed, and the hadith names foods."}}]}, {"type": "heading", "text": {"bn": "কখন ও কাকে", "en": "When and to whom"}}, {"type": "list", "items": [{"bn": "ঈদের নামাজে যাওয়ার আগে দেওয়া উত্তম। সাহাবিরা ঈদের এক-দুই দিন আগেও দিতেন। গরিবরা যাতে ঈদের প্রস্তুতি নিতে পারে, তাই কয়েক দিন আগে দেওয়াও ভালো (হানাফি মতে রমজানের যেকোনো সময় দেওয়া যায়)।", "en": "Best before the Eid prayer. The Companions gave it a day or two before Eid. Giving a few days early helps the poor prepare (Hanafis allow any time in Ramadan)."}, {"bn": "ঈদের নামাজের পর পর্যন্ত দেরি করা ঠিক নয়; দেরি হলেও দায়িত্ব শেষ হয় না, আদায় করতেই হবে।", "en": "Do not delay it past the Eid prayer; if delayed, it is still owed and must be paid."}, {"bn": "যাকাতের যারা হকদার, ফিতরাও তাদেরই দেবেন, বিশেষ করে গরিব-মিসকিন। নিজের মা-বাবা, সন্তান ও স্ত্রীকে দেওয়া যায় না।", "en": "Give it to those eligible for zakat, especially the poor and needy; not to one''s own parents, children or spouse."}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি (ইবনে উমর রা. ঈদের এক-দুই দিন আগে ফিতরা দিতেন)", "en": "Sahih al-Bukhari (Ibn Umar gave it a day or two before Eid)"}, "check": true}]', 'in_review', 70 FROM is_guide_topics WHERE slug = 'sawm' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '8498d3a7-f68f-5632-9fe6-a0a1fd3e4c5f', id, 'sawm-nafl-and-forbidden', '{"bn": "নফল রোজা ও যেসব দিনে রোজা নিষেধ", "en": "Voluntary fasts and forbidden fasting days"}', '{"bn": "শাওয়ালের ছয় রোজা, আরাফা, আশুরা, সোম-বৃহস্পতিবার, আইয়ামে বিজ এবং যেদিন রোজা রাখা নিষেধ।", "en": "Six of Shawwal, Arafah, Ashura, Mondays and Thursdays, the White Days, and the days fasting is forbidden."}', 'basic', '[{"type": "heading", "text": {"bn": "সুন্নত ও নফল রোজা", "en": "Sunnah and voluntary fasts"}}, {"type": "table", "head": [{"bn": "রোজা", "en": "Fast"}, {"bn": "ফজিলত", "en": "Virtue"}, {"bn": "সূত্র", "en": "Source"}], "rows": [[{"bn": "শাওয়ালের ছয় রোজা", "en": "Six days of Shawwal"}, {"bn": "রমজানের পর ছয়টি রাখলে সারা বছর রোজার সমান; একটানা বা আলাদা দুইভাবেই রাখা যায়", "en": "With Ramadan, like fasting the whole year; may be kept consecutively or spread out"}, {"bn": "সহিহ মুসলিম ১১৬৪", "en": "Sahih Muslim 1164"}], [{"bn": "আরাফার দিন (৯ জিলহজ)", "en": "Day of Arafah (9 Dhul Hijjah)"}, {"bn": "আগের ও পরের এক বছরের গুনাহের কাফফারা হওয়ার আশা", "en": "Hoped to expiate the sins of the year before and the year after"}, {"bn": "সহিহ মুসলিম ১১৬২", "en": "Sahih Muslim 1162"}], [{"bn": "আশুরা (১০ মুহাররম)", "en": "Ashura (10 Muharram)"}, {"bn": "আগের এক বছরের গুনাহের কাফফারা হওয়ার আশা; সঙ্গে ৯ তারিখও রাখা সুন্নত", "en": "Hoped to expiate the previous year; fasting the 9th with it is sunnah"}, {"bn": "সহিহ মুসলিম ১১৬২, ১১৩৪", "en": "Sahih Muslim 1162, 1134"}], [{"bn": "সোমবার ও বৃহস্পতিবার", "en": "Mondays and Thursdays"}, {"bn": "এ দুই দিনে আমল আল্লাহর কাছে পেশ করা হয়; সোমবার নবী (সা.)-এর জন্মদিন", "en": "Deeds are presented to Allah on these days; Monday is the day the Prophet was born"}, {"bn": "সহিহ মুসলিম ১১৬২; জামে তিরমিজি ৭৪৭", "en": "Sahih Muslim 1162; Jami'' at-Tirmidhi 747"}], [{"bn": "আইয়ামে বিজ (চান্দ্রমাসের ১৩, ১৪, ১৫)", "en": "White Days (13th, 14th, 15th of each lunar month)"}, {"bn": "প্রতি মাসে তিন রোজা সারা বছর রোজার মতো", "en": "Three days each month are like fasting all year"}, {"bn": "সহিহ বুখারি ১৯৮১; জামে তিরমিজি ৭৬১", "en": "Sahih al-Bukhari 1981; Jami'' at-Tirmidhi 761"}], [{"bn": "মুহাররম মাস", "en": "The month of Muharram"}, {"bn": "রমজানের পর সর্বোত্তম রোজা আল্লাহর মাস মুহাররমের রোজা", "en": "The best fasting after Ramadan is in Allah''s month, Muharram"}, {"bn": "সহিহ মুসলিম ১১৬৩", "en": "Sahih Muslim 1163"}], [{"bn": "শাবান মাস", "en": "The month of Sha''ban"}, {"bn": "নবী (সা.) রমজানের পর শাবানেই সবচেয়ে বেশি রোজা রাখতেন", "en": "After Ramadan the Prophet fasted most in Sha''ban"}, {"bn": "সহিহ বুখারি ১৯৬৯", "en": "Sahih al-Bukhari 1969"}]]}, {"type": "note", "tone": "info", "text": {"bn": "হজে থাকা ব্যক্তির জন্য আরাফার দিনে রোজা না রাখাই সুন্নত; নবী (সা.) আরাফায় রোজা রাখেননি, যাতে দোয়া ও ইবাদতে শক্তি থাকে।", "en": "For someone performing hajj, not fasting on the day of Arafah is the sunnah; the Prophet did not fast at Arafah, keeping his strength for dua and worship."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি (উম্মুল ফজল রা.-এর বর্ণনা: আরাফায় নবী সা.-কে দুধ পাঠানো)", "en": "Sahih al-Bukhari (Umm al-Fadl''s report of sending milk to the Prophet at Arafah)"}, "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "নফল রোজা রেখে কোনো কারণে ভেঙে ফেললে হানাফি মতে পরে একটি কাজা করতে হয়; শাফেয়ি ও হাম্বলি মতে কাজা জরুরি নয়, তবে উত্তম।", "en": "If a voluntary fast is broken for some reason, Hanafis require one make-up day; Shafi''is and Hanbalis say it is not required but recommended."}}, {"type": "heading", "text": {"bn": "যেসব দিনে রোজা রাখা নিষেধ", "en": "Days on which fasting is forbidden"}}, {"type": "table", "head": [{"bn": "দিন", "en": "Day"}, {"bn": "হুকুম", "en": "Ruling"}], "rows": [[{"bn": "ঈদুল ফিতরের দিন (১ শাওয়াল)", "en": "Eid al-Fitr (1 Shawwal)"}, {"bn": "হারাম", "en": "Forbidden (haram)"}], [{"bn": "ঈদুল আজহার দিন (১০ জিলহজ)", "en": "Eid al-Adha (10 Dhul Hijjah)"}, {"bn": "হারাম", "en": "Forbidden (haram)"}], [{"bn": "আইয়ামে তাশরিক (১১, ১২, ১৩ জিলহজ)", "en": "Days of Tashriq (11, 12, 13 Dhul Hijjah)"}, {"bn": "নিষেধ; এগুলো খাওয়া-দাওয়া ও আল্লাহর জিকিরের দিন (হাদি জোগাড় করতে না পারা তামাত্তু হাজির জন্য কিছু মাজহাবে ছাড় আছে)", "en": "Forbidden; these are days of eating, drinking and remembering Allah (some madhhabs make an exception for a tamattu'' pilgrim who finds no sacrificial animal)"}], [{"bn": "শুধু জুমার দিনকে আলাদা করে রোজা", "en": "Singling out Friday alone for fasting"}, {"bn": "মাকরুহ; আগের বা পরের দিনসহ রাখলে সমস্যা নেই", "en": "Disliked; fine if joined with the day before or after"}], [{"bn": "সন্দেহের দিন (শাবানের ৩০ তারিখ, চাঁদ নিয়ে সন্দেহ হলে) রমজানের সতর্কতায়", "en": "The day of doubt (30 Sha''ban when the moon is unclear) as a precaution for Ramadan"}, {"bn": "মাকরুহ / নিষেধ; রমজানের এক-দুই দিন আগে থেকে রোজা শুরু করবেন না, তবে নিয়মিত অভ্যাসের রোজা হলে ভিন্ন কথা", "en": "Disliked / forbidden; do not start fasting a day or two before Ramadan, unless it is a regular habitual fast"}], [{"bn": "সারা বছর বিরতিহীন রোজা", "en": "Fasting every day of the year without break"}, {"bn": "নিষেধ", "en": "Forbidden"}], [{"bn": "স্বামী উপস্থিত থাকলে তার অনুমতি ছাড়া স্ত্রীর নফল রোজা", "en": "A wife''s voluntary fast without her husband''s permission when he is present"}, {"bn": "নিষেধ", "en": "Forbidden"}]]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৯৯০; সহিহ মুসলিম ১১৩৭; সহিহ মুসলিম ১১৪১; সহিহ বুখারি ১৯৮৫; সহিহ মুসলিম ১১৪৪; সহিহ বুখারি ১৯১৪; সহিহ বুখারি ১৯৭৭; সহিহ বুখারি ৫১৯৫", "en": "Sahih al-Bukhari 1990; Sahih Muslim 1137; Sahih Muslim 1141; Sahih al-Bukhari 1985; Sahih Muslim 1144; Sahih al-Bukhari 1914; Sahih al-Bukhari 1977; Sahih al-Bukhari 5195"}}]', 'in_review', 80 FROM is_guide_topics WHERE slug = 'sawm' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '5d1955e8-d8f8-5f41-9de3-c7d40af47f17', id, 'zakat-basics', '{"bn": "যাকাত: কার ওপর ফরজ", "en": "Zakat: who must pay"}', '{"bn": "যাকাত ইসলামের তৃতীয় স্তম্ভ। কোন শর্তে যাকাত ফরজ হয় এবং কেন এটি সম্পদকে পবিত্র করে।", "en": "Zakat is the third pillar of Islam. The conditions that make it due and how it purifies wealth."}', 'basic', '[{"type": "arabic", "ar": "وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ", "pron": {"bn": "ওয়া আকীমুস সালাতা ওয়া আতুয যাকাহ", "en": "Wa aqimus-salata wa atuz-zakah"}, "meaning": {"bn": "আর নামাজ কায়েম করো এবং যাকাত দাও।", "en": "And establish the prayer and give the zakat."}, "ref": {"bn": "সূরা বাকারা ২:৪৩", "en": "Al-Baqarah 2:43"}}, {"type": "text", "text": {"bn": "যাকাত মানে পবিত্রতা ও বৃদ্ধি। নির্দিষ্ট পরিমাণ সম্পদ এক বছর মালিকানায় থাকলে তার একটি নির্ধারিত অংশ (সাধারণত ২.৫%) কুরআনে বর্ণিত হকদারদের দিয়ে দেওয়াই যাকাত। নবী (সা.) বলেছেন, ইসলাম পাঁচটি স্তম্ভের ওপর প্রতিষ্ঠিত, তার একটি যাকাত দেওয়া।", "en": "Zakat means purification and growth. When a set amount of wealth has been owned for a year, a fixed share of it (usually 2.5%) is given to the recipients named in the Quran. The Prophet said Islam is built on five pillars, one of which is giving zakat."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৮; সহিহ মুসলিম ১৬", "en": "Sahih al-Bukhari 8; Sahih Muslim 16"}}, {"type": "arabic", "ar": "خُذْ مِنْ أَمْوَالِهِمْ صَدَقَةً تُطَهِّرُهُمْ وَتُزَكِّيهِمْ بِهَا", "pron": {"bn": "খুয মিন আমওয়ালিহিম সাদাকাতান তুতাহহিরুহুম ওয়া তুযাক্কীহিম বিহা", "en": "Khudh min amwalihim sadaqatan tutahhiruhum wa tuzakkihim biha"}, "meaning": {"bn": "তাদের সম্পদ থেকে সদকা গ্রহণ করো, যা দিয়ে তুমি তাদের পবিত্র ও পরিশুদ্ধ করবে।", "en": "Take from their wealth a charity by which you purify them and cause them to grow."}, "ref": {"bn": "সূরা তাওবা ৯:১০৩", "en": "At-Tawbah 9:103"}}, {"type": "heading", "text": {"bn": "যাকাত ফরজ হওয়ার শর্ত", "en": "Conditions for zakat to be due"}}, {"type": "list", "items": [{"bn": "মুসলিম হওয়া", "en": "Being Muslim"}, {"bn": "নিসাব পরিমাণ যাকাতযোগ্য সম্পদের মালিক হওয়া (নিসাবের বিস্তারিত পরের গাইডে)", "en": "Owning zakatable wealth of at least the nisab (details in the next guide)"}, {"bn": "সম্পদের পূর্ণ মালিকানা থাকা", "en": "Full ownership of the wealth"}, {"bn": "সম্পদ মৌলিক প্রয়োজন (থাকার ঘর, পরিধেয় কাপড়, ব্যবহারের আসবাব, যানবাহন ইত্যাদি) ও আদায়যোগ্য ঋণের অতিরিক্ত হওয়া", "en": "The wealth being beyond basic needs (home, clothes, household items, personal vehicle) and debts due"}, {"bn": "নিসাব পরিমাণ সম্পদের ওপর চান্দ্রবছর (হাওল) পূর্ণ হওয়া", "en": "A full lunar year (hawl) passing on the nisab amount"}, {"bn": "প্রাপ্তবয়স্ক ও সুস্থ মস্তিষ্কের হওয়া (হানাফি মতে)", "en": "Being adult and sane (Hanafi view)"}]}, {"type": "differ", "title": {"bn": "শিশু ও মানসিক প্রতিবন্ধীর সম্পদে যাকাত", "en": "Zakat on the wealth of children and the insane"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "নাবালেগ ও পাগলের সম্পদে যাকাত ফরজ নয় (তবে তাদের জমির ফসলে উশর আছে)।", "en": "No zakat is due on the wealth of a minor or an insane person (though ushr is due on their crops)."}, "evidence": {"bn": "যাকাত একটি ইবাদত, আর তারা ইবাদতের জন্য দায়িত্বপ্রাপ্ত নয়।", "en": "Zakat is an act of worship and they are not legally responsible for worship."}}, {"label": {"bn": "শাফেয়ি, মালেকি, হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "তাদের সম্পদেও যাকাত ফরজ; অভিভাবক আদায় করবেন।", "en": "Zakat is due on their wealth too; the guardian pays it."}, "evidence": {"bn": "যাকাত সম্পদের হক; উমর (রা.) ও আয়েশা (রা.) ইয়াতিমের সম্পদ থেকে যাকাত দিতেন বলে বর্ণিত।", "en": "Zakat is a right on the wealth; Umar and Aishah are reported to have paid zakat from orphans'' wealth."}}]}, {"type": "note", "tone": "warn", "text": {"bn": "যাকাত না দেওয়ার পরিণতি ভয়াবহ। যারা সোনা-রূপা জমিয়ে রাখে আর আল্লাহর পথে খরচ করে না, কুরআনে তাদের যন্ত্রণাদায়ক শাস্তির কথা বলা হয়েছে।", "en": "The consequence of withholding zakat is severe. The Quran warns those who hoard gold and silver and do not spend it in the way of Allah of a painful punishment."}}, {"type": "ref", "text": {"bn": "সূরা তাওবা ৯:৩৪; সূরা তাওবা ৯:৩৫", "en": "At-Tawbah 9:34; At-Tawbah 9:35"}}, {"type": "note", "tone": "tip", "text": {"bn": "এই অ্যাপে একটি যাকাত ক্যালকুলেটর আছে। নিচের গাইডগুলো পড়ে নিয়ম বুঝে নিন, তারপর ক্যালকুলেটরে নিজের সম্পদের হিসাব বসান।", "en": "This app has a zakat calculator. Read these guides to understand the rules, then enter your own figures in the calculator."}}]', 'in_review', 10 FROM is_guide_topics WHERE slug = 'zakat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'af60c109-647d-50a8-9de4-57300a2dd79a', id, 'zakat-nisab-hawl', '{"bn": "নিসাব ও এক বছর (হাওল)", "en": "Nisab and the zakat year (hawl)"}', '{"bn": "কতটুকু সম্পদ থাকলে যাকাত ফরজ হয়, সোনা না রূপার নিসাব ধরবেন, আর বছর কীভাবে গণনা করবেন।", "en": "How much wealth makes zakat due, whether to use the gold or silver nisab, and how the year is counted."}', 'basic', '[{"type": "heading", "text": {"bn": "নিসাব কী", "en": "What is nisab"}}, {"type": "text", "text": {"bn": "নিসাব হলো সম্পদের সেই ন্যূনতম পরিমাণ, যার মালিক হলে যাকাত ফরজ হয়। হাদিসে সোনার নিসাব ২০ দিনার (মিসকাল) এবং রূপার নিসাব ২০০ দিরহাম (৫ উকিয়া) নির্ধারিত হয়েছে।", "en": "Nisab is the minimum amount of wealth that makes zakat due. The hadith sets the nisab of gold at 20 dinars (mithqal) and of silver at 200 dirhams (5 awqiyah)."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৯৭৯", "en": "Sahih Muslim 979"}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ (আলী রা.-এর বর্ণনা: ২০ দিনার ও এক বছর)", "en": "Sunan Abi Dawud (narration of Ali: 20 dinars and one year)"}, "check": true}, {"type": "table", "head": [{"bn": "সম্পদ", "en": "Asset"}, {"bn": "নিসাব (গ্রাম)", "en": "Nisab (grams)"}, {"bn": "ভরি/তোলা হিসাবে", "en": "In bhori/tola"}], "rows": [[{"bn": "সোনা", "en": "Gold"}, {"bn": "প্রায় ৮৫ গ্রাম", "en": "About 85 g"}, {"bn": "সাড়ে ৭ ভরি (প্রায় ৮৭.৪৮ গ্রাম)", "en": "7.5 bhori (about 87.48 g)"}], [{"bn": "রূপা", "en": "Silver"}, {"bn": "প্রায় ৫৯৫ গ্রাম", "en": "About 595 g"}, {"bn": "সাড়ে ৫২ ভরি (প্রায় ৬১২.৩৬ গ্রাম)", "en": "52.5 bhori (about 612.36 g)"}], [{"bn": "নগদ টাকা, ব্যবসায়িক পণ্য ও মিশ্র সম্পদ", "en": "Cash, trade goods and mixed assets"}, {"bn": "সোনা বা রূপার নিসাবের সমমূল্য (নিচের মতভেদ দেখুন)", "en": "The value of the gold or silver nisab (see the difference below)"}, {"bn": "—", "en": "—"}]]}, {"type": "note", "tone": "info", "text": {"bn": "গ্রামের হিসাবে সামান্য পার্থক্য আছে: আন্তর্জাতিকভাবে সাধারণত ৮৫ গ্রাম ও ৫৯৫ গ্রাম ধরা হয়, আর বাংলাদেশ-ভারতে প্রচলিত হিসাব সাড়ে ৭ ভরি ও সাড়ে ৫২ ভরি। যাকাতের তারিখে স্থানীয় বাজারদর দেখে টাকায় নিসাব নির্ণয় করুন।", "en": "The gram figures differ slightly: internationally 85 g and 595 g are common, while the usual reckoning in Bangladesh and India is 7.5 and 52.5 bhori. Work out the nisab in taka from the local market price on your zakat date."}}, {"type": "differ", "title": {"bn": "নগদ ও মিশ্র সম্পদে কোন নিসাব ধরবেন", "en": "Which nisab to use for cash and mixed wealth"}, "views": [{"label": {"bn": "রূপার নিসাব", "en": "Silver nisab"}, "text": {"bn": "টাকা, ব্যবসার পণ্য বা কয়েক ধরনের সম্পদ মিলে রূপার নিসাবের মূল্যে পৌঁছালেই যাকাত ফরজ। হানাফি মাজহাব ও বাংলাদেশের অধিকাংশ মুফতি এ মত দেন। এতে গরিবদের উপকার বেশি এবং সতর্কতাও বেশি।", "en": "Zakat is due once cash, trade goods or a mix of assets reach the value of the silver nisab. This is the Hanafi view and that of most muftis in Bangladesh; it benefits the poor more and is more cautious."}, "evidence": {"bn": "দুটি নিসাবের মধ্যে যেটি গরিবের জন্য বেশি উপকারী সেটিই ধরা উচিত; হানাফি মতে বিভিন্ন সম্পদ মূল্যের ভিত্তিতে একসাথে যোগ হয়।", "en": "Of the two nisabs, the one more beneficial to the poor should be used; Hanafis combine different assets by value."}}, {"label": {"bn": "সোনার নিসাব", "en": "Gold nisab"}, "text": {"bn": "বর্তমানে রূপার দাম অনেক কমে যাওয়ায় সমকালীন অনেক আলেম (যেমন ইউসুফ আল-কারযাভি) বলেন, টাকার নিসাব সোনার মূল্যে ধরা উচিত, যাতে সত্যিকারের সচ্ছল ব্যক্তির ওপরই যাকাত আসে।", "en": "Because silver has lost much of its value, many contemporary scholars (e.g. Yusuf al-Qaradawi) say the cash nisab should be set by gold, so that zakat falls on the genuinely well-off."}, "evidence": {"bn": "নবী (সা.)-এর যুগে ২০ দিনার ও ২০০ দিরহামের মূল্য প্রায় সমান ছিল; এখন সোনা সম্পদের স্থিতিশীল মাপকাঠি।", "en": "In the Prophet''s time 20 dinars and 200 dirhams were roughly equal in value; today gold is the more stable measure of wealth."}}]}, {"type": "note", "tone": "tip", "text": {"bn": "শুধু সোনা থাকলে (অন্য কোনো যাকাতযোগ্য সম্পদ, এমনকি সামান্য নগদও নেই) তাহলে সোনার নিসাবই প্রযোজ্য। কিন্তু সোনার সাথে কিছু নগদ টাকা বা রূপা থাকলেই হানাফি মতে সব মিলিয়ে রূপার নিসাবে হিসাব হবে।", "en": "If you own only gold (no other zakatable asset, not even a little cash), the gold nisab applies. But in the Hanafi view, once there is some cash or silver with the gold, everything is combined and measured against the silver nisab."}}, {"type": "heading", "text": {"bn": "এক বছর (হাওল)", "en": "The year (hawl)"}}, {"type": "list", "items": [{"bn": "যেদিন প্রথম নিসাব পরিমাণ সম্পদের মালিক হয়েছেন, চান্দ্রমাসের সেই তারিখই আপনার যাকাতের তারিখ। পরের বছর ওই তারিখে হিসাব করবেন।", "en": "The lunar date on which you first owned the nisab is your zakat date; calculate on that date each following year."}, {"bn": "যাকাতের বছর চান্দ্রবছর (হিজরি)। ইংরেজি বছর ধরে হিসাব করলে অনেক আলেম ২.৫%-এর বদলে প্রায় ২.৫৭৭% দিতে বলেন।", "en": "The zakat year is lunar (Hijri). If you calculate on the solar year, many scholars advise about 2.577% instead of 2.5%."}, {"bn": "ফসল, ফল ও খনিজে বছর লাগে না; তোলার সময়ই দিতে হয়।", "en": "Crops, fruit and minerals need no year; their due is paid at harvest."}]}, {"type": "differ", "title": {"bn": "বছরের মাঝে সম্পদ কমে গেলে বা নতুন আয় হলে", "en": "When wealth drops or new income arrives during the year"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "বছরের শুরু ও শেষে নিসাব পূর্ণ থাকলেই যথেষ্ট; মাঝে কমে গেলেও (একেবারে শূন্য না হলে) ক্ষতি নেই। বছরের মাঝে যে নতুন টাকা আসে (বেতন, লাভ, উপহার), তার জন্য আলাদা বছর লাগে না; যাকাতের তারিখে যা আছে, সবকিছুর যাকাত দেবেন।", "en": "It is enough that the nisab is complete at the start and end of the year; dropping below it in between does not matter (unless it falls to nothing). New money during the year (salary, profit, gifts) needs no separate year; pay on everything you hold on the zakat date."}, "evidence": {"bn": "প্রতিটি আয়ের আলাদা বছর হিসাব করা মানুষের জন্য কঠিন; একই জাতের সম্পদ মূল সম্পদের সঙ্গে যুক্ত হয়।", "en": "Tracking a separate year for every receipt would be a hardship; wealth of the same kind joins the original holding."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "পুরো বছর জুড়ে নিসাব থাকতে হবে; মাঝে নিসাবের নিচে নামলে নতুন করে বছর শুরু। নতুন আয়ের প্রতিটির জন্য আলাদা বছর গণনা হবে (ব্যবসার লাভ ছাড়া), তবে সহজতার জন্য আগেভাগে সবটার যাকাত দিয়ে দেওয়া যায়।", "en": "The nisab must be held throughout the year; if it falls below, the year restarts. Each new receipt has its own year (except trading profit), though one may pay on everything early for simplicity."}, "evidence": {"bn": "হাদিস: ''বছর পূর্ণ না হওয়া পর্যন্ত কোনো সম্পদে যাকাত নেই।''", "en": "Hadith: ''No zakat is due on wealth until a year has passed over it.''"}}]}, {"type": "note", "tone": "tip", "text": {"bn": "বছর পূর্ণ হওয়ার আগে অগ্রিম যাকাত দেওয়া হানাফি, শাফেয়ি ও হাম্বলি মতে জায়েজ; নবী (সা.) আব্বাস (রা.)-এর কাছ থেকে অগ্রিম যাকাত নিয়েছিলেন বলে বর্ণিত।", "en": "Paying zakat in advance before the year ends is allowed by the Hanafi, Shafi''i and Hanbali schools; the Prophet is reported to have accepted Abbas''s zakat in advance."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ; জামে তিরমিজি (আব্বাস রা.-এর অগ্রিম যাকাত)", "en": "Sunan Abi Dawud; Jami'' at-Tirmidhi (Abbas paying zakat in advance)"}, "check": true}]', 'in_review', 20 FROM is_guide_topics WHERE slug = 'zakat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '2e39a327-58bb-5551-b19e-0590ce80832a', id, 'zakat-assets', '{"bn": "কোন কোন সম্পদে যাকাত", "en": "Which assets are zakatable"}', '{"bn": "নগদ টাকা, সোনা-রূপা, ব্যবসার পণ্য, শেয়ার, পাওনা টাকা, ফসলের উশর ও গবাদিপশু; আর কোন সম্পদে যাকাত নেই।", "en": "Cash, gold and silver, trade goods, shares, money owed to you, ushr on crops and livestock; and what is not zakatable."}', 'detail', '[{"type": "heading", "text": {"bn": "নগদ টাকা ও সঞ্চয়", "en": "Cash and savings"}}, {"type": "text", "text": {"bn": "হাতের নগদ, ব্যাংক হিসাব, মোবাইল ব্যাংকিং, এফডিআর, সঞ্চয়পত্র, বিদেশি মুদ্রা, ডিপিএস-এ জমা টাকা — সবই যাকাতের হিসাবে আসবে। সুদ বা অবৈধ আয়ের টাকা যাকাতের অংশ নয়; সেটি সওয়াবের নিয়ত ছাড়া পুরোটাই গরিবকে দিয়ে দিতে হবে।", "en": "Cash in hand, bank accounts, mobile wallets, fixed deposits, savings certificates, foreign currency and deposit schemes all count. Interest or unlawful income is not part of zakat; all of it must be given away to the poor without expecting reward."}}, {"type": "heading", "text": {"bn": "সোনা ও রূপা", "en": "Gold and silver"}}, {"type": "text", "text": {"bn": "সোনা-রূপার গয়না, বার বা কয়েনের যাকাত দিতে হবে যাকাতের তারিখের বাজারদর (বিক্রয়মূল্য) অনুযায়ী। পাথর বা অন্য ধাতু বাদ দিয়ে শুধু সোনা-রূপার ওজন ধরবেন। হীরা, মুক্তা বা প্ল্যাটিনামের গয়না ব্যক্তিগত ব্যবহারের হলে যাকাত নেই; ব্যবসার জন্য হলে আছে।", "en": "Gold and silver jewellery, bars and coins are zakatable at the market (sale) value on the zakat date. Count only the gold or silver weight, excluding stones and other metals. Diamond, pearl or platinum jewellery for personal use is not zakatable; if held for trade, it is."}}, {"type": "differ", "title": {"bn": "ব্যবহারের গয়নায় যাকাত", "en": "Zakat on jewellery that is worn"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "নারীর ব্যবহারের সোনা-রূপার গয়নাতেও যাকাত ফরজ।", "en": "Zakat is due even on gold and silver jewellery a woman wears."}, "evidence": {"bn": "এক নারীর মেয়ের হাতে সোনার মোটা কাঁকন দেখে নবী (সা.) জিজ্ঞেস করেন তার যাকাত দেওয়া হয় কি না (আবু দাউদ); এবং সোনা-রূপা জমানোর আয়াতের ব্যাপকতা।", "en": "The Prophet, seeing thick gold bangles on a woman''s daughter, asked whether their zakat was paid (Abu Dawud); and the general verse on hoarding gold and silver."}}, {"label": {"bn": "শাফেয়ি, মালেকি, হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "স্বাভাবিক পরিমাণে ব্যবহারের জন্য রাখা জায়েজ গয়নায় যাকাত নেই; সঞ্চয় বা বিনিয়োগের জন্য রাখা গয়নায় আছে।", "en": "No zakat on lawful jewellery kept in normal amounts for wearing; jewellery kept as savings or investment is zakatable."}, "evidence": {"bn": "আয়েশা (রা.), জাবির (রা.), ইবনে উমর (রা.)সহ কয়েকজন সাহাবির আমল: তারা পরিবারের ব্যবহারের গয়নার যাকাত দিতেন না।", "en": "The practice of Companions such as Aishah, Jabir and Ibn Umar, who did not pay zakat on the jewellery their families wore."}}], "check": true}, {"type": "heading", "text": {"bn": "ব্যবসার পণ্য", "en": "Trade goods"}}, {"type": "text", "text": {"bn": "বিক্রির উদ্দেশ্যে রাখা সব পণ্য (দোকানের মাল, গুদামের স্টক, বিক্রির জন্য কেনা জমি বা ফ্ল্যাট) যাকাতের তারিখের বাজারদরে হিসাব করে যাকাত দেবেন। দোকানঘর, আসবাব, মেশিন ও গাড়ির মতো স্থায়ী সম্পদে যাকাত নেই, তবে সেগুলো থেকে আসা আয় জমা থাকলে তাতে আছে।", "en": "All goods held for sale (shop stock, warehouse inventory, land or flats bought to resell) are valued at the market price on the zakat date. Fixed assets such as the shop premises, furniture, machines and vehicles are not zakatable, though the income from them is once saved."}}, {"type": "heading", "text": {"bn": "শেয়ার ও বিনিয়োগ", "en": "Shares and investments"}}, {"type": "differ", "title": {"bn": "শেয়ারের যাকাত", "en": "Zakat on shares"}, "views": [{"label": {"bn": "কেনাবেচার জন্য রাখা শেয়ার", "en": "Shares held for trading"}, "text": {"bn": "দাম বাড়লে বিক্রির উদ্দেশ্যে কেনা শেয়ার ব্যবসার পণ্যের মতো; যাকাতের তারিখে পুরো বাজারমূল্যের ২.৫% দিতে হবে। এ বিষয়ে সমকালীন আলেমরা প্রায় একমত।", "en": "Shares bought to sell at a profit are like trade goods: 2.5% of the full market value on the zakat date. Contemporary scholars broadly agree on this."}, "evidence": {"bn": "ব্যবসার পণ্যে যাকাতের সাধারণ বিধান।", "en": "The general ruling on trade goods."}}, {"label": {"bn": "দীর্ঘমেয়াদি বিনিয়োগ (লভ্যাংশের জন্য)", "en": "Long-term investment (for dividends)"}, "text": {"bn": "এক মত: কোম্পানির নগদ, পাওনা ও পণ্যের মতো যাকাতযোগ্য সম্পদে আপনার অংশ হিসাব করে তার যাকাত দেবেন (জানা না গেলে বাজারমূল্যের ওপর দেওয়াই সতর্কতা)। আরেক মত: পুরো বাজারমূল্যের ওপরই যাকাত। লভ্যাংশ হাতে এলে তা নগদের সঙ্গে যোগ হবে।", "en": "One view: pay on your share of the company''s zakatable assets (cash, receivables, inventory); if that is unknown, paying on market value is the safe course. Another view: pay on the full market value. Dividends received join your cash."}, "evidence": {"bn": "শেয়ার কোম্পানির সম্পদের মালিকানার অংশ; স্থায়ী সম্পদে যাকাত নেই — ইসলামিক ফিকহ একাডেমির মতো সংস্থার আলোচনা।", "en": "A share is part-ownership of the company''s assets, and fixed assets are not zakatable — as discussed by bodies such as the Islamic Fiqh Academy."}}]}, {"type": "heading", "text": {"bn": "পাওনা টাকা ও ঋণ", "en": "Money owed to you and your debts"}}, {"type": "list", "items": [{"bn": "যে পাওনা ফেরত পাওয়ার আশা আছে, তার যাকাতও দিতে হবে; প্রতি বছর দিয়ে দেওয়া সহজ। হানাফি মতে চাইলে টাকা হাতে পাওয়ার পর বিগত বছরগুলোর যাকাত একসাথে দেওয়া যায়।", "en": "Money owed to you that you expect to recover is zakatable; paying each year is simplest. Hanafis allow paying for the past years together once it is received."}, {"bn": "যে পাওনা ফেরত পাওয়ার আশা নেই, তাতে যাকাত নেই; পরে পেলে হানাফি মতে পাওয়ার পর থেকে হিসাব।", "en": "Money you do not expect to recover is not zakatable; if later recovered, Hanafis count from receipt."}, {"bn": "আপনার নিজের যে ঋণ এখন পরিশোধ করতে হবে (বা এ বছরের কিস্তি), হানাফি ও হাম্বলি মতে তা বাদ দিয়ে হিসাব করবেন; দীর্ঘমেয়াদি ঋণের পুরোটা একবারে বাদ দেওয়া যায় না। শাফেয়ি মতে ঋণ বাদ যায় না।", "en": "Debts you must pay now (or this year''s instalments) are deducted in the Hanafi and Hanbali view; the whole of a long-term loan is not deducted at once. Shafi''is do not deduct debts."}, {"bn": "প্রভিডেন্ট ফান্ড: যে অংশ এখনও তোলার অধিকার নেই, অনেক আলেমের মতে তা হাতে পাওয়ার পর থেকে হিসাব হবে; স্বেচ্ছায় জমা অংশ ও তোলার অধিকার আছে এমন অংশে যাকাত দেওয়াই সতর্কতা।", "en": "Provident fund: many scholars say the part you cannot yet withdraw is counted from when you receive it; voluntary contributions and withdrawable balances should be included to be safe."}]}, {"type": "heading", "text": {"bn": "যেসব সম্পদে যাকাত নেই", "en": "What is not zakatable"}}, {"type": "list", "items": [{"bn": "বসবাসের বাড়ি, ব্যবহারের গাড়ি, আসবাব, পোশাক ও গৃহস্থালি জিনিস", "en": "The home you live in, personal car, furniture, clothes and household goods"}, {"bn": "ভাড়া দেওয়া বাড়ি-দোকান (তবে ভাড়ার জমানো টাকায় যাকাত আছে)", "en": "Property rented out (but saved rental income is zakatable)"}, {"bn": "নিজে বাড়ি করার জন্য কেনা জমি (বিক্রির নিয়তে কিনলে যাকাত আছে)", "en": "Land bought to build your own home (land bought to resell is zakatable)"}, {"bn": "পেশার যন্ত্রপাতি ও কাজের বই", "en": "Tools of one''s trade and working books"}]}, {"type": "heading", "text": {"bn": "ফসলের যাকাত (উশর)", "en": "Zakat on crops (ushr)"}}, {"type": "text", "text": {"bn": "বৃষ্টি বা প্রাকৃতিক পানিতে উৎপন্ন ফসলে উৎপাদনের ১০% (উশর), আর সেচ দিয়ে উৎপন্ন ফসলে ৫% (নিসফে উশর) দিতে হয়। এতে বছর পূর্ণ হওয়া লাগে না; ফসল তোলার সময়ই দেবেন।", "en": "Crops watered by rain or natural sources owe 10% of the harvest (ushr); crops watered by irrigation owe 5%. No year is needed; it is paid at harvest."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৪৮৩", "en": "Sahih al-Bukhari 1483"}}, {"type": "differ", "title": {"bn": "উশরের নিসাব", "en": "Nisab for ushr"}, "views": [{"label": {"bn": "ইমাম আবু হানিফা", "en": "Imam Abu Hanifa"}, "text": {"bn": "কম-বেশি যে পরিমাণ ফসলই হোক, উশর দিতে হবে; কোনো নিসাব নেই।", "en": "Ushr is due on any amount of produce, however small; there is no nisab."}, "evidence": {"bn": "''যা বৃষ্টিতে সিক্ত হয় তাতে উশর'' হাদিসটি ব্যাপক, পরিমাণের শর্ত নেই।", "en": "The hadith ''what is watered by rain owes a tenth'' is general, with no minimum."}}, {"label": {"bn": "অধিকাংশ আলেম (আবু ইউসুফ, মুহাম্মদসহ)", "en": "Majority (incl. Abu Yusuf and Muhammad)"}, "text": {"bn": "পাঁচ ওয়াসাক (প্রায় ৬৫০ কেজি) বা তার বেশি সংরক্ষণযোগ্য শস্য হলেই উশর।", "en": "Ushr is due only once storable grain reaches five awsuq (about 650 kg)."}, "evidence": {"bn": "হাদিস: ''পাঁচ ওয়াসাকের কম শস্যে সদকা নেই।''", "en": "Hadith: ''There is no charity on less than five awsuq.''"}}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৯৭৯", "en": "Sahih Muslim 979"}}, {"type": "heading", "text": {"bn": "গবাদিপশু (সংক্ষেপে)", "en": "Livestock (briefly)"}}, {"type": "text", "text": {"bn": "যে গরু, মহিষ, উট, ছাগল ও ভেড়া বছরের বেশির ভাগ সময় মুক্ত চারণভূমিতে চরে খায় (সায়িমা), তাতে যাকাত আছে। যেমন: ৪০–১২০টি ছাগল/ভেড়ায় ১টি; ৩০টি গরু/মহিষে এক বছর বয়সী ১টি বাছুর, ৪০টিতে দুই বছর বয়সী ১টি; ৫টি উটে ১টি ছাগল। খামারে কিনে খাওয়ানো পশু ব্যবসার জন্য হলে ব্যবসার পণ্য হিসেবে মূল্যের ২.৫% দিতে হবে।", "en": "Cattle, buffalo, camels, goats and sheep that graze freely for most of the year (sa''imah) owe zakat. For example: 1 for 40–120 goats/sheep; a one-year calf for 30 cattle and a two-year one for 40; a goat for 5 camels. Farm animals fed on bought fodder and raised for sale are trade goods at 2.5% of value."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি (আবু বকর রা.-এর যাকাত-পত্র); সুনান আবু দাউদ (মুয়াজ রা.-এর বর্ণনা)", "en": "Sahih al-Bukhari (Abu Bakr''s letter on zakat); Sunan Abi Dawud (narration of Mu''adh)"}, "check": true}, {"type": "note", "tone": "info", "text": {"bn": "পশুর যাকাতের পূর্ণ তালিকা দীর্ঘ; এমন খামার থাকলে নির্ভরযোগ্য আলেমের কাছ থেকে বিস্তারিত জেনে নিন।", "en": "The full livestock tables are long; if you own such herds, get the details from a reliable scholar."}}]', 'in_review', 30 FROM is_guide_topics WHERE slug = 'zakat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '2a51f1ae-181b-5481-b2d8-b4c41f536007', id, 'zakat-calculation', '{"bn": "যাকাত হিসাব করার নিয়ম", "en": "How to calculate zakat"}', '{"bn": "ধাপে ধাপে যাকাতের হিসাব এবং টাকায় একটি উদাহরণ।", "en": "Step-by-step zakat calculation with a worked example in taka."}', 'basic', '[{"type": "step", "title": {"bn": "যাকাতের তারিখ ঠিক করুন", "en": "Fix your zakat date"}, "text": {"bn": "যে হিজরি তারিখে প্রথম নিসাবের মালিক হয়েছিলেন, সেটিই আপনার যাকাতের তারিখ। মনে না থাকলে আনুমানিক একটি তারিখ (যেমন রমজানের কোনো দিন) ঠিক করে প্রতি বছর সেদিন হিসাব করুন।", "en": "Your zakat date is the Hijri date you first owned the nisab. If you do not remember, fix a reasonable date (e.g. a day in Ramadan) and calculate on it every year."}}, {"type": "step", "title": {"bn": "যাকাতযোগ্য সম্পদ যোগ করুন", "en": "Add up zakatable assets"}, "text": {"bn": "ওই দিনের হিসাবে নগদ, ব্যাংক, সঞ্চয়, সোনা-রূপার বাজারমূল্য, ব্যবসার পণ্যের মূল্য, শেয়ার ও ফেরতযোগ্য পাওনা যোগ করুন।", "en": "On that date add cash, bank balances, savings, the market value of gold and silver, the value of trade stock, shares and recoverable money owed to you."}}, {"type": "step", "title": {"bn": "আদায়যোগ্য ঋণ বাদ দিন", "en": "Deduct debts now due"}, "text": {"bn": "এখন পরিশোধ করতে হবে এমন ঋণ, বকেয়া বিল ও এ বছরের কিস্তি বাদ দিন (হানাফি মত)।", "en": "Deduct debts you must pay now, unpaid bills and this year''s instalments (Hanafi view)."}}, {"type": "step", "title": {"bn": "নিসাবের সাথে মিলান", "en": "Compare with the nisab"}, "text": {"bn": "বাকি অঙ্ক যদি নিসাবের মূল্যের (আজকের দামে) সমান বা বেশি হয়, তাহলে যাকাত ফরজ।", "en": "If what remains is equal to or above the nisab value (at today''s price), zakat is due."}}, {"type": "step", "title": {"bn": "২.৫% বের করুন", "en": "Take 2.5%"}, "text": {"bn": "নিট সম্পদকে ৪০ দিয়ে ভাগ করুন, অথবা ২.৫% হিসাব করুন। যাকাত নিসাবের ওপরের অংশে নয়, পুরো নিট সম্পদের ওপর।", "en": "Divide net wealth by 40, i.e. take 2.5%. Zakat is on the whole net amount, not only the part above the nisab."}}, {"type": "step", "title": {"bn": "নিয়ত করে আদায় করুন", "en": "Pay with intention"}, "text": {"bn": "যাকাতের নিয়তে (মনে মনে) হকদারকে দিন। প্রাপককে ''যাকাত'' বলে জানানো জরুরি নয়। হিসাব লিখে রাখুন।", "en": "Give it to eligible recipients with the intention of zakat in your heart. You need not tell the recipient it is zakat. Keep a record."}}, {"type": "heading", "text": {"bn": "উদাহরণ", "en": "Worked example"}}, {"type": "text", "text": {"bn": "রহিম সাহেবের যাকাতের তারিখে সম্পদ নিচের মতো। (দামগুলো শুধু উদাহরণের জন্য; আসল হিসাবে সেদিনের বাজারদর বসাবেন।)", "en": "Mr Rahim''s assets on his zakat date are below. (Values are only for illustration; use the actual market prices on your date.)"}}, {"type": "table", "head": [{"bn": "খাত", "en": "Item"}, {"bn": "টাকা", "en": "Taka"}], "rows": [[{"bn": "হাতে ও ব্যাংকে নগদ", "en": "Cash in hand and bank"}, {"bn": "১,৫০,০০০", "en": "150,000"}], [{"bn": "সঞ্চয়পত্র ও এফডিআর", "en": "Savings certificates and FDR"}, {"bn": "২,০০,০০০", "en": "200,000"}], [{"bn": "স্ত্রীর গয়নার সোনা, সেদিনের বিক্রয়মূল্যে (ধরা যাক; মালিক স্ত্রী হলে হিসাব তার নামে হবে)", "en": "Gold jewellery at sale value that day (assumed; if it belongs to his wife, it is counted in her name)"}, {"bn": "৪,০০,০০০", "en": "400,000"}], [{"bn": "দোকানের বিক্রয়যোগ্য মাল", "en": "Shop stock for sale"}, {"bn": "৩,০০,০০০", "en": "300,000"}], [{"bn": "ফেরত পাওয়ার আশা আছে এমন পাওনা", "en": "Money owed to him, expected back"}, {"bn": "৫০,০০০", "en": "50,000"}], [{"bn": "মোট যাকাতযোগ্য সম্পদ", "en": "Total zakatable assets"}, {"bn": "১১,০০,০০০", "en": "1,100,000"}], [{"bn": "বাদ: এখন পরিশোধযোগ্য ঋণ ও এ বছরের কিস্তি", "en": "Less: debts and instalments due now"}, {"bn": "− ১,০০,০০০", "en": "− 100,000"}], [{"bn": "বাদ: বকেয়া বিল", "en": "Less: unpaid bills"}, {"bn": "− ২০,০০০", "en": "− 20,000"}], [{"bn": "নিট যাকাতযোগ্য সম্পদ", "en": "Net zakatable wealth"}, {"bn": "৯,৮০,০০০", "en": "980,000"}], [{"bn": "যাকাত (৯,৮০,০০০ × ২.৫%)", "en": "Zakat (980,000 × 2.5%)"}, {"bn": "২৪,৫০০", "en": "24,500"}]]}, {"type": "text", "text": {"bn": "নিট সম্পদ ৯,৮০,০০০ টাকা যদি সেদিনের নিসাবের মূল্যের চেয়ে বেশি হয় (রূপার নিসাবে সাধারণত হবে), তাহলে রহিম সাহেবের যাকাত ২৪,৫০০ টাকা।", "en": "If the net 980,000 taka is above that day''s nisab value (with the silver nisab it usually will be), Mr Rahim''s zakat is 24,500 taka."}}, {"type": "note", "tone": "info", "text": {"bn": "গয়না যার মালিকানায়, যাকাত তারই। স্ত্রীর গয়না স্ত্রীর সম্পদ; স্বামী চাইলে তার পক্ষ থেকে (তার অনুমতিতে) দিয়ে দিতে পারেন।", "en": "Zakat is on whoever owns the jewellery. A wife''s jewellery is her wealth; the husband may pay it for her with her permission."}}, {"type": "note", "tone": "tip", "text": {"bn": "এই অ্যাপের যাকাত ক্যালকুলেটরে খাতগুলো আলাদা করে বসালে হিসাব সহজ হবে। ক্যালকুলেটরের ফল একটি সহায়ক হিসাব; জটিল ব্যবসা বা সম্পদের ক্ষেত্রে আলেমের পরামর্শ নিন।", "en": "Entering each item separately in this app''s zakat calculator makes it easy. The calculator gives a helpful estimate; for complex businesses or holdings, consult a scholar."}}]', 'in_review', 40 FROM is_guide_topics WHERE slug = 'zakat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'f4f40b12-938a-54a9-ae1c-f90075105432', id, 'zakat-recipients', '{"bn": "যাকাত কাকে দেবেন, কাকে দেবেন না", "en": "Who receives zakat and who cannot"}', '{"bn": "কুরআনে বর্ণিত যাকাতের আট খাত এবং যাদের যাকাত দেওয়া যায় না।", "en": "The eight categories of zakat recipients in the Quran, and those who may not receive it."}', 'basic', '[{"type": "arabic", "label": {"bn": "যাকাতের আট খাত", "en": "The eight categories"}, "ar": "إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَابْنِ السَّبِيلِ ۖ فَرِيضَةً مِنَ اللَّهِ ۗ وَاللَّهُ عَلِيمٌ حَكِيمٌ", "pron": {"bn": "ইন্নামাস সাদাকাতু লিল ফুকারাই ওয়াল মাসাকীনি ওয়াল আমিলীনা আলাইহা ওয়াল মুআল্লাফাতি কুলূবুহুম ওয়া ফির রিকাবি ওয়াল গারিমীনা ওয়া ফী সাবীলিল্লাহি ওয়াবনিস সাবীল, ফারীদাতাম মিনাল্লাহ, ওয়াল্লাহু আলীমুন হাকীম", "en": "Innamas-sadaqatu lil-fuqara''i wal-masakini wal-''amilina ''alayha wal-mu''allafati qulubuhum wa fir-riqabi wal-gharimina wa fi sabilillahi wabnis-sabil, faridatam minallah, wallahu ''alimun hakim"}, "meaning": {"bn": "সদকা (যাকাত) কেবল ফকির, মিসকিন, যাকাত আদায়ের কাজে নিযুক্ত কর্মী, যাদের মন জয় করা উদ্দেশ্য, দাসমুক্তি, ঋণগ্রস্ত, আল্লাহর পথে এবং মুসাফিরের জন্য। এটা আল্লাহর নির্ধারিত বিধান; আল্লাহ সর্বজ্ঞ, প্রজ্ঞাময়।", "en": "Zakat is only for the poor, the needy, those employed to administer it, those whose hearts are to be reconciled, freeing captives, those in debt, in the cause of Allah, and the stranded traveller: an obligation from Allah. Allah is All-Knowing, All-Wise."}, "ref": {"bn": "সূরা তাওবা ৯:৬০", "en": "At-Tawbah 9:60"}}, {"type": "table", "head": [{"bn": "খাত", "en": "Category"}, {"bn": "কারা", "en": "Who they are"}], "rows": [[{"bn": "ফকির", "en": "Al-fuqara'' (the poor)"}, {"bn": "যার নিসাব পরিমাণ সম্পদ নেই; প্রয়োজনের চেয়ে অনেক কম আছে", "en": "Those without nisab-level wealth, having far less than their needs"}], [{"bn": "মিসকিন", "en": "Al-masakin (the needy)"}, {"bn": "যার কিছুই নেই বা যা আছে তাতে চলে না (দুটির পার্থক্য নিয়ে মতভেদ আছে, তবে দুজনই হকদার)", "en": "Those with nothing or not enough to live on (the exact difference is debated; both are eligible)"}], [{"bn": "আমিলিন", "en": "Al-''amilin (zakat workers)"}, {"bn": "সরকার বা প্রতিষ্ঠানের পক্ষ থেকে যাকাত সংগ্রহ ও বণ্টনের দায়িত্বপ্রাপ্ত কর্মী, ধনী হলেও পারিশ্রমিক হিসেবে", "en": "Those appointed by the state or an institution to collect and distribute zakat, paid even if wealthy"}], [{"bn": "মুআল্লাফাতুল কুলূব", "en": "Mu''allafat al-qulub"}, {"bn": "ইসলামের প্রতি মন আকৃষ্ট করা বা নওমুসলিমকে দৃঢ় করা যাদের উদ্দেশ্য (হানাফি মতে এ খাতটি এখন প্রযোজ্য নয়; অন্যরা প্রয়োজনে প্রযোজ্য বলেন)", "en": "Those whose hearts are to be won or new Muslims to be strengthened (Hanafis hold this no longer applies; others say it applies when needed)"}], [{"bn": "রিকাব", "en": "Ar-riqab (captives)"}, {"bn": "দাস বা বন্দিকে মুক্ত করা", "en": "Freeing slaves or captives"}], [{"bn": "গারিমিন", "en": "Al-gharimin (debtors)"}, {"bn": "বৈধ প্রয়োজনে ঋণগ্রস্ত, যে ঋণ শোধ করতে অক্ষম", "en": "Those in debt for a lawful need who cannot repay"}], [{"bn": "ফী সাবীলিল্লাহ", "en": "Fi sabilillah"}, {"bn": "আল্লাহর পথে: হানাফি মতে আল্লাহর পথে নিয়োজিত অভাবী ব্যক্তি (যেমন অভাবী দ্বীনি ছাত্র); এর পরিধি নিয়ে আলেমদের মতভেদ আছে", "en": "In Allah''s cause: for Hanafis, needy people engaged in it (e.g. poor students of religious knowledge); its scope is debated"}], [{"bn": "ইবনুস সাবীল", "en": "Ibn as-sabil"}, {"bn": "সফরে গিয়ে অর্থসংকটে পড়া মুসাফির, বাড়িতে ধনী হলেও", "en": "A traveller stranded without funds, even if wealthy at home"}]]}, {"type": "note", "tone": "tip", "text": {"bn": "নিকটাত্মীয়দের মধ্যে যারা হকদার (ভাই-বোন, চাচা-মামা, খালা-ফুফু ইত্যাদি), তাদের দেওয়া উত্তম; এতে যাকাত ও আত্মীয়তার হক দুটোই আদায় হয়।", "en": "It is best to give to eligible relatives (siblings, uncles, aunts, etc.); it fulfils both zakat and the rights of kinship."}}, {"type": "heading", "text": {"bn": "যাদের যাকাত দেওয়া যায় না", "en": "Those who cannot receive zakat"}}, {"type": "list", "items": [{"bn": "নিজের মা-বাবা, দাদা-দাদি, নানা-নানি (ঊর্ধ্বতন)", "en": "One''s own parents and grandparents (ascendants)"}, {"bn": "নিজের সন্তান, নাতি-নাতনি (অধস্তন)", "en": "One''s own children and grandchildren (descendants)"}, {"bn": "নিজের স্ত্রী (স্বামী স্ত্রীকে যাকাত দিতে পারেন না)", "en": "One''s own wife (a husband cannot give zakat to his wife)"}, {"bn": "নিসাব পরিমাণ সম্পদের মালিক ধনী ব্যক্তি", "en": "A wealthy person who owns nisab"}, {"bn": "নবী (সা.)-এর বংশধর বনু হাশিম", "en": "The Prophet''s family, Banu Hashim"}, {"bn": "অমুসলিমকে ফরজ যাকাত দেওয়া যায় না (নফল সদকা দেওয়া যায়)", "en": "Non-Muslims cannot receive obligatory zakat (they may receive voluntary charity)"}, {"bn": "হানাফি মতে যাকাতে কোনো ব্যক্তিকে মালিক বানিয়ে দিতে হয়; তাই সরাসরি মসজিদ নির্মাণ, রাস্তা তৈরি বা মৃতের কাফনে যাকাতের টাকা খরচ করা যায় না", "en": "Hanafis require zakat to be handed into a person''s ownership, so it cannot be spent directly on building masjids, roads or shrouding the dead"}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১০৭২", "en": "Sahih Muslim 1072"}}, {"type": "differ", "title": {"bn": "স্ত্রী কি স্বামীকে যাকাত দিতে পারবেন", "en": "Can a wife give zakat to her husband"}, "views": [{"label": {"bn": "ইমাম আবু হানিফা", "en": "Imam Abu Hanifa"}, "text": {"bn": "না; স্বামী-স্ত্রীর সম্পদ ও উপকার পরস্পর জড়িত, তাই যাকাত নিজের কাছেই ফিরে আসে।", "en": "No; spouses share benefit from each other''s wealth, so the zakat effectively returns to the giver."}, "evidence": {"bn": "মা-বাবা ও সন্তানের ক্ষেত্রে নিষেধের ওপর কিয়াস।", "en": "Analogy with the prohibition for parents and children."}}, {"label": {"bn": "শাফেয়ি, হাম্বলি (এক বর্ণনা), আবু ইউসুফ ও মুহাম্মদ", "en": "Shafi''i, Hanbali (one report), Abu Yusuf and Muhammad"}, "text": {"bn": "হ্যাঁ, স্বামী হকদার হলে স্ত্রী তাকে যাকাত দিতে পারেন।", "en": "Yes, a wife may give her zakat to her husband if he is eligible."}, "evidence": {"bn": "ইবনে মাসউদ (রা.)-এর স্ত্রী জয়নব (রা.) স্বামী ও ইয়াতিমদের দান করা সম্পর্কে জিজ্ঞেস করলে নবী (সা.) বলেন, তার জন্য দুটি সওয়াব: আত্মীয়তার ও সদকার (সহিহ বুখারি)।", "en": "When Zaynab, wife of Ibn Mas''ud, asked about giving to her husband and orphans, the Prophet said she would have two rewards, for kinship and for charity (Sahih al-Bukhari)."}}], "check": true}, {"type": "note", "tone": "info", "text": {"bn": "ভালোভাবে খোঁজ নিয়ে যাকে হকদার মনে করে দিয়েছেন, পরে সে ধনী প্রমাণিত হলেও হানাফি মতে যাকাত আদায় হয়ে যাবে।", "en": "If you gave to someone after reasonable checking and they later turn out to be wealthy, in the Hanafi view the zakat is still valid."}}]', 'in_review', 50 FROM is_guide_topics WHERE slug = 'zakat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'af354431-da57-5509-8cec-3f3319423958', id, 'zakat-sadaqah', '{"bn": "সদকা ও তার ফজিলত", "en": "Sadaqah and its virtues"}', '{"bn": "ফরজ যাকাতের বাইরে নফল দান, সদকায়ে জারিয়া এবং দানের আদব।", "en": "Voluntary charity beyond zakat, ongoing charity, and the manners of giving."}', 'basic', '[{"type": "arabic", "ar": "مَثَلُ الَّذِينَ يُنْفِقُونَ أَمْوَالَهُمْ فِي سَبِيلِ اللَّهِ كَمَثَلِ حَبَّةٍ أَنْبَتَتْ سَبْعَ سَنَابِلَ فِي كُلِّ سُنْبُلَةٍ مِائَةُ حَبَّةٍ", "pron": {"bn": "মাসালুল্লাযীনা ইউনফিকূনা আমওয়ালাহুম ফী সাবীলিল্লাহি কামাসালি হাব্বাতিন আমবাতাত সাবআ সানাবিলা ফী কুল্লি সুমবুলাতিম মিআতু হাব্বাহ", "en": "Mathalul-ladhina yunfiquna amwalahum fi sabilillahi kamathali habbatin ambatat sab''a sanabila fi kulli sumbulatim mi''atu habbah"}, "meaning": {"bn": "যারা আল্লাহর পথে সম্পদ ব্যয় করে, তাদের উপমা একটি শস্যদানার মতো, যা থেকে সাতটি শীষ জন্মায়, প্রতিটি শীষে একশ দানা।", "en": "The example of those who spend their wealth in the way of Allah is that of a grain that grows seven ears, in each ear a hundred grains."}, "ref": {"bn": "সূরা বাকারা ২:২৬১", "en": "Al-Baqarah 2:261"}}, {"type": "heading", "text": {"bn": "সদকার কিছু ফজিলত", "en": "Some virtues of charity"}}, {"type": "list", "items": [{"bn": "সদকা সম্পদ কমায় না।", "en": "Charity does not decrease wealth."}, {"bn": "অর্ধেক খেজুর দিয়ে হলেও জাহান্নাম থেকে বাঁচো।", "en": "Protect yourself from the Fire, even with half a date."}, {"bn": "আল্লাহ হালাল উপার্জনের দান গ্রহণ করেন এবং তা বাড়িয়ে পাহাড়সম করে দেন।", "en": "Allah accepts charity from lawful earnings and grows it until it becomes like a mountain."}, {"bn": "যে এত গোপনে দান করে যে ডান হাত কী দিল বাম হাত জানে না, সে কিয়ামতের দিন আল্লাহর আরশের ছায়া পাবে।", "en": "One who gives so secretly that his left hand does not know what his right hand gave will be shaded by Allah on the Day of Judgement."}, {"bn": "প্রত্যেক ভালো কাজই সদকা; ভাইয়ের সাথে হাসিমুখে দেখা করাও সদকা।", "en": "Every good deed is charity; meeting your brother with a smile is charity."}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৫৮৮; সহিহ বুখারি ১৪১৭; সহিহ বুখারি ১৪১০; সহিহ বুখারি ১৪২৩; সহিহ বুখারি ৬০২১; জামে তিরমিজি ১৯৫৬", "en": "Sahih Muslim 2588; Sahih al-Bukhari 1417; Sahih al-Bukhari 1410; Sahih al-Bukhari 1423; Sahih al-Bukhari 6021; Jami'' at-Tirmidhi 1956"}}, {"type": "heading", "text": {"bn": "সদকায়ে জারিয়া", "en": "Ongoing charity (sadaqah jariyah)"}}, {"type": "text", "text": {"bn": "মানুষ মারা গেলে তার আমল বন্ধ হয়ে যায়, তিনটি ছাড়া: সদকায়ে জারিয়া, উপকারী জ্ঞান এবং নেক সন্তান যে তার জন্য দোয়া করে। মসজিদ, মাদরাসা, নলকূপ, হাসপাতাল, গাছ লাগানো, কুরআন বিতরণ — এগুলো চলমান সদকার উদাহরণ (এসব খাতে নফল সদকা দেবেন; হানাফি মতে ফরজ যাকাত নয়)।", "en": "When a person dies his deeds end except three: ongoing charity, beneficial knowledge, and a righteous child who prays for him. Masjids, schools, wells, hospitals, planting trees and distributing Qurans are examples (give voluntary charity for these; in the Hanafi view not obligatory zakat)."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১৬৩১", "en": "Sahih Muslim 1631"}}, {"type": "heading", "text": {"bn": "দানের আদব", "en": "Manners of giving"}}, {"type": "list", "items": [{"bn": "হালাল ও ভালো জিনিস দান করুন; নিজে যা নিতে চান না তা দেবেন না।", "en": "Give from lawful and good things; do not give what you yourself would not accept."}, {"bn": "খোঁটা দিয়ে বা কষ্ট দিয়ে দান নষ্ট করবেন না।", "en": "Do not ruin charity with reminders of your favour or with hurt."}, {"bn": "লোক দেখানোর জন্য নয়, আল্লাহর সন্তুষ্টির জন্য দিন; গোপনে দেওয়া উত্তম, তবে অন্যকে উৎসাহিত করতে প্রকাশ্যে দেওয়াও জায়েজ।", "en": "Give for Allah, not for show; secret giving is better, though open giving to encourage others is allowed."}, {"bn": "প্রাপকের সম্মান রক্ষা করুন; ছবি তুলে প্রচার করা থেকে বিরত থাকুন।", "en": "Preserve the recipient''s dignity; avoid photographing and publicising them."}]}, {"type": "ref", "text": {"bn": "সূরা বাকারা ২:২৬৪; সূরা বাকারা ২:২৬৭; সূরা বাকারা ২:২৭১", "en": "Al-Baqarah 2:264; Al-Baqarah 2:267; Al-Baqarah 2:271"}}]', 'in_review', 60 FROM is_guide_topics WHERE slug = 'zakat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '0db15e08-cc83-54e0-9d4b-1e7b4ffe2cff', id, 'zakat-common-mistakes', '{"bn": "যাকাতে প্রচলিত ভুল", "en": "Common mistakes in zakat"}', '{"bn": "যাকাত দিতে গিয়ে মানুষ সাধারণত যে ভুলগুলো করে।", "en": "Mistakes people commonly make when paying zakat."}', 'basic', '[{"type": "list", "items": [{"bn": "হিসাব না করে আন্দাজে একটা অঙ্ক দিয়ে দেওয়া। প্রতি বছর লিখে হিসাব করুন।", "en": "Giving a rough amount without calculating. Calculate and write it down every year."}, {"bn": "শুধু রমজানে যাকাত দিতে হবে ভাবা। যাকাতের তারিখ আপনার নিসাবের বছর অনুযায়ী; চাইলে রমজানকে তারিখ বানাতে পারেন, কিন্তু পরে দেরি করা ঠিক নয়।", "en": "Thinking zakat must be paid in Ramadan. The date follows your nisab year; you may choose a Ramadan date, but do not delay beyond it."}, {"bn": "স্ত্রীর গয়না, ব্যবসার মাল বা পাওনা টাকা হিসাব থেকে বাদ দেওয়া।", "en": "Leaving out the wife''s jewellery, business stock or money owed."}, {"bn": "ইংরেজি বছর ধরে ২.৫% দেওয়া; সৌরবছরে হিসাব করলে প্রায় ২.৫৭৭% দিন।", "en": "Paying 2.5% on a solar year; on a solar year pay about 2.577%."}, {"bn": "মা-বাবা, সন্তান বা স্ত্রীকে যাকাত দেওয়া।", "en": "Giving zakat to parents, children or one''s wife."}, {"bn": "যাচাই না করে পেশাদার ভিক্ষুক বা ধনী ব্যক্তিকে দেওয়া।", "en": "Giving without checking to professional beggars or the well-off."}, {"bn": "নিম্নমানের শাড়ি-লুঙ্গির দাম বাজারমূল্যের চেয়ে বেশি ধরে যাকাত হিসাবে দেওয়া; জিনিস দিলে তার প্রকৃত মূল্যই ধরবেন।", "en": "Giving cheap clothes valued above their real price; when giving goods, count only their true value."}, {"bn": "যাকাতের টাকায় সরাসরি মসজিদ বানানো বা ওয়াজ মাহফিলের খরচ চালানো (হানাফি মতে আদায় হয় না)।", "en": "Using zakat directly to build masjids or fund events (not valid in the Hanafi view)."}, {"bn": "কর্মচারীর বেতন বা উপহার যাকাতের নামে দেওয়া; প্রাপ্য পারিশ্রমিক যাকাত নয়।", "en": "Paying an employee''s salary or a gift as zakat; wages owed are not zakat."}, {"bn": "যাকাতের নিয়ত ছাড়া দান করে পরে তাকে যাকাত ধরা; দেওয়ার সময় বা আলাদা করে রাখার সময় নিয়ত থাকতে হবে।", "en": "Giving without the intention of zakat and counting it later; the intention must be there when giving or when setting it aside."}, {"bn": "সুদের টাকা দিয়ে যাকাত দেওয়া। সুদের টাকা সওয়াবের নিয়ত ছাড়া গরিবকে দিয়ে দিতে হবে; যাকাত হালাল সম্পদ থেকে দিতে হবে।", "en": "Paying zakat from interest money. Interest must be given away without seeking reward; zakat is paid from lawful wealth."}, {"bn": "মাসিক বেতনের প্রতিটির জন্য আলাদা বছর গুনতে গিয়ে হিসাব জটিল করে ফেলা; হানাফি মতে যাকাতের তারিখে যা আছে, সবকিছুর যাকাত একসাথে দিলেই হয়।", "en": "Over-complicating by counting a separate year for every salary; for Hanafis, pay on everything you hold on the zakat date."}]}, {"type": "note", "tone": "tip", "text": {"bn": "অ্যাপের যাকাত ক্যালকুলেটর ব্যবহার করে প্রতি বছরের হিসাব সংরক্ষণ করুন, যাতে পরের বছর তুলনা করা সহজ হয়।", "en": "Use the app''s zakat calculator and keep each year''s calculation so next year''s comparison is easy."}}]', 'in_review', 70 FROM is_guide_topics WHERE slug = 'zakat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'bc8edbf2-aa93-542e-baaf-012e269acde7', id, 'hajj-basics', '{"bn": "হজ: কার ওপর ফরজ", "en": "Hajj: who must perform it"}', '{"bn": "হজ জীবনে একবার ফরজ, যদি সামর্থ্য থাকে। হজ ফরজ হওয়ার শর্ত, ফজিলত ও হজের মাসগুলো।", "en": "Hajj is obligatory once in a lifetime for those able. Its conditions, virtues and months."}', 'basic', '[{"type": "arabic", "ar": "وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا", "pron": {"bn": "ওয়া লিল্লাহি আলান নাসি হিজ্জুল বাইতি মানিসতাতাআ ইলাইহি সাবীলা", "en": "Wa lillahi ''alan-nasi hijjul-bayti manistata''a ilayhi sabila"}, "meaning": {"bn": "আর আল্লাহর জন্য মানুষের ওপর এই ঘরের হজ করা ফরজ, যে সেখানে যাওয়ার সামর্থ্য রাখে।", "en": "Pilgrimage to the House is a duty owed to Allah by people who are able to make their way there."}, "ref": {"bn": "সূরা আলে ইমরান ৩:৯৭", "en": "Aal-Imran 3:97"}}, {"type": "text", "text": {"bn": "হজ ইসলামের পঞ্চম স্তম্ভ। সামর্থ্যবান মুসলিমের ওপর জীবনে একবার হজ করা ফরজ; এর বেশি করলে তা নফল।", "en": "Hajj is the fifth pillar of Islam. It is obligatory once in a lifetime on a Muslim who is able; more than that is voluntary."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১৩৩৭", "en": "Sahih Muslim 1337"}}, {"type": "heading", "text": {"bn": "হজ ফরজ হওয়ার শর্ত", "en": "Conditions that make hajj obligatory"}}, {"type": "list", "items": [{"bn": "মুসলিম হওয়া", "en": "Being Muslim"}, {"bn": "প্রাপ্তবয়স্ক ও সুস্থ মস্তিষ্কের হওয়া", "en": "Being adult and of sound mind"}, {"bn": "স্বাধীন হওয়া", "en": "Being free"}, {"bn": "আর্থিক সামর্থ্য: যাতায়াত, থাকা-খাওয়ার খরচ এবং ফেরা পর্যন্ত পরিবারের ভরণপোষণের খরচের অতিরিক্ত অর্থ থাকা", "en": "Financial ability: money for travel, lodging and food, beyond what the family needs until return"}, {"bn": "শারীরিক সামর্থ্য ও পথের নিরাপত্তা", "en": "Physical ability and a safe route"}, {"bn": "নারীর জন্য মাহরাম বা স্বামী সঙ্গে থাকা (মতভেদ আছে; নারীদের গাইডে বিস্তারিত)", "en": "For a woman, a mahram or husband accompanying her (differed on; see the women''s guide)"}]}, {"type": "note", "tone": "info", "text": {"bn": "সামর্থ্য হওয়ার পর বিনা কারণে দেরি না করে হজ করা উচিত। হানাফি মাজহাবে (ইমাম আবু ইউসুফের মত অনুযায়ী) সামর্থ্য হলে প্রথম সুযোগেই হজ করা ওয়াজিব; দেরি করলে গুনাহ হয়, যদিও পরে করলে হজ আদায় হয়ে যায়।", "en": "Once able, one should not delay hajj without reason. In the Hanafi school (per Imam Abu Yusuf) it must be done at the first opportunity; delaying is sinful, though hajj done later is still valid."}}, {"type": "heading", "text": {"bn": "ফজিলত", "en": "Virtues"}}, {"type": "list", "items": [{"bn": "যে আল্লাহর জন্য হজ করে, অশ্লীল কথা ও গুনাহ থেকে বেঁচে থাকে, সে সদ্য জন্ম নেওয়া শিশুর মতো নিষ্পাপ হয়ে ফেরে।", "en": "Whoever performs hajj for Allah, avoiding obscenity and sin, returns as sinless as the day his mother bore him."}, {"bn": "কবুল হজের (হজে মাবরুর) প্রতিদান জান্নাত ছাড়া কিছু নয়।", "en": "The reward of an accepted hajj (hajj mabrur) is nothing less than Paradise."}, {"bn": "আরাফার দিনের চেয়ে বেশি মানুষকে আল্লাহ অন্য কোনো দিন জাহান্নাম থেকে মুক্তি দেন না।", "en": "There is no day on which Allah frees more people from the Fire than the day of Arafah."}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৫২১; সহিহ বুখারি ১৭৭৩; সহিহ মুসলিম ১৩৪৮", "en": "Sahih al-Bukhari 1521; Sahih al-Bukhari 1773; Sahih Muslim 1348"}}, {"type": "heading", "text": {"bn": "হজের মাস ও আদব", "en": "The months and manners of hajj"}}, {"type": "arabic", "ar": "الْحَجُّ أَشْهُرٌ مَعْلُومَاتٌ ۚ فَمَنْ فَرَضَ فِيهِنَّ الْحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي الْحَجِّ", "pron": {"bn": "আল হাজ্জু আশহুরুম মা''লূমাত, ফামান ফারাদা ফীহিন্নাল হাজ্জা ফালা রাফাসা ওয়ালা ফুসূকা ওয়ালা জিদালা ফিল হাজ্জ", "en": "Al-hajju ashhurum ma''lumat, faman farada fihinnal-hajja fala rafatha wa la fusuqa wa la jidala fil-hajj"}, "meaning": {"bn": "হজের মাসগুলো সুবিদিত। যে এসব মাসে হজ নিজের ওপর অপরিহার্য করে নেয়, তার জন্য হজে অশ্লীলতা, পাপাচার ও ঝগড়া-বিবাদ নেই।", "en": "Hajj is in well-known months. Whoever undertakes hajj in them, there is to be no obscenity, no wrongdoing and no quarrelling during hajj."}, "ref": {"bn": "সূরা বাকারা ২:১৯৭", "en": "Al-Baqarah 2:197"}}, {"type": "text", "text": {"bn": "হজের মাস: শাওয়াল, জিলকদ ও জিলহজের প্রথম দশ দিন। এর আগে হজের ইহরাম বাঁধা হানাফি মতে মাকরুহ এবং শাফেয়ি মতে তা উমরাহ হয়ে যায়। মূল হজের কাজগুলো হয় ৮ থেকে ১৩ জিলহজ।", "en": "The months of hajj are Shawwal, Dhul Qa''dah and the first ten days of Dhul Hijjah. Entering ihram for hajj before them is disliked for Hanafis, and for Shafi''is it becomes an umrah. The main rites take place from 8 to 13 Dhul Hijjah."}}, {"type": "note", "tone": "tip", "text": {"bn": "হজের আগে টাকা হালাল কি না নিশ্চিত হোন, কারও কাছে ঋণ বা হক থাকলে মিটিয়ে নিন, খাঁটি তওবা করুন এবং হজের নিয়মগুলো আগে থেকে ভালোভাবে শিখে নিন।", "en": "Before hajj, make sure your money is lawful, settle debts and rights owed to others, repent sincerely, and learn the rites well in advance."}}]', 'in_review', 10 FROM is_guide_topics WHERE slug = 'hajj' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'a160a7c4-b1e8-59a8-816b-d8def37d5148', id, 'hajj-types-miqat', '{"bn": "হজের প্রকার ও মিকাত", "en": "Types of hajj and the miqat"}', '{"bn": "ইফরাদ, কিরান ও তামাত্তু হজের পার্থক্য এবং কোথা থেকে ইহরাম বাঁধতে হয়।", "en": "The difference between ifrad, qiran and tamattu'', and where ihram must be entered."}', 'basic', '[{"type": "heading", "text": {"bn": "হজের তিন প্রকার", "en": "The three types of hajj"}}, {"type": "table", "head": [{"bn": "প্রকার", "en": "Type"}, {"bn": "কীভাবে", "en": "How"}, {"bn": "কুরবানি (হাদি)", "en": "Sacrifice (hady)"}], "rows": [[{"bn": "ইফরাদ", "en": "Ifrad"}, {"bn": "শুধু হজের ইহরাম; উমরাহ ছাড়া কেবল হজ", "en": "Ihram for hajj alone, without umrah"}, {"bn": "ওয়াজিব নয় (চাইলে নফল)", "en": "Not required (optional)"}], [{"bn": "কিরান", "en": "Qiran"}, {"bn": "উমরাহ ও হজ একই ইহরামে; উমরাহর পর ইহরাম খোলা যায় না, হজ শেষে খোলা হয়", "en": "Umrah and hajj in one ihram; ihram is not removed after umrah, only after hajj"}, {"bn": "ওয়াজিব", "en": "Required"}], [{"bn": "তামাত্তু", "en": "Tamattu''"}, {"bn": "হজের মাসে প্রথমে উমরাহ করে ইহরাম খুলে ফেলা, তারপর ৮ জিলহজ মক্কা থেকে নতুন করে হজের ইহরাম", "en": "Umrah in the hajj months, leave ihram, then a new ihram for hajj from Makkah on 8 Dhul Hijjah"}, {"bn": "ওয়াজিব", "en": "Required"}]]}, {"type": "arabic", "ar": "فَمَنْ تَمَتَّعَ بِالْعُمْرَةِ إِلَى الْحَجِّ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ", "pron": {"bn": "ফামান তামাত্তাআ বিল উমরাতি ইলাল হাজ্জি ফামাসতাইসারা মিনাল হাদই", "en": "Faman tamatta''a bil-''umrati ilal-hajji famastaysara minal-hady"}, "meaning": {"bn": "যে ব্যক্তি উমরাহকে হজের সাথে মিলিয়ে উপকৃত হয়, সে যা সহজলভ্য তা কুরবানি করবে।", "en": "Whoever benefits by combining umrah with hajj must offer whatever sacrifice is easily obtainable."}, "ref": {"bn": "সূরা বাকারা ২:১৯৬", "en": "Al-Baqarah 2:196"}}, {"type": "note", "tone": "info", "text": {"bn": "বাংলাদেশ থেকে যাওয়া হাজিদের বেশির ভাগ তামাত্তু হজ করেন, কারণ তারা কয়েক সপ্তাহ আগে পৌঁছান এবং দীর্ঘ সময় ইহরামে থাকা কঠিন। মক্কার স্থায়ী বাসিন্দাদের জন্য তামাত্তু ও কিরান নেই (হানাফি মত)।", "en": "Most pilgrims from Bangladesh perform tamattu'', since they arrive weeks early and staying long in ihram is hard. Residents of Makkah do not perform tamattu'' or qiran (Hanafi view)."}}, {"type": "differ", "title": {"bn": "কোন হজ উত্তম", "en": "Which type is best"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "কিরান সর্বোত্তম, তারপর তামাত্তু, তারপর ইফরাদ।", "en": "Qiran is best, then tamattu'', then ifrad."}, "evidence": {"bn": "নবী (সা.) কিরান হজ করেছিলেন বলে আনাস (রা.)-এর বর্ণনা; এতে কষ্ট ও ইবাদত বেশি।", "en": "Anas''s report that the Prophet performed qiran; it involves more effort and worship."}}, {"label": {"bn": "শাফেয়ি ও মালেকি", "en": "Shafi''i and Maliki"}, "text": {"bn": "ইফরাদ উত্তম (সেই বছরই উমরাহ করলে)।", "en": "Ifrad is best (if umrah is done the same year)."}, "evidence": {"bn": "জাবির (রা.) ও আয়েশা (রা.)-এর কিছু বর্ণনায় নবী (সা.) ইফরাদ করেছিলেন বলে এসেছে; খুলাফায়ে রাশেদিনের আমল।", "en": "Some reports from Jabir and Aishah say the Prophet performed ifrad; practice of the rightly-guided caliphs."}}, {"label": {"bn": "হাম্বলি", "en": "Hanbali"}, "text": {"bn": "তামাত্তু উত্তম।", "en": "Tamattu'' is best."}, "evidence": {"bn": "নবী (সা.) কুরবানির পশু সঙ্গে না থাকা সাহাবিদের তামাত্তু করতে বলেন এবং বলেন, আগে জানলে তিনি নিজেও পশু সঙ্গে আনতেন না।", "en": "The Prophet told Companions without sacrificial animals to make it tamattu'', saying that had he known beforehand he would not have brought his animal."}}]}, {"type": "heading", "text": {"bn": "মিকাত", "en": "The miqat"}}, {"type": "text", "text": {"bn": "মিকাত হলো সেই নির্ধারিত সীমা, যেখান থেকে হজ বা উমরাহর নিয়তে আসা ব্যক্তিকে ইহরাম বাঁধতে হয়। ইহরাম ছাড়া মিকাত পার হলে ফিরে এসে ইহরাম বাঁধতে হবে, নয়তো দম (একটি পশু কুরবানি) দিতে হবে।", "en": "The miqat is the fixed boundary at which anyone intending hajj or umrah must enter ihram. Crossing it without ihram means returning to enter ihram there, or else a dam (one animal sacrifice) is due."}}, {"type": "table", "head": [{"bn": "মিকাত", "en": "Miqat"}, {"bn": "কাদের জন্য", "en": "For whom"}, {"bn": "বর্তমান নাম/অবস্থান", "en": "Today"}], "rows": [[{"bn": "যুল হুলাইফা", "en": "Dhul Hulayfah"}, {"bn": "মদিনা থেকে আসা ব্যক্তি", "en": "Those coming from Madinah"}, {"bn": "আবইয়ার আলী (মদিনার কাছে)", "en": "Abyar Ali (near Madinah)"}], [{"bn": "জুহফা", "en": "Al-Juhfah"}, {"bn": "সিরিয়া, মিসর ও পশ্চিম দিক থেকে", "en": "From Syria, Egypt and the west"}, {"bn": "রাবিগের কাছে", "en": "Near Rabigh"}], [{"bn": "কারনুল মানাযিল", "en": "Qarn al-Manazil"}, {"bn": "নজদ ও পূর্ব দিক থেকে", "en": "From Najd and the east"}, {"bn": "আস-সাইল আল-কাবির", "en": "As-Sayl al-Kabir"}], [{"bn": "ইয়ালামলাম", "en": "Yalamlam"}, {"bn": "ইয়েমেন ও দক্ষিণ দিক থেকে; উপমহাদেশ থেকে সমুদ্রপথে আসা যাত্রী", "en": "From Yemen and the south; travellers by sea from the subcontinent"}, {"bn": "আস-সাদিয়া", "en": "As-Sa''diyyah"}], [{"bn": "যাতু ইরক", "en": "Dhat ''Irq"}, {"bn": "ইরাক থেকে", "en": "From Iraq"}, {"bn": "বর্তমানে সড়কপথে খুব কম ব্যবহৃত", "en": "Rarely used by road today"}]]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৫২৪; সহিহ মুসলিম ১১৮১", "en": "Sahih al-Bukhari 1524; Sahih Muslim 1181"}}, {"type": "note", "tone": "warn", "text": {"bn": "বাংলাদেশ থেকে সরাসরি জেদ্দাগামী বিমানের যাত্রীদের বিমান মিকাতের সীমা পার হয় জেদ্দায় নামার আগেই। তাই ঢাকা থেকেই ইহরামের কাপড় পরে নিন (বা বিমানে পরুন) এবং মিকাত কাছে আসার ঘোষণা হলে নিয়ত করে তালবিয়া পড়ুন। জেদ্দায় নেমে ইহরাম বাঁধার অপেক্ষা করবেন না।", "en": "On direct flights from Bangladesh to Jeddah, the plane crosses the miqat line before landing. So put on the ihram clothes in Dhaka (or on the plane) and make the intention and talbiyah when the miqat is announced. Do not wait to enter ihram in Jeddah."}}, {"type": "note", "tone": "info", "text": {"bn": "যারা প্রথমে মদিনা যাবেন, তারা বিমানে ইহরাম বাঁধবেন না; পরে মদিনা থেকে মক্কা যাওয়ার পথে যুল হুলাইফায় ইহরাম বাঁধবেন। মিকাতের ভেতরে বসবাসকারীরা নিজের অবস্থান থেকেই ইহরাম বাঁধেন; আর মক্কায় অবস্থানকারী হজের ইহরাম মক্কা থেকে এবং উমরাহর ইহরাম হারামের সীমার বাইরে (যেমন তানঈম) থেকে বাঁধেন।", "en": "Those going to Madinah first do not enter ihram on the plane; they enter it at Dhul Hulayfah on the way from Madinah to Makkah. People living inside the miqat enter ihram from where they are; someone in Makkah enters hajj ihram in Makkah and umrah ihram outside the Haram boundary (e.g. at Tan''im)."}}]', 'in_review', 20 FROM is_guide_topics WHERE slug = 'hajj' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '0865c935-d037-5964-8a65-33f1862807fb', id, 'hajj-ihram', '{"bn": "ইহরাম: নিয়ম ও নিষেধ", "en": "Ihram: rules and prohibitions"}', '{"bn": "ইহরামের প্রস্তুতি, পোশাক, নিয়ত, তালবিয়া এবং ইহরাম অবস্থায় যা নিষেধ।", "en": "Preparing for ihram, the clothing, the intention, the talbiyah and what is forbidden in ihram."}', 'basic', '[{"type": "text", "text": {"bn": "ইহরাম মানে হজ বা উমরাহর নিয়ত করে তালবিয়া পড়ার মাধ্যমে এমন অবস্থায় প্রবেশ করা, যেখানে কিছু হালাল কাজও সাময়িকভাবে নিষিদ্ধ হয়ে যায়। শুধু সাদা কাপড় পরলেই ইহরাম হয় না; নিয়ত ও তালবিয়াই মূল।", "en": "Ihram is entering, by intention and the talbiyah, a sacred state in which some normally lawful things become temporarily forbidden. Wearing white sheets alone is not ihram; the intention and talbiyah are what count."}}, {"type": "step", "title": {"bn": "পরিচ্ছন্নতা", "en": "Cleanliness"}, "text": {"bn": "নখ কাটা, অবাঞ্ছিত লোম পরিষ্কার করা, তারপর গোসল করা (সুন্নত; গোসল সম্ভব না হলে ওজু)। হায়েজ-নিফাস অবস্থায় নারীরাও গোসল করবেন।", "en": "Trim nails, remove unwanted hair, then take a ghusl (sunnah; wudu if ghusl is not possible). Women in menstruation or post-natal bleeding also take this ghusl."}}, {"type": "step", "title": {"bn": "সুগন্ধি", "en": "Perfume"}, "text": {"bn": "পুরুষ ইহরামের আগে শরীরে (কাপড়ে নয়) সুগন্ধি লাগাতে পারেন; ইহরামের পরে তার ঘ্রাণ থেকে গেলে সমস্যা নেই।", "en": "Men may apply perfume to the body (not the ihram cloth) before ihram; its lingering scent afterwards is fine."}}, {"type": "step", "title": {"bn": "পোশাক", "en": "Clothing"}, "text": {"bn": "পুরুষ: সেলাইবিহীন দুটি চাদর, একটি লুঙ্গির মতো (ইজার), একটি গায়ে (রিদা); সাদা হওয়া উত্তম। মাথা খোলা, আর এমন জুতা/স্যান্ডেল যাতে পায়ের পাতার মাঝখানের উঁচু হাড় খোলা থাকে। নারী: সাধারণ শালীন পোশাক, যেকোনো রঙের; শুধু মুখে নিকাব ও হাতে মোজা পরবেন না।", "en": "Men: two unstitched sheets, one wrapped round the waist (izar) and one over the shoulders (rida), preferably white; head uncovered; sandals that leave the raised middle of the foot exposed. Women: ordinary modest clothes of any colour; only no face veil (niqab) and no gloves."}}, {"type": "step", "title": {"bn": "দুই রাকাত নামাজ", "en": "Two rakats"}, "text": {"bn": "মাকরুহ সময় না হলে ইহরামের নিয়তে দুই রাকাত নামাজ পড়া সুন্নত (হানাফি মত); অন্যদের মতে কোনো ফরজ নামাজের পরে ইহরাম বাঁধা উত্তম।", "en": "If it is not a disliked time, pray two rakats for ihram (Hanafi view); others say it is best to enter ihram after an obligatory prayer."}}, {"type": "step", "title": {"bn": "নিয়ত ও তালবিয়া", "en": "Intention and talbiyah"}, "text": {"bn": "মিকাতে বা তার আগে মনে মনে হজ/উমরাহর নিয়ত করুন এবং তালবিয়া পড়ুন। তালবিয়া পড়ার সঙ্গে সঙ্গে ইহরাম শুরু।", "en": "At or before the miqat, make the intention for hajj/umrah in your heart and say the talbiyah. Ihram begins with it."}}, {"type": "note", "tone": "tip", "text": {"bn": "নিয়ত মনের বিষয়। প্রচলিত মৌখিক উদাহরণ: ইফরাদে ''লাব্বাইকা হাজ্জান'', তামাত্তুতে প্রথমে ''লাব্বাইকা উমরাতান'', কিরানে ''লাব্বাইকা উমরাতান ওয়া হাজ্জান''। মুখে বলা শর্ত নয়, তবে এভাবে বলা সাহাবিদের থেকে বর্ণিত।", "en": "The intention is in the heart. Common spoken examples: for ifrad ''Labbayka hajjan'', for tamattu'' first ''Labbayka ''umratan'', for qiran ''Labbayka ''umratan wa hajjan''. Saying it is not a condition, though Companions are reported to have said it."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম (আনাস রা.: ''লাব্বাইকা উমরাতান ওয়া হাজ্জান'')", "en": "Sahih Muslim (Anas: ''Labbayka ''umratan wa hajjan'')"}, "check": true}, {"type": "arabic", "label": {"bn": "তালবিয়া", "en": "Talbiyah"}, "ar": "لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لَا شَرِيكَ لَكَ", "pron": {"bn": "লাব্বাইকা আল্লাহুম্মা লাব্বাইক, লাব্বাইকা লা শারীকা লাকা লাব্বাইক, ইন্নাল হামদা ওয়ান নি''মাতা লাকা ওয়াল মুলক, লা শারীকা লাক", "en": "Labbayka Allahumma labbayk, labbayka la sharika laka labbayk, innal-hamda wan-ni''mata laka wal-mulk, la sharika lak"}, "meaning": {"bn": "আমি হাজির, হে আল্লাহ! আমি হাজির। আমি হাজির, তোমার কোনো শরিক নেই, আমি হাজির। নিশ্চয়ই সব প্রশংসা, সব নিয়ামত তোমারই, আর রাজত্বও তোমার; তোমার কোনো শরিক নেই।", "en": "Here I am, O Allah, here I am. Here I am, You have no partner, here I am. Surely all praise and blessings are Yours, and the dominion; You have no partner."}, "ref": {"bn": "সহিহ বুখারি ১৫৪৯; সহিহ মুসলিম ১১৮৪", "en": "Sahih al-Bukhari 1549; Sahih Muslim 1184"}}, {"type": "note", "tone": "info", "text": {"bn": "পুরুষরা উচ্চস্বরে, নারীরা নিচু স্বরে তালবিয়া পড়বেন। ইহরাম থেকে শুরু করে উমরাহয় তাওয়াফ শুরু পর্যন্ত, আর হজে ১০ জিলহজ জামরাতুল আকাবায় প্রথম কংকর মারা পর্যন্ত বেশি বেশি তালবিয়া পড়ুন।", "en": "Men say the talbiyah aloud, women quietly. Say it often from ihram until starting tawaf in umrah, and in hajj until the first pebble at Jamrat al-Aqabah on 10 Dhul Hijjah."}}, {"type": "heading", "text": {"bn": "ইহরাম অবস্থায় যা নিষেধ", "en": "What is forbidden in ihram"}}, {"type": "list", "items": [{"bn": "চুল, দাড়ি বা শরীরের কোনো লোম কাটা বা ওঠানো; নখ কাটা", "en": "Cutting or removing hair from the head, beard or body; cutting nails"}, {"bn": "শরীর, কাপড় বা খাবারে সুগন্ধি ব্যবহার; সুগন্ধিযুক্ত সাবান", "en": "Using perfume on the body, clothes or food; scented soap"}, {"bn": "পুরুষের জন্য সেলাই করা পোশাক (জামা, প্যান্ট, গেঞ্জি, মোজা) পরা এবং মাথা ঢাকা", "en": "For men: wearing sewn, body-shaped garments (shirts, trousers, vests, socks) and covering the head"}, {"bn": "মুখ ঢাকা (পুরুষের জন্য সব মাজহাবে; নারীর জন্য মুখের সঙ্গে লেগে থাকা নিকাব)", "en": "Covering the face (for men in all schools; for women, a niqab fitted to the face)"}, {"bn": "স্থলের প্রাণী শিকার করা বা শিকারে সাহায্য করা", "en": "Hunting land animals or helping to hunt"}, {"bn": "বিয়ে করা বা বিয়ের প্রস্তাব দেওয়া", "en": "Marrying or proposing marriage"}, {"bn": "স্ত্রী-সহবাস, কামভাবের সাথে স্পর্শ বা অশ্লীল কথা", "en": "Marital relations, touching with desire, or obscene talk"}, {"bn": "ঝগড়া-বিবাদ ও সব ধরনের গুনাহ (এগুলো সবসময় নিষেধ, ইহরামে আরও কঠোরভাবে)", "en": "Quarrelling and all sins (always forbidden, more so in ihram)"}, {"bn": "হারামের সীমার ভেতরের গাছ কাটা বা ঘাস ওপড়ানো (ইহরাম ছাড়াও হারামে নিষেধ)", "en": "Cutting trees or uprooting plants within the Haram (forbidden there even without ihram)"}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৫৪২; সহিহ বুখারি ১৮৩৮", "en": "Sahih al-Bukhari 1542; Sahih al-Bukhari 1838"}}, {"type": "heading", "text": {"bn": "যা করা যায়", "en": "What is allowed"}}, {"type": "list", "items": [{"bn": "গোসল করা, সুগন্ধিহীন সাবান ব্যবহার", "en": "Bathing and using unscented soap"}, {"bn": "ঘড়ি, চশমা, বেল্ট বা টাকার থলে ব্যবহার", "en": "Wearing a watch, glasses, a belt or money pouch"}, {"bn": "ছাতা বা তাঁবুর ছায়া নেওয়া", "en": "Shade of an umbrella or tent"}, {"bn": "ইহরামের কাপড় বদলানো বা ধোয়া", "en": "Changing or washing the ihram sheets"}, {"bn": "প্রয়োজনে ওষুধ খাওয়া, ইনজেকশন নেওয়া", "en": "Taking medicine or injections when needed"}]}, {"type": "heading", "text": {"bn": "নিষিদ্ধ কাজ হয়ে গেলে", "en": "If a prohibition is broken"}}, {"type": "text", "text": {"bn": "ভুলে বা অজ্ঞতায় কিংবা জেনেশুনে নিষিদ্ধ কাজ হয়ে গেলে কাজের ধরন অনুযায়ী দম (মক্কার হারামে একটি ছাগল/ভেড়া বা গরু-উটের সাত ভাগের এক ভাগ কুরবানি) বা সদকা দিতে হয়। আরাফায় অবস্থানের আগে সহবাস করলে হজ নষ্ট হয়ে যায়। নির্দিষ্ট ক্ষেত্রে কী দিতে হবে, কাফেলার আলেম বা মুয়াল্লিমের কাছে জেনে নিন।", "en": "If a prohibition is broken, by mistake, ignorance or deliberately, a dam (sacrificing a sheep/goat or a seventh of a cow/camel in the Haram) or a charity is due depending on the act. Intercourse before standing at Arafah invalidates the hajj. Ask your group''s scholar what is due in a specific case."}}, {"type": "ref", "text": {"bn": "সূরা বাকারা ২:১৯৬", "en": "Al-Baqarah 2:196"}}]', 'in_review', 30 FROM is_guide_topics WHERE slug = 'hajj' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '6ced096e-e4b1-5edf-9b47-396271fc015d', id, 'hajj-days-8-9', '{"bn": "হজের দিন: ৮ ও ৯ জিলহজ (মিনা, আরাফা, মুজদালিফা)", "en": "Hajj days 8–9: Mina, Arafah, Muzdalifah"}', '{"bn": "তারবিয়ার দিন মিনায় যাওয়া, আরাফার দিনের অবস্থান ও দোয়া, তারপর মুজদালিফায় রাত যাপন।", "en": "Going to Mina on the day of Tarwiyah, standing at Arafah with its dua, then the night at Muzdalifah."}', 'detail', '[{"type": "table", "head": [{"bn": "তারিখ", "en": "Date"}, {"bn": "স্থান", "en": "Place"}, {"bn": "প্রধান কাজ", "en": "Main acts"}], "rows": [[{"bn": "৮ জিলহজ", "en": "8 Dhul Hijjah"}, {"bn": "মিনা", "en": "Mina"}, {"bn": "ইহরাম (তামাত্তু হলে), মিনায় পাঁচ ওয়াক্ত নামাজ", "en": "Ihram (for tamattu''), five prayers in Mina"}], [{"bn": "৯ জিলহজ", "en": "9 Dhul Hijjah"}, {"bn": "আরাফা → মুজদালিফা", "en": "Arafah → Muzdalifah"}, {"bn": "আরাফায় অবস্থান (হজের প্রধান রুকন), রাতে মুজদালিফা", "en": "Standing at Arafah (the main pillar), night at Muzdalifah"}], [{"bn": "১০ জিলহজ", "en": "10 Dhul Hijjah"}, {"bn": "মুজদালিফা → মিনা → মক্কা", "en": "Muzdalifah → Mina → Makkah"}, {"bn": "বড় জামরায় কংকর, কুরবানি, মাথা মুণ্ডন, তাওয়াফে জিয়ারত", "en": "Stoning the big jamrah, sacrifice, shaving, tawaf al-ifadah"}], [{"bn": "১১–১২ জিলহজ", "en": "11–12 Dhul Hijjah"}, {"bn": "মিনা", "en": "Mina"}, {"bn": "তিন জামরায় কংকর", "en": "Stoning the three jamarat"}], [{"bn": "১৩ জিলহজ (ঐচ্ছিক)", "en": "13 Dhul Hijjah (optional)"}, {"bn": "মিনা", "en": "Mina"}, {"bn": "তিন জামরায় কংকর, তারপর বিদায়", "en": "Stoning the three jamarat, then departure"}]]}, {"type": "heading", "text": {"bn": "৮ জিলহজ: ইয়াওমুত তারবিয়া", "en": "8 Dhul Hijjah: the day of Tarwiyah"}}, {"type": "step", "title": {"bn": "ইহরাম", "en": "Ihram"}, "text": {"bn": "তামাত্তু হাজিরা মক্কায় নিজের অবস্থানস্থল থেকে গোসল করে হজের ইহরাম বাঁধবেন ও তালবিয়া পড়বেন। কিরান ও ইফরাদ হাজিরা আগে থেকেই ইহরামে আছেন।", "en": "Tamattu'' pilgrims take a ghusl and enter hajj ihram from their lodging in Makkah and say the talbiyah. Qiran and ifrad pilgrims are already in ihram."}}, {"type": "step", "title": {"bn": "মিনায় যাওয়া", "en": "Go to Mina"}, "text": {"bn": "সকালে মিনায় গিয়ে জোহর, আসর, মাগরিব, এশা এবং ৯ তারিখের ফজর মিনায় আদায় করা ও রাত যাপন সুন্নত। নামাজ নিজ নিজ ওয়াক্তে পড়বেন।", "en": "Go to Mina in the morning; praying Zuhr, Asr, Maghrib, Isha and the Fajr of the 9th there and spending the night is sunnah. Pray each prayer in its own time."}}, {"type": "note", "tone": "info", "text": {"bn": "মিনায় চার রাকাতের নামাজ কসর হবে কি না, তা নিয়ে মতভেদ আছে: হানাফি মতে মক্কায় ১৫ দিন বা তার বেশি অবস্থানের নিয়ত করে থাকা হাজিরা পুরো নামাজ পড়বেন; অন্য অনেক আলেমের মতে সব হাজি মিনা-আরাফা-মুজদালিফায় কসর করবেন। নিজের কাফেলার আলেমের নির্দেশনা মানুন।", "en": "Scholars differ on shortening four-rakat prayers in Mina: in the Hanafi view pilgrims who intended to stay 15 days or more in Makkah pray in full; many others say all pilgrims shorten in Mina, Arafah and Muzdalifah. Follow your group''s scholar."}}, {"type": "heading", "text": {"bn": "৯ জিলহজ: আরাফার দিন", "en": "9 Dhul Hijjah: the day of Arafah"}}, {"type": "step", "title": {"bn": "আরাফায় যাওয়া", "en": "Go to Arafah"}, "text": {"bn": "সূর্যোদয়ের পর তালবিয়া পড়তে পড়তে আরাফার দিকে রওনা হোন। আরাফার সীমানা নির্দেশক বোর্ড দেখে নিশ্চিত হোন যে আপনি সীমার ভেতরে আছেন; উরানা উপত্যকা আরাফার অংশ নয়।", "en": "After sunrise set off for Arafah saying the talbiyah. Check the boundary signs to be sure you are inside Arafah; the valley of ''Uranah is not part of it."}}, {"type": "step", "title": {"bn": "অবস্থান (উকুফ)", "en": "The standing (wuquf)"}, "text": {"bn": "জাওয়াল (দুপুরে সূর্য হেলে পড়া) থেকে সূর্যাস্ত পর্যন্ত আরাফায় অবস্থান করুন। দাঁড়িয়ে, বসে, শুয়ে যেকোনোভাবে থাকা যায়; সময়টা কাটান দোয়া, জিকির, ইস্তিগফার, তালবিয়া ও কুরআন তিলাওয়াতে, কিবলামুখী হয়ে হাত তুলে দোয়া করুন।", "en": "Stay at Arafah from zawal (just after midday) until sunset. You may stand, sit or lie down; spend the time in dua, dhikr, seeking forgiveness, talbiyah and Quran, facing the qiblah with hands raised in dua."}}, {"type": "step", "title": {"bn": "জোহর ও আসর", "en": "Zuhr and Asr"}, "text": {"bn": "মসজিদে নামিরায় ইমামের সঙ্গে জোহর ও আসর জোহরের ওয়াক্তে একসাথে পড়া হয়।", "en": "At Masjid Namirah, Zuhr and Asr are prayed together in Zuhr time with the imam."}}, {"type": "note", "tone": "info", "text": {"bn": "তাঁবুতে আলাদা জামাতে জোহর-আসর একসাথে পড়া যাবে কি না, তা নিয়ে মতভেদ আছে: ইমাম আবু হানিফার মতে একসাথে পড়ার শর্ত হজের ইমামের সঙ্গে পড়া, নইলে প্রতিটি নিজ ওয়াক্তে; অন্য মাজহাব ও হানাফি সাহিবাইনের মতে তাঁবুতেও একসাথে পড়া যায়।", "en": "Scholars differ on combining Zuhr and Asr in separate congregations in the tents: for Imam Abu Hanifa combining requires praying with the hajj imam, otherwise each is prayed in its time; the other schools and Abu Hanifa''s two students allow combining in the tents."}}, {"type": "arabic", "label": {"bn": "আরাফার দিনের শ্রেষ্ঠ দোয়া", "en": "The best dua on the day of Arafah"}, "ar": "لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ", "pron": {"bn": "লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারীকা লাহু, লাহুল মুলকু ওয়া লাহুল হামদু, ওয়া হুয়া আলা কুল্লি শাইয়িন কাদীর", "en": "La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamd, wa huwa ''ala kulli shay''in qadir"}, "meaning": {"bn": "আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি এক, তাঁর কোনো শরিক নেই। রাজত্ব তাঁরই, প্রশংসাও তাঁর, তিনি সবকিছুর ওপর ক্ষমতাবান।", "en": "There is no god but Allah alone, without partner. His is the dominion and His is the praise, and He has power over all things."}, "ref": {"bn": "জামে তিরমিজি ৩৫৮৫", "en": "Jami'' at-Tirmidhi 3585"}}, {"type": "note", "tone": "tip", "text": {"bn": "নবী (সা.) বলেছেন, সর্বোত্তম দোয়া আরাফার দিনের দোয়া, আর তিনি ও পূর্ববর্তী নবীগণ যা বলেছেন তার মধ্যে শ্রেষ্ঠ এই বাক্য। নিজের ভাষায় নিজের, পরিবারের ও উম্মাহর জন্য মন খুলে দোয়া করুন। জাবালে রহমত পাহাড়ে ওঠা জরুরি নয়; আরাফার যেকোনো স্থানে অবস্থানই যথেষ্ট।", "en": "The Prophet said the best dua is the dua of the day of Arafah, and the best words he and the prophets before him said are these. Pray from the heart in your own language for yourself, your family and the ummah. Climbing Jabal ar-Rahmah is not required; anywhere within Arafah is enough."}}, {"type": "ref", "text": {"bn": "জামে তিরমিজি ৮৮৯; সহিহ মুসলিম ১২১৮", "en": "Jami'' at-Tirmidhi 889; Sahih Muslim 1218"}}, {"type": "note", "tone": "warn", "text": {"bn": "সূর্যাস্তের আগে আরাফার সীমা থেকে বের হবেন না। হানাফি মতে দিনে আরাফায় পৌঁছালে সূর্যাস্ত পর্যন্ত থাকা ওয়াজিব; আগে বের হয়ে গেলে দম দিতে হয়।", "en": "Do not leave Arafah before sunset. For Hanafis, someone who reaches Arafah in the day must stay until sunset; leaving earlier requires a dam."}}, {"type": "heading", "text": {"bn": "৯ জিলহজের রাত: মুজদালিফা", "en": "The night of the 9th: Muzdalifah"}}, {"type": "step", "title": {"bn": "মুজদালিফায় যাওয়া", "en": "Go to Muzdalifah"}, "text": {"bn": "সূর্যাস্তের পর মাগরিব না পড়ে শান্তভাবে তালবিয়া ও জিকির করতে করতে মুজদালিফায় যান।", "en": "After sunset, go calmly to Muzdalifah saying the talbiyah and dhikr, without praying Maghrib at Arafah."}}, {"type": "step", "title": {"bn": "মাগরিব ও এশা", "en": "Maghrib and Isha"}, "text": {"bn": "মুজদালিফায় পৌঁছে এশার ওয়াক্তে মাগরিব ও এশা একসাথে আদায় করুন (মাগরিব তিন রাকাত, এশা দুই বা চার রাকাত, কসরের বিধান অনুযায়ী)।", "en": "At Muzdalifah pray Maghrib and Isha together in Isha time (Maghrib three rakats, Isha two or four depending on the rule of shortening)."}}, {"type": "step", "title": {"bn": "রাত যাপন ও কংকর", "en": "Night and pebbles"}, "text": {"bn": "এখানে খোলা আকাশের নিচে রাত কাটানো সুন্নত। ১০ তারিখের জন্য ৭টি (বা সব দিনের জন্য ৪৯/৭০টি) ছোলার দানার মতো ছোট কংকর এখান থেকে বা মিনা থেকে সংগ্রহ করা যায়।", "en": "Spending the night here in the open is sunnah. Pebbles the size of a chickpea, 7 for the 10th (or 49/70 for all days), may be collected here or in Mina."}}, {"type": "step", "title": {"bn": "ফজর ও উকুফ", "en": "Fajr and the standing"}, "text": {"bn": "ফজরের ওয়াক্ত শুরু হলেই ফজর পড়ে মাশআরুল হারামের কাছে বা মুজদালিফার যেকোনো স্থানে কিবলামুখী হয়ে আকাশ বেশ ফরসা হওয়া পর্যন্ত দোয়া-জিকির করুন, তারপর সূর্যোদয়ের আগে মিনার দিকে রওনা দিন।", "en": "Pray Fajr as soon as its time begins, then at Al-Mash''ar al-Haram or anywhere in Muzdalifah face the qiblah and make dua and dhikr until it is quite light, then set off for Mina before sunrise."}}, {"type": "arabic", "ar": "فَإِذَا أَفَضْتُمْ مِنْ عَرَفَاتٍ فَاذْكُرُوا اللَّهَ عِنْدَ الْمَشْعَرِ الْحَرَامِ", "pron": {"bn": "ফাইযা আফাদতুম মিন আরাফাতিন ফাযকুরুল্লাহা ইনদাল মাশআরিল হারাম", "en": "Fa idha afadtum min ''arafatin fadhkurullaha ''indal-mash''aril-haram"}, "meaning": {"bn": "যখন তোমরা আরাফা থেকে ফিরে আসবে, তখন মাশআরুল হারামের কাছে আল্লাহকে স্মরণ করো।", "en": "When you pour down from Arafat, remember Allah at Al-Mash''ar al-Haram."}, "ref": {"bn": "সূরা বাকারা ২:১৯৮", "en": "Al-Baqarah 2:198"}}, {"type": "differ", "title": {"bn": "মুজদালিফায় অবস্থানের ওয়াজিব অংশ", "en": "The obligatory part of Muzdalifah"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "সুবহে সাদিক থেকে সূর্যোদয়ের মধ্যে অল্প সময় হলেও মুজদালিফায় থাকা ওয়াজিব; রাত যাপন সুন্নত। দুর্বল, অসুস্থ ও নারীরা ভিড়ের ভয়ে আগে চলে গেলে দম লাগে না।", "en": "Being in Muzdalifah for any time between true dawn and sunrise is obligatory; spending the night is sunnah. The weak, sick and women who leave early for fear of crowds owe no dam."}, "evidence": {"bn": "নবী (সা.) ফজরের পর মাশআরুল হারামে অবস্থান করেছেন; দুর্বলদের রাতেই পাঠিয়ে দিয়েছেন।", "en": "The Prophet stood at Al-Mash''ar al-Haram after Fajr and sent the weak ahead at night."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "মধ্যরাতের পর কিছু সময় মুজদালিফায় থাকা ওয়াজিব; মধ্যরাতের পর চলে যাওয়া জায়েজ, বিশেষ করে দুর্বলদের জন্য।", "en": "Being in Muzdalifah for some time after midnight is obligatory; leaving after midnight is allowed, especially for the weak."}, "evidence": {"bn": "সাওদা (রা.) ও আসমা (রা.)-কে রাতেই মুজদালিফা ছাড়ার অনুমতি দেওয়ার বর্ণনা।", "en": "Reports that Sawdah and Asma'' were allowed to leave Muzdalifah during the night."}}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি; সহিহ মুসলিম (সাওদা রা.-কে রাতেই মুজদালিফা ছাড়ার অনুমতি)", "en": "Sahih al-Bukhari; Sahih Muslim (Sawdah allowed to leave Muzdalifah at night)"}, "check": true}]', 'in_review', 40 FROM is_guide_topics WHERE slug = 'hajj' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'a25de849-edc5-5a9e-a4c6-7781ebc14365', id, 'hajj-days-10-13', '{"bn": "হজের দিন: ১০ থেকে ১৩ জিলহজ", "en": "Hajj days 10–13 Dhul Hijjah"}', '{"bn": "ঈদের দিনের চার কাজ (কংকর, কুরবানি, মুণ্ডন, তাওয়াফ), মিনার দিনগুলো এবং বিদায়ী তাওয়াফ।", "en": "The four acts of Eid day (stoning, sacrifice, shaving, tawaf), the days in Mina and the farewell tawaf."}', 'detail', '[{"type": "heading", "text": {"bn": "১০ জিলহজ: ইয়াওমুন নাহর (কুরবানির দিন)", "en": "10 Dhul Hijjah: Yawm an-Nahr (day of sacrifice)"}}, {"type": "step", "title": {"bn": "জামরাতুল আকাবায় কংকর", "en": "Stone Jamrat al-Aqabah"}, "text": {"bn": "মিনায় পৌঁছে শুধু বড় জামরায় (জামরাতুল আকাবা) একে একে সাতটি কংকর মারুন; প্রতিটির সাথে ''আল্লাহু আকবার'' বলুন। প্রথম কংকর মারার সঙ্গে সঙ্গে তালবিয়া বন্ধ। এদিনের কংকর মারার সুন্নত সময় সূর্যোদয় থেকে জাওয়াল পর্যন্ত, তবে পরেও জায়েজ।", "en": "In Mina stone only the big jamrah (Jamrat al-Aqabah) with seven pebbles one by one, saying ''Allahu akbar'' with each. Talbiyah stops with the first pebble. The sunnah time for this day is from sunrise to zawal, though later is permitted."}}, {"type": "arabic", "label": {"bn": "প্রতিটি কংকর মারার সময়", "en": "With each pebble"}, "ar": "اللَّهُ أَكْبَرُ", "pron": {"bn": "আল্লাহু আকবার", "en": "Allahu akbar"}, "meaning": {"bn": "আল্লাহ সবচেয়ে মহান।", "en": "Allah is the Greatest."}, "ref": {"bn": "সহিহ বুখারি (ইবনে উমর রা.-এর বর্ণনা)", "en": "Sahih al-Bukhari (narration of Ibn Umar)"}, "check": true}, {"type": "step", "title": {"bn": "কুরবানি (হাদি)", "en": "Sacrifice (hady)"}, "text": {"bn": "তামাত্তু ও কিরান হাজির জন্য কুরবানি ওয়াজিব; ইফরাদ হাজির জন্য ঐচ্ছিক। সাধারণত ব্যাংক বা অনুমোদিত সংস্থার মাধ্যমে কুপন কেনা হয়; কুরবানি কখন হলো, তা নিশ্চিত হয়ে নিন, কারণ এরপরই মাথা মুণ্ডন করবেন।", "en": "The sacrifice is required for tamattu'' and qiran pilgrims and optional for ifrad. It is usually arranged by buying a voucher through a bank or approved body; confirm when it is done, since you shave after it."}}, {"type": "step", "title": {"bn": "মাথা মুণ্ডন বা চুল ছোট করা", "en": "Shave or shorten the hair"}, "text": {"bn": "পুরুষের জন্য পুরো মাথা মুণ্ডন (হলক) উত্তম, অথবা চুল ছোট করা (কসর)। নারীরা চুলের আগা থেকে আঙুলের এক কর পরিমাণ কাটবেন। এরপর স্ত্রী-সংক্রান্ত বিষয় ছাড়া ইহরামের সব নিষেধ উঠে যায় (প্রথম হালাল)।", "en": "For men, shaving the whole head (halq) is better, or shortening (qasr). Women cut a fingertip''s length from the ends. After this everything forbidden by ihram becomes lawful except marital matters (first release)."}}, {"type": "step", "title": {"bn": "তাওয়াফে জিয়ারত (ইফাদা)", "en": "Tawaf al-Ifadah (ziyarah)"}, "text": {"bn": "মক্কায় গিয়ে হজের ফরজ তাওয়াফ করুন। ১০ তারিখে করা উত্তম; হানাফি মতে ১২ জিলহজের সূর্যাস্তের আগে করতে হবে, বিনা ওজরে দেরি করলে দম। তামাত্তু হাজিরা এরপর সাফা-মারওয়ায় সাঈ করবেন; কিরান/ইফরাদ হাজি আগে তাওয়াফে কুদুমের পর সাঈ করে থাকলে আবার লাগবে না।", "en": "Go to Makkah and perform the obligatory tawaf of hajj. The 10th is best; for Hanafis it must be done before sunset on the 12th, otherwise a dam is due without excuse. Tamattu'' pilgrims then do sa''i; qiran/ifrad pilgrims who did sa''i after tawaf al-qudum need not repeat it."}}, {"type": "note", "tone": "info", "text": {"bn": "তাওয়াফে জিয়ারতের পর স্বামী-স্ত্রীর সম্পর্কসহ ইহরামের সব নিষেধ উঠে যায় (দ্বিতীয় হালাল)। তারপর মিনায় ফিরে রাত কাটাবেন।", "en": "After tawaf al-ifadah all ihram restrictions, including marital relations, are lifted (second release). Then return to Mina for the night."}}, {"type": "differ", "title": {"bn": "১০ তারিখের কাজগুলোর ধারাবাহিকতা", "en": "The order of the acts of the 10th"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "তামাত্তু ও কিরান হাজির জন্য কংকর → কুরবানি → মুণ্ডন এই ধারাবাহিকতা ওয়াজিব; উল্টাপাল্টা হলে ইমাম আবু হানিফার মতে দম দিতে হবে। (ইফরাদ হাজির কুরবানি নেই; তার জন্য কংকরের পর মুণ্ডন।)", "en": "For tamattu'' and qiran pilgrims the order stoning → sacrifice → shaving is obligatory; breaking it requires a dam per Imam Abu Hanifa. (Ifrad has no sacrifice; stoning then shaving.)"}, "evidence": {"bn": "নবী (সা.) এই ক্রমে করেছেন এবং বলেছেন, ''তোমাদের হজের নিয়ম আমার কাছ থেকে শিখে নাও।''", "en": "The Prophet did them in this order and said, ''Take your rites from me.''"}}, {"label": {"bn": "শাফেয়ি, হাম্বলি, হানাফি সাহিবাইন", "en": "Shafi''i, Hanbali, Abu Hanifa''s two students"}, "text": {"bn": "ক্রম মানা সুন্নত; আগে-পরে হয়ে গেলে কোনো দম নেই।", "en": "Keeping the order is sunnah; doing them out of order requires no dam."}, "evidence": {"bn": "১০ তারিখে আগে-পরে করার প্রশ্ন এলে নবী (সা.) বলতেন, ''করে ফেলো, কোনো সমস্যা নেই।''", "en": "On the 10th, when asked about doing things out of order, the Prophet said, ''Do it, there is no harm.''"}}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৭৩৬; সহিহ মুসলিম ১৩০৬; সহিহ মুসলিম ১২৯৭", "en": "Sahih al-Bukhari 1736; Sahih Muslim 1306; Sahih Muslim 1297"}}, {"type": "heading", "text": {"bn": "১১ ও ১২ জিলহজ: আইয়ামে তাশরিক", "en": "11 and 12 Dhul Hijjah: days of Tashriq"}}, {"type": "step", "title": {"bn": "মিনায় রাত যাপন", "en": "Nights in Mina"}, "text": {"bn": "১১ ও ১২ তারিখের রাত (অধিকাংশ সময়) মিনায় কাটাবেন।", "en": "Spend (most of) the nights of the 11th and 12th in Mina."}}, {"type": "step", "title": {"bn": "তিন জামরায় কংকর", "en": "Stone the three jamarat"}, "text": {"bn": "জাওয়ালের (দুপুরের) পর প্রথমে ছোট জামরা (জামরাতুল উলা), তারপর মধ্যম (উসতা), তারপর বড় (আকাবা) — প্রতিটিতে সাতটি করে কংকর, প্রতিবার ''আল্লাহু আকবার''।", "en": "After zawal (midday), stone first the small jamrah (Ula), then the middle (Wusta), then the big (Aqabah), seven pebbles each, saying ''Allahu akbar'' each time."}}, {"type": "step", "title": {"bn": "দোয়া", "en": "Dua"}, "text": {"bn": "ছোট ও মধ্যম জামরায় কংকর মারার পর একটু সরে কিবলামুখী হয়ে হাত তুলে দীর্ঘ সময় দোয়া করুন। বড় জামরার পর দোয়ার জন্য না দাঁড়িয়ে চলে যান।", "en": "After the small and middle jamrah, step aside, face the qiblah, raise your hands and make a long dua. After the big jamrah, leave without stopping for dua."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি (ইবনে উমর রা.-এর বর্ণনা: প্রতি কংকরে তাকবির ও প্রথম দুই জামরার পর দোয়া)", "en": "Sahih al-Bukhari (Ibn Umar: takbir with each pebble and dua after the first two jamarat)"}, "check": true}, {"type": "differ", "title": {"bn": "মিনায় রাত যাপনের হুকুম", "en": "Ruling on staying the nights in Mina"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "সুন্নত; ছেড়ে দিলে দম নেই, তবে বিনা কারণে ছাড়া মাকরুহ।", "en": "Sunnah; no dam if missed, but missing it without reason is disliked."}, "evidence": {"bn": "নবী (সা.) আব্বাস (রা.)-কে হাজিদের পানি পান করানোর জন্য মক্কায় রাত কাটানোর অনুমতি দিয়েছিলেন।", "en": "The Prophet allowed Abbas to spend the nights in Makkah to provide water for the pilgrims."}}, {"label": {"bn": "শাফেয়ি, মালেকি, হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "ওয়াজিব; বিনা ওজরে ছাড়লে দম বা সদকা।", "en": "Obligatory; missing it without excuse requires a dam or charity."}, "evidence": {"bn": "আব্বাস (রা.)-কে আলাদাভাবে অনুমতি দেওয়াই প্রমাণ করে যে অন্যদের জন্য এটি জরুরি।", "en": "Giving Abbas a special permission shows it is required of others."}}]}, {"type": "heading", "text": {"bn": "১২ বা ১৩ তারিখে মিনা ত্যাগ", "en": "Leaving Mina on the 12th or 13th"}}, {"type": "arabic", "ar": "فَمَنْ تَعَجَّلَ فِي يَوْمَيْنِ فَلَا إِثْمَ عَلَيْهِ وَمَنْ تَأَخَّرَ فَلَا إِثْمَ عَلَيْهِ لِمَنِ اتَّقَىٰ", "pron": {"bn": "ফামান তাআজ্জালা ফী ইয়াওমাইনি ফালা ইসমা আলাইহি, ওয়া মান তাআখখারা ফালা ইসমা আলাইহি লিমানিত্তাকা", "en": "Faman ta''ajjala fi yawmayni fala ithma ''alayh, wa man ta''akhkhara fala ithma ''alayh, limanittaqa"}, "meaning": {"bn": "যে দুই দিনে তাড়াতাড়ি চলে যায়, তার কোনো গুনাহ নেই; আর যে দেরি করে, তারও কোনো গুনাহ নেই — যে তাকওয়া অবলম্বন করে তার জন্য।", "en": "Whoever hastens in two days, there is no sin on him; and whoever delays, there is no sin on him — for one who is mindful of Allah."}, "ref": {"bn": "সূরা বাকারা ২:২০৩", "en": "Al-Baqarah 2:203"}}, {"type": "text", "text": {"bn": "১২ তারিখে কংকর মারার পর সূর্যাস্তের আগে মিনা ছেড়ে যেতে পারেন। মিনায় থাকা অবস্থায় সূর্য ডুবে গেলে ১৩ তারিখও থেকে তিন জামরায় কংকর মারা উত্তম (হানাফি মতে ১৩ তারিখের সুবহে সাদিকের আগে চলে যাওয়া জায়েজ, তবে মাকরুহ; অন্য মাজহাবে সূর্যাস্তের পর থেকে যাওয়া আবশ্যক)।", "en": "After stoning on the 12th you may leave Mina before sunset. If the sun sets while you are still in Mina, it is better to stay the 13th and stone the three jamarat (Hanafis allow leaving before dawn of the 13th, though disliked; the other schools require staying once the sun has set)."}}, {"type": "note", "tone": "warn", "text": {"bn": "কংকর মারা নিজেকেই করতে হবে। অসুস্থ, অতি বৃদ্ধ বা প্রকৃত অক্ষম হলে অন্য কাউকে প্রতিনিধি বানানো যায়, যিনি আগে নিজের কংকর মেরে তারপর তার পক্ষ থেকে মারবেন। শুধু ভিড় এড়াতে সুস্থ ব্যক্তির প্রতিনিধি দেওয়া জায়েজ নয়।", "en": "You must do the stoning yourself. The sick, very elderly or truly unable may appoint someone, who first stones for himself and then for them. A healthy person may not delegate just to avoid the crowd."}}, {"type": "heading", "text": {"bn": "বিদায়ী তাওয়াফ (তাওয়াফুল বিদা)", "en": "The farewell tawaf (tawaf al-wada'')"}}, {"type": "text", "text": {"bn": "মক্কা ছেড়ে নিজ দেশে ফেরার আগে বাইরের হাজিদের শেষ কাজ হবে বায়তুল্লাহর তাওয়াফ। এটি হানাফি, শাফেয়ি ও হাম্বলি মতে ওয়াজিব (মালেকি মতে সুন্নত)। হায়েজ-নিফাস অবস্থায় থাকা নারীদের জন্য এটি মাফ।", "en": "Before leaving Makkah for home, the last act of pilgrims from outside is a tawaf of the House. It is obligatory for Hanafis, Shafi''is and Hanbalis (sunnah for Malikis). Women in menstruation or post-natal bleeding are excused from it."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৭৫৫; সহিহ মুসলিম ১৩২৮", "en": "Sahih al-Bukhari 1755; Sahih Muslim 1328"}}]', 'in_review', 50 FROM is_guide_topics WHERE slug = 'hajj' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'fc704b4d-be52-5855-b12a-8ea631437225', id, 'hajj-farz-wajib-sunnah', '{"bn": "হজের ফরজ, ওয়াজিব ও সুন্নত", "en": "Farz, wajib and sunnah acts of hajj"}', '{"bn": "কোন কাজ ছুটলে হজ হবে না, কোনটায় দম লাগবে, আর কোনটা সুন্নত; মাজহাবগুলোর পার্থক্যসহ।", "en": "Which omissions invalidate hajj, which need a dam, and which are sunnah; with the differences between schools."}', 'detail', '[{"type": "text", "text": {"bn": "হজের কাজগুলো তিন স্তরের। ফরজ বা রুকন ছুটে গেলে হজ হবে না। ওয়াজিব ছুটে গেলে হজ হবে, তবে দম (একটি পশু কুরবানি) দিতে হবে। সুন্নত ছুটলে দম নেই, তবে সওয়াব কমে।", "en": "The acts of hajj have three levels. If a farz (pillar) is missed, the hajj is not valid. If a wajib is missed, the hajj is valid but a dam (animal sacrifice) is due. If a sunnah is missed, there is no penalty but reward is lost."}}, {"type": "heading", "text": {"bn": "হানাফি মাজহাব অনুযায়ী", "en": "According to the Hanafi school"}}, {"type": "table", "head": [{"bn": "স্তর", "en": "Level"}, {"bn": "কাজ", "en": "Acts"}], "rows": [[{"bn": "ফরজ", "en": "Farz"}, {"bn": "১. ইহরাম (শর্ত) ২. ৯ জিলহজ জাওয়াল থেকে ১০ তারিখের সুবহে সাদিকের মধ্যে আরাফায় অবস্থান ৩. তাওয়াফে জিয়ারত", "en": "1. Ihram (a condition) 2. Being at Arafah between zawal on the 9th and dawn on the 10th 3. Tawaf al-ziyarah"}], [{"bn": "ওয়াজিব", "en": "Wajib"}, {"bn": "মিকাত থেকে ইহরাম; দিনে পৌঁছালে সূর্যাস্ত পর্যন্ত আরাফায় থাকা; মুজদালিফায় অবস্থান; সাফা-মারওয়ার সাঈ; কংকর মারা; মুণ্ডন বা চুল ছোট করা; তামাত্তু-কিরানে কুরবানি ও ১০ তারিখের ক্রম; নির্দিষ্ট সময়ে তাওয়াফে জিয়ারত; বাইরের হাজির জন্য বিদায়ী তাওয়াফ", "en": "Ihram from the miqat; staying at Arafah till sunset if arrived by day; Muzdalifah; sa''i between Safa and Marwah; stoning; shaving or shortening; sacrifice and the order of the 10th for tamattu''/qiran; tawaf al-ziyarah in its time; farewell tawaf for those from outside"}], [{"bn": "সুন্নত (কয়েকটি)", "en": "Sunnah (some)"}, {"bn": "ইহরামের গোসল; ইফরাদ ও কিরানে তাওয়াফে কুদুম; ৮ তারিখ মিনায় রাত যাপন; মুজদালিফায় রাত যাপন; মিনায় তাশরিকের রাতগুলো কাটানো; প্রথম তিন চক্করে রমল ও ইজতিবা (পুরুষ)", "en": "Ghusl for ihram; tawaf al-qudum in ifrad and qiran; the night of the 8th in Mina; the night in Muzdalifah; the nights of Tashriq in Mina; ramal and idtiba'' in the first three rounds (men)"}]]}, {"type": "differ", "title": {"bn": "হজের রুকন কয়টি", "en": "How many pillars does hajj have"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "রুকন দুটি: আরাফায় অবস্থান ও তাওয়াফে জিয়ারত; ইহরাম শর্ত। সাঈ ওয়াজিব।", "en": "Two pillars: standing at Arafah and tawaf al-ziyarah; ihram is a condition. Sa''i is wajib."}, "evidence": {"bn": "হাদিস: ''হজ হলো আরাফা''; আয়াত: ''তারা যেন প্রাচীন ঘরের তাওয়াফ করে'' (২২:২৯)। সাঈর আয়াতে ''কোনো দোষ নেই'' বলা হয়েছে, যা রুকন হওয়ার ইঙ্গিত দেয় না।", "en": "Hadith: ''Hajj is Arafah''; verse: ''let them circle the Ancient House'' (22:29). The sa''i verse says ''there is no blame'', which does not indicate a pillar."}}, {"label": {"bn": "শাফেয়ি", "en": "Shafi''i"}, "text": {"bn": "রুকন ছয়টি: ইহরাম, আরাফায় অবস্থান, তাওয়াফে ইফাদা, সাঈ, মুণ্ডন/চুল ছোট করা, এবং বেশির ভাগ রুকনে ক্রম।", "en": "Six pillars: ihram, Arafah, tawaf al-ifadah, sa''i, shaving/shortening, and order among most of them."}, "evidence": {"bn": "নবী (সা.)-এর আমল ও নির্দেশ, এবং মুসনাদে আহমাদের হাদিস: ''আল্লাহ তোমাদের ওপর সাঈ নির্ধারণ করেছেন, তাই সাঈ করো।''", "en": "The Prophet''s practice and command, and the hadith in Musnad Ahmad: ''Allah has prescribed sa''i for you, so do sa''i.''"}}, {"label": {"bn": "মালেকি ও হাম্বলি", "en": "Maliki and Hanbali"}, "text": {"bn": "রুকন চারটি: ইহরাম, আরাফায় অবস্থান, তাওয়াফে ইফাদা ও সাঈ।", "en": "Four pillars: ihram, Arafah, tawaf al-ifadah and sa''i."}, "evidence": {"bn": "একই দলিল; মুণ্ডনকে তারা ওয়াজিব গণ্য করেন, রুকন নয়।", "en": "The same evidence; they count shaving as wajib, not a pillar."}}]}, {"type": "ref", "text": {"bn": "জামে তিরমিজি ৮৮৯; সূরা হজ ২২:২৯; সূরা বাকারা ২:১৫৮", "en": "Jami'' at-Tirmidhi 889; Al-Hajj 22:29; Al-Baqarah 2:158"}}, {"type": "note", "tone": "tip", "text": {"bn": "কোনো কাজ ছুটে গেছে বা ভুল হয়েছে মনে হলে অনুমান করবেন না; সঙ্গে সঙ্গে কাফেলার আলেমকে জিজ্ঞেস করুন। দম অবশ্যই হারামের সীমার ভেতরে দিতে হয়।", "en": "If you think you missed or got something wrong, do not guess; ask your group''s scholar at once. A dam must be slaughtered within the Haram."}}]', 'in_review', 60 FROM is_guide_topics WHERE slug = 'hajj' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '5feb6ec9-fa69-5abb-af16-7dd4811b1816', id, 'hajj-women', '{"bn": "নারীদের হজ: বিশেষ বিধান", "en": "Women''s hajj: special rulings"}', '{"bn": "মাহরাম, ইহরামের পোশাক, হায়েজ অবস্থায় হজ এবং নারীদের জন্য আলাদা নিয়মগুলো।", "en": "Mahram, ihram clothing, hajj during menstruation and the rules that differ for women."}', 'basic', '[{"type": "heading", "text": {"bn": "মাহরাম", "en": "Mahram"}}, {"type": "differ", "title": {"bn": "মাহরাম ছাড়া নারীর ফরজ হজ", "en": "A woman''s obligatory hajj without a mahram"}, "views": [{"label": {"bn": "হানাফি ও হাম্বলি", "en": "Hanafi and Hanbali"}, "text": {"bn": "সফরের দূরত্বে স্বামী বা মাহরাম সঙ্গে থাকা হজ ফরজ হওয়ার (বা আদায়ের) শর্ত; মাহরাম না পেলে তার ওপর নিজে যাওয়া আবশ্যক নয়।", "en": "A husband or mahram accompanying her over the travel distance is a condition for hajj; if she finds none she is not required to go herself."}, "evidence": {"bn": "হাদিস: ''কোনো নারী মাহরাম ছাড়া সফর করবে না।'' এক সাহাবি বললেন, আমার স্ত্রী হজে যাচ্ছে; নবী (সা.) বললেন, ''যাও, তোমার স্ত্রীর সাথে হজ করো।''", "en": "Hadith: ''A woman must not travel except with a mahram.'' A man said his wife was going for hajj; the Prophet said, ''Go and perform hajj with your wife.''"}}, {"label": {"bn": "শাফেয়ি ও মালেকি", "en": "Shafi''i and Maliki"}, "text": {"bn": "ফরজ হজের জন্য নির্ভরযোগ্য নারীদের দল বা নিরাপদ কাফেলা থাকলে মাহরাম ছাড়াও যাওয়া জায়েজ।", "en": "For the obligatory hajj, she may go without a mahram in a trustworthy group of women or a safe caravan."}, "evidence": {"bn": "উমর (রা.) নবীপত্নীদের উসমান (রা.) ও আবদুর রহমান ইবনে আওফ (রা.)-এর তত্ত্বাবধানে হজে পাঠিয়েছিলেন; এবং নিরাপত্তা প্রতিষ্ঠিত হলে নারী একা হিরা থেকে কাবা পর্যন্ত সফর করবে — এ ভবিষ্যদ্বাণীর হাদিস (সহিহ বুখারি)।", "en": "Umar sent the Prophet''s wives for hajj under the care of Uthman and Abd al-Rahman ibn Awf; and the hadith foretelling that a woman would travel safely alone from Hira to the Ka''bah (Sahih al-Bukhari)."}}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৮৬২; সহিহ মুসলিম ১৩৪১", "en": "Sahih al-Bukhari 1862; Sahih Muslim 1341"}}, {"type": "heading", "text": {"bn": "ইহরামের পোশাক", "en": "Clothing in ihram"}}, {"type": "list", "items": [{"bn": "যেকোনো রঙের শালীন, ঢিলেঢালা সাধারণ পোশাক পরবেন; সাদা হওয়া জরুরি নয়।", "en": "Wear ordinary modest, loose clothes of any colour; white is not required."}, {"bn": "মুখে নিকাব (মুখের সাথে লাগানো নেকাব) ও হাতে মোজা পরবেন না; পায়ে মোজা ও জুতা পরা যায়।", "en": "Do not wear a niqab fitted to the face or gloves; socks and shoes are allowed."}, {"bn": "পরপুরুষ কাছে এলে মাথার ওপর থেকে কাপড় ঝুলিয়ে মুখ আড়াল করতে পারেন, যেমন সাহাবি নারীরা করতেন; কাপড় মুখে লেগে থাকা থেকে যথাসম্ভব বাঁচবেন।", "en": "When unrelated men come near, you may let cloth hang from the head to screen the face, as the women Companions did; try to keep it from clinging to the face."}, {"bn": "মাথার চুল সবসময় ঢাকা থাকবে; ইহরামে নারীর মাথা খোলা রাখার কোনো বিধান নেই।", "en": "The hair stays covered at all times; there is no rule for a woman to uncover her head in ihram."}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৮৩৮", "en": "Sahih al-Bukhari 1838"}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ (আয়েশা রা.-এর বর্ণনা: কাফেলা কাছে এলে মুখের ওপর কাপড় ঝুলিয়ে দেওয়া)", "en": "Sunan Abi Dawud (Aishah: lowering cloth over the face when riders passed)"}, "check": true}, {"type": "heading", "text": {"bn": "হায়েজ বা নিফাস অবস্থায়", "en": "During menstruation or post-natal bleeding"}}, {"type": "list", "items": [{"bn": "ইহরাম বাঁধা যায় (গোসল করে নিয়ত ও তালবিয়া), শুধু ইহরামের নামাজ পড়বেন না।", "en": "She may enter ihram (ghusl, intention and talbiyah), only without the ihram prayer."}, {"bn": "আরাফা, মুজদালিফা, মিনা, কংকর মারা, দোয়া-জিকির সবই করবেন; শুধু পবিত্র না হওয়া পর্যন্ত তাওয়াফ করবেন না এবং মসজিদে প্রবেশ করবেন না।", "en": "She does everything — Arafah, Muzdalifah, Mina, stoning, dua and dhikr — except tawaf and entering the masjid until she is pure."}, {"bn": "তাওয়াফে জিয়ারত পবিত্র হওয়ার পর করবেন; এর জন্য দেরি হলে কোনো দম নেই।", "en": "She performs tawaf al-ifadah after becoming pure; there is no penalty for the delay."}, {"bn": "দেশে ফেরার আগে পবিত্র না হলে বিদায়ী তাওয়াফ তার জন্য মাফ।", "en": "If she is not pure before leaving for home, the farewell tawaf is waived for her."}, {"bn": "তামাত্তুর উমরাহ শেষ করার আগে হায়েজ শুরু হলে এবং ৮ তারিখের আগে পবিত্র না হলে আলেমের পরামর্শে হজের নিয়ত যোগ করবেন (কিরানে রূপান্তর বা অন্য বিধান মাজহাব অনুযায়ী ভিন্ন)।", "en": "If her period starts before finishing the tamattu'' umrah and she is not pure by the 8th, she adds the hajj intention on a scholar''s advice (converting to qiran or another ruling, depending on the school)."}, {"bn": "তাওয়াফে জিয়ারত না করে দেশে ফিরে যাওয়ার পরিস্থিতি হলে অবশ্যই আলেমের সাথে পরামর্শ করবেন; এটি হজের রুকন।", "en": "If she faces having to leave without tawaf al-ifadah, she must consult a scholar; it is a pillar of hajj."}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৩০৫; সহিহ বুখারি ১৭৫৫", "en": "Sahih al-Bukhari 305; Sahih al-Bukhari 1755"}}, {"type": "note", "tone": "info", "text": {"bn": "স্বাস্থ্যের ক্ষতি না হলে চিকিৎসকের পরামর্শে ওষুধ খেয়ে হজের সময় মাসিক পিছিয়ে রাখা অনেক আলেমের মতে জায়েজ।", "en": "Many scholars allow delaying the period during hajj with medicine on a doctor''s advice, if it causes no harm."}}, {"type": "heading", "text": {"bn": "অন্যান্য পার্থক্য", "en": "Other differences"}}, {"type": "list", "items": [{"bn": "তালবিয়া নিচু স্বরে পড়বেন, যাতে শুধু নিজে বা পাশের জন শোনে।", "en": "Say the talbiyah quietly, so only you or the person beside you hears."}, {"bn": "তাওয়াফে রমল (দ্রুত হাঁটা) ও ইজতিবা নেই; সাঈতে সবুজ বাতির মাঝে দৌড়াবেন না।", "en": "No ramal or idtiba'' in tawaf; do not jog between the green lights in sa''i."}, {"bn": "মাথা মুণ্ডন করবেন না; সব চুলের আগা থেকে আঙুলের এক কর (প্রায় এক ইঞ্চি) পরিমাণ কাটবেন।", "en": "Do not shave the head; cut about a fingertip''s length (about an inch) from the ends of the hair."}, {"bn": "ভিড়ের মধ্যে হাজরে আসওয়াদ চুম্বন করতে যাবেন না; দূর থেকে ইশারা করাই যথেষ্ট।", "en": "Do not push into crowds to kiss the Black Stone; pointing from a distance is enough."}, {"bn": "ইদ্দত পালনরত নারী সেই সময়ে হজে যাবেন না।", "en": "A woman in her ''iddah does not set out for hajj during it."}]}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ (নারীদের জন্য মুণ্ডন নয়, চুল ছোট করা)", "en": "Sunan Abi Dawud (women shorten the hair rather than shave)"}, "check": true}]', 'in_review', 70 FROM is_guide_topics WHERE slug = 'hajj' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'b56a8f63-7058-58e7-bc47-470a306539f8', id, 'hajj-mistakes', '{"bn": "হজে যে ভুলগুলো এড়িয়ে চলবেন", "en": "Mistakes to avoid in hajj"}', '{"bn": "হাজিদের মধ্যে প্রচলিত কিছু ভুল, যা হজের ক্ষতি করে বা অন্যকে কষ্ট দেয়।", "en": "Common mistakes among pilgrims that harm the hajj or hurt others."}', 'basic', '[{"type": "list", "items": [{"bn": "ইহরাম ছাড়া মিকাত পার হওয়া, যেমন জেদ্দায় পৌঁছে ইহরাম বাঁধা।", "en": "Crossing the miqat without ihram, e.g. entering ihram only on landing in Jeddah."}, {"bn": "পুরো ইহরামের সময় ডান কাঁধ খোলা রাখা। ইজতিবা শুধু সাঈযুক্ত তাওয়াফের সময়; নামাজে কাঁধ ঢেকে রাখবেন।", "en": "Keeping the right shoulder bare throughout ihram. Idtiba'' is only during a tawaf followed by sa''i; cover the shoulder in prayer."}, {"bn": "তাওয়াফের প্রতিটি চক্করের জন্য বই থেকে নির্দিষ্ট দোয়া পড়া জরুরি মনে করা; এমন নির্দিষ্ট দোয়া হাদিসে নেই। নিজের ভাষায় দোয়া করুন।", "en": "Believing a set dua from a booklet is required for each round of tawaf; no such set duas exist in the hadith. Pray in your own words."}, {"bn": "দলবদ্ধভাবে চিৎকার করে দোয়া পড়ে অন্যের মনোযোগ নষ্ট করা।", "en": "Reciting duas loudly in groups and disturbing others."}, {"bn": "হাজরে আসওয়াদ চুম্বনের জন্য ধাক্কাধাক্কি করা; এটি সুন্নত, কিন্তু মানুষকে কষ্ট দেওয়া হারাম।", "en": "Pushing to kiss the Black Stone; kissing it is sunnah, but hurting people is haram."}, {"bn": "হাতিম (হিজরে ইসমাইল)-এর ভেতর দিয়ে তাওয়াফ করা; এটি কাবার অংশ, তাই এর বাইরে দিয়ে ঘুরতে হবে।", "en": "Doing tawaf through the Hatim (Hijr Isma''il); it is part of the Ka''bah, so go around outside it."}, {"bn": "সূর্যাস্তের আগে আরাফা ত্যাগ করা বা আরাফার সীমার বাইরে অবস্থান করা।", "en": "Leaving Arafah before sunset or staying outside its boundary."}, {"bn": "জাবালে রহমতে ওঠা, পাথর স্পর্শ বা সেখানে নামাজ পড়াকে জরুরি মনে করা।", "en": "Thinking it necessary to climb Jabal ar-Rahmah, touch its rocks or pray there."}, {"bn": "বড় পাথর, জুতা বা স্যান্ডেল দিয়ে জামরায় মারা, বা জামরাকে শয়তান ভেবে গালি দেওয়া। ছোট কংকরই সুন্নত; উদ্দেশ্য আল্লাহর জিকির।", "en": "Throwing large stones, shoes or sandals at the jamarat, or cursing them as if they were Satan. Small pebbles are the sunnah; the purpose is remembrance of Allah."}, {"bn": "সুস্থ থাকা সত্ত্বেও কংকর মারার জন্য অন্যকে প্রতিনিধি বানানো।", "en": "Appointing someone else to stone while healthy."}, {"bn": "মাথার কয়েকটি চুল কেটে ইহরাম খুলে ফেলা। হানাফি মতে মাথার অন্তত এক-চতুর্থাংশের চুল ছোট করতে হয়, অন্যদের মতে পুরো বা বেশির ভাগ মাথার; পুরো মাথা মুণ্ডন বা পুরো মাথা থেকে ছোট করাই নিরাপদ।", "en": "Cutting a few hairs and leaving ihram. Hanafis require at least a quarter of the head, others the whole or most of it; shaving or shortening the whole head is safest."}, {"bn": "নামাজের সময় ছবি তোলা, ভিডিও করা ও সেলফিতে ব্যস্ত থাকা; এতে ইবাদতের একাগ্রতা নষ্ট হয়।", "en": "Being busy with photos, videos and selfies in worship; it destroys focus."}, {"bn": "ঝগড়া, গিবত ও অন্য হাজির সাথে খারাপ আচরণ; এগুলো হজের সওয়াব নষ্ট করে।", "en": "Quarrelling, backbiting and mistreating fellow pilgrims; these spoil the reward of hajj."}]}, {"type": "note", "tone": "tip", "text": {"bn": "সন্দেহ হলে অনুমান না করে নির্ভরযোগ্য আলেমকে জিজ্ঞেস করুন। ধৈর্য ও নম্রতা হজের বড় শিক্ষা।", "en": "When in doubt, ask a reliable scholar instead of guessing. Patience and gentleness are among the great lessons of hajj."}}]', 'in_review', 80 FROM is_guide_topics WHERE slug = 'hajj' ON CONFLICT (slug) DO NOTHING;
